// current site) first, then each route hazard in travel order, then landing
// assist (arriving at the final destination) last. Each item carries
// segIndex - the turn1Segs index whose arrival resolves it (liftoff -> 0,
// landing -> the last index) - so the hazard stepper can group items that
// share an arrival and split the route at the boundaries between them.
// `liftoffAssist` / `landingAssist` are null or {site, glyph, label},
// already gated by the caller (needsRoll, not colony-waived).
function buildOrderedHazardItems({ turn1Segs, hz, curSite, safeAeroOnline, liftoffAssist, landingAssist, liftoffAssistActive }) {
  const items = [];
  if (liftoffAssist) items.push({ ...liftoffAssist, segIndex: 0 });
  // H6c Crash Hazard: a factory-assist liftoff ignores the hazard on the FIRST
  // space it moves into (turn1Segs[0].to). Mirror of the server; the assist's own
  // roll (liftoffAssist) is separately gated on colony / Powersat. NEVER waives a
  // lander-burn (or half-lander-burn) space: factory-assist can't carry a
  // maneuver into a lander burn, so a Hazard on one always rolls (mirror of the
  // engine's isLanderBurnNode gate). (User 2026-07-19: Triton + a couple sites.)
  const crashSpaceId = (liftoffAssistActive && curSite && turn1Segs && turn1Segs.length) ? turn1Segs[0].to : null;
  for (const h of hz) {
    if (h.site.type === 'radhaz') continue;
    if (safeAeroOnline && h.aero) continue;
    if (crashSpaceId && h.site.id === crashSpaceId && !isLanderBurnNodeClient(plannerIdToSlug(h.site.id))) continue;
    if (liftoffColonyWaives(curSite, h.site)) continue;
    const segIndex = turn1Segs.findIndex((s) => s.to === h.site.id);
    if (segIndex < 0) continue;
    items.push({ site: h.site, glyph: h.glyph, label: h.label, aero: !!h.aero, segIndex });
  }
  if (landingAssist) items.push({ ...landingAssist, segIndex: turn1Segs.length - 1 });
  // Stable sort: items already pushed in chronological order, so a tie
  // (liftoff assist AND a route hazard both resolving at segment 0) keeps
  // liftoff first - you can't even attempt the hop without clearing it.
  items.sort((a, b) => a.segIndex - b.segIndex);
  return items;
}

// Once-per-turn flag: a move that was paid-out or rolled for at
// a hazard cannot be undone. Persisted so a reload mid-turn
// preserves the lockout; cleared on end-turn via onTurnChange.
const STORAGE_HAZARDOUS_MOVE = 'hf-sandbox-hazardous-move';
let _lastMoveHazardous = (() => {
  try { return localStorage.getItem(STORAGE_HAZARDOUS_MOVE) === '1'; }
  catch { return false; }
})();
function setHazardousMove(on) {
  _lastMoveHazardous = !!on;
  try {
    if (_lastMoveHazardous) localStorage.setItem(STORAGE_HAZARDOUS_MOVE, '1');
    else                    localStorage.removeItem(STORAGE_HAZARDOUS_MOVE);
  } catch { /* private mode */ }
}
// End-of-turn always clears the lockout - a fresh turn refunds
// the move budget too, but the hazardous flag stays scoped to
// the turn that flew through the hazard.
onTurnChange(() => {
  if (getMovesRemaining() > 0 && _lastMoveHazardous) setHazardousMove(false);
});

// Hazard-list modal for the "your route crosses hazards" prompt. Resolves to
// one of:
//   'pay'      - player pays HAZARD_COST_PER × N aqua to bypass every hazard
//   'roll'     - player rolls a d6 per hazard, no undo allowed
//   'stepwise' - (only when opts.allowStepwise) walk the hazards one at a
//                time, choosing pay / roll / stop per hazard - see
//                runHazardStepper. Only offered for the rocket's own route
//                (the reported pain point); freighter/Bernal callers keep
//                the plain pay-all/roll-all choice.
//   'cancel'   - back to planning; move not consumed
// Pay button is disabled (but still rendered, with a help line)
// when the balance can't cover the bill. The wording leans hard
// on "cannot be undone" because the rulebook commits the dice as
// soon as they hit the table - same idiom here.
function hazardConfirmModal(hazards, { allowStepwise = false } = {}) {
  return new Promise((resolve) => {
    document.querySelector('.confirm-modal-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay hazard-confirm-overlay';
    const close = (val) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(val);
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close('cancel'); });
    const onKey = (e) => {
      if (e.key === 'Escape') close('cancel');
    };
    document.addEventListener('keydown', onKey);

    const n = hazards.length;
    const cost = n * finaoPer();
    const have = getAqua();
    const canPay = have >= cost;
    const list = hazards.map((h, i) =>
      `<li><span class="haz-order">${i + 1}.</span> <span class="haz-glyph">${h.glyph}</span> `
      + `${esc(h.site.name || h.label)} <em class="muted">${esc(h.label)}</em></li>`
    ).join('');

    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel hazard-confirm-panel';
    panel.innerHTML = `
      <h3>⚠ Hazard zone ahead</h3>
      <p>Your planned route passes through
        <strong>${n}</strong> hazard${n === 1 ? '' : 's'}, in order:</p>
      <ul class="hazard-list">${list}</ul>
      <p class="hazard-warning">
        <strong>A paid or rolled hazard CANNOT be undone</strong>
        - hazard rolls and aqua spends commit the moment the dice
        leave the cup. End the turn to clear the lockout.
      </p>
      <div class="hazard-cost-row">
        <span>💎 Aqua balance: <strong>${have}</strong></span>
        <span>Cost to pay all: <strong>${cost}</strong>
          <em class="muted">(${finaoPer()}/hazard)</em></span>
      </div>
      <div class="turn-confirm-actions hazard-actions">
        <button type="button" class="popup-btn primary" data-act="pay"
          ${canPay ? '' : 'disabled'}
          title="${canPay ? 'Spend ' + cost + ' aqua to skip every roll' : 'Not enough aqua to bypass all hazards'}">
          💎 Pay all now (${cost} aqua)
        </button>
        <button type="button" class="popup-btn" data-act="roll"
          title="Roll a d6 for each hazard. 1 destroys the rocket. Cannot be undone.">
          🎲 Roll all now (${n} d6, 1 = boom)
        </button>
        ${allowStepwise ? `<button type="button" class="popup-btn" data-act="stepwise"
          title="Decide pay, roll, or stop separately for each hazard, in order.">
          ▶ Decide as I go
        </button>` : ''}
        <button type="button" class="popup-btn" data-act="cancel"
          title="Return to planning; no move spent">
          ✕ Cancel move
        </button>
      </div>
      ${canPay ? '' : '<p class="muted hazard-need-aqua">Pay all disabled - need '
        + (cost - have) + ' more aqua. Roll, decide as you go, or cancel instead.</p>'}
    `;
    for (const b of panel.querySelectorAll('button[data-act]')) {
      b.addEventListener('click', () => close(b.dataset.act));
    }
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

// "Decide as I go": ordered per-hazard step modal. Shows the CURRENT group
// (one or more hazards that resolve at the same arrival, so they must be
// decided together), where the ship would be standing, and how many more
// groups remain. Resolves to:
//   ['pay'|'roll', ...]  - one choice per item in this group, then continue
//   'stop'               - end the route here (only offered when stopOffered)
//   'cancel'/null        - abort the whole move
function hazardStepModal({ group, groupNumber, totalGroups, atSiteLabel, stopOffered, costPer, aquaLeft }) {
  return new Promise((resolve) => {
    document.querySelector('.hazard-step-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay hazard-step-overlay';
    const close = (val) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(val);
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close('cancel'); });
    const onKey = (e) => { if (e.key === 'Escape') close('cancel'); };
    document.addEventListener('keydown', onKey);

    const choices = group.items.map(() => 'roll');   // per-item toggle state, default roll (free)
    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel hazard-confirm-panel hazard-step-panel';
    const rows = group.items.map((h, i) => `
      <li class="hazard-step-row" data-i="${i}">
        <span class="haz-glyph">${h.glyph}</span>
        <span class="hazard-step-name">${esc(h.site.name || h.label)} <em class="muted">${esc(h.label)}</em></span>
        <span class="hazard-step-toggle">
          <button type="button" class="popup-btn small" data-pick="pay" data-i="${i}">💎 Pay</button>
          <button type="button" class="popup-btn small is-active" data-pick="roll" data-i="${i}">🎲 Roll</button>
        </span>
      </li>`).join('');
    panel.innerHTML = `
      <h3>⚠ Hazard ${groupNumber} of ${totalGroups}</h3>
      <p class="muted">Currently at <strong>${esc(atSiteLabel)}</strong>.</p>
      <ul class="hazard-list hazard-step-list">${rows}</ul>
      <p class="hazard-cost-row"><span id="hz-step-cost"></span></p>
      <div class="turn-confirm-actions hazard-actions">
        <button type="button" class="popup-btn primary" data-act="go">▶ Keep going</button>
        ${stopOffered ? `<button type="button" class="popup-btn" data-act="stop"
          title="End the move here. Nothing is spent or rolled for the hazards ahead.">
          🛑 Stop here
        </button>` : ''}
        <button type="button" class="popup-btn" data-act="cancel"
          title="Abort the whole move - nothing spent or rolled, even for hazards already agreed">
          ✕ Cancel move
        </button>
      </div>
    `;
    const costEl = panel.querySelector('#hz-step-cost');
    const syncCost = () => {
      const paidN = choices.filter((c) => c === 'pay').length;
      const cost = paidN * costPer;
      const over = cost > aquaLeft;
      costEl.innerHTML = paidN
        ? `💎 This step costs <strong>${cost}</strong> aqua (${aquaLeft} left after prior steps)`
          + (over ? ' <strong style="color:#f87171">- not enough aqua left</strong>' : '')
        : '🎲 Rolling every hazard in this step (free).';
      const go = panel.querySelector('button[data-act="go"]');
      if (go) go.disabled = over;
    };
    panel.querySelectorAll('.hazard-step-toggle button[data-pick]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const i = Number(btn.dataset.i);
        choices[i] = btn.dataset.pick;
        panel.querySelectorAll(`button[data-pick][data-i="${i}"]`).forEach((b) => {
          b.classList.toggle('is-active', b.dataset.pick === choices[i]);
        });
        syncCost();
      });
    });
    syncCost();
    panel.querySelector('button[data-act="go"]').addEventListener('click', () => close(choices.slice()));
    panel.querySelector('button[data-act="stop"]')?.addEventListener('click', () => close('stop'));
    panel.querySelector('button[data-act="cancel"]').addEventListener('click', () => close('cancel'));
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

// Orchestrates "decide as I go": groups the ordered hazard `items` by their
// shared arrival point (segIndex), merges forward past any node that isn't
// safe to halt on (a lander-burn pad - H6c), then walks the groups asking
// pay/roll/stop.
//
// Nothing is charged or rolled during this wizard - the server never allows
// undoing a rolled hazard, so incrementally submitting (and maybe reverting)
// REAL rolls isn't safe. Deciding the whole plan first, then making the one
// real MOVE submission, is the only way to offer a genuine "stop here,
// nothing spent past this point" bail-out. Returns { uptoSegIndex, choices }
// (choices aligned to items[0..uptoSegIndex]) or null if the player backs
// out of the whole move.
async function runHazardStepper(items, { turn1Segs, netThrust }) {
  const groups = [];
  for (const it of items) {
    const last = groups[groups.length - 1];
    if (last && last.segIndex === it.segIndex) last.items.push(it);
    else groups.push({ segIndex: it.segIndex, items: [it] });
  }
  // Merge a group's stop point forward into the next one whenever it isn't a
  // clean, free halt: a lander-burn pad (H6c - "cannot halt on a lander
  // burn"), or a site that would itself need its own factory-assist roll to
  // land on (kept out of "Stop here" so stopping never opens a NEW hazard
  // decision of its own - it's always a plain, unconditional halt). If the
  // very last group still isn't clean, "Stop here" simply never appears
  // there - that node is the move's real destination either way, already
  // validated (and its landing-assist item, if any, already in the list).
  const needsMerge = (groupIdx) => {
    const stopPlannerId = turn1Segs[groups[groupIdx].segIndex].to;
    if (isLanderBurnNodeClient(plannerIdToSlug(stopPlannerId))) return true;
    const stopSite = _activeData.byId?.[stopPlannerId] || _activeData.sites.find((s) => s.id === stopPlannerId);
    if (!stopSite) return false;   // a plain waypoint - always a clean, free halt
    const g = maneuverGate(stopSite, netThrust);
    return !g.ok || !!g.needsRoll;
  };
  for (let i = 0; i < groups.length - 1; i++) {
    if (!needsMerge(i)) continue;
    groups[i + 1].items = groups[i].items.concat(groups[i + 1].items);
    groups.splice(i, 1);
    i -= 1;
  }
  const choices = [];
  let committedSegIndex = -1;
  for (let g = 0; g < groups.length; g++) {
    const group = groups[g];
    const atSiteLabel = committedSegIndex < 0
      ? 'your current position'
      : ((_activeData.byId?.[turn1Segs[committedSegIndex].to] || {}).name || 'the last stop');
    const pick = await hazardStepModal({
      group, groupNumber: g + 1, totalGroups: groups.length, atSiteLabel,
      stopOffered: g > 0,
      costPer: finaoPer(),
      aquaLeft: getAqua() - choices.filter((c) => c === 'pay').length * finaoPer(),
    });
    if (pick === 'stop') {
      return committedSegIndex >= 0 ? { uptoSegIndex: committedSegIndex, choices } : null;
    }
    if (pick === 'cancel' || pick == null) return null;
    choices.push(...pick);
    committedSegIndex = group.segIndex;
  }
  return { uptoSegIndex: committedSegIndex, choices };
}

// Factory-assist confirm. Surfaces when a land / liftoff maneuver is
// under-thrust (net thrust <= site size) but a factory at the site
// can carry it. Each such maneuver is a hazard roll; the player may
// pay FINAO (aqua, like the hazard bypass) to guarantee them all,
// roll the dice (a 1 destroys the rocket), or cancel. Colony-waived
// maneuvers never reach this modal. Resolves 'pay' | 'roll' | 'cancel'.
function factoryAssistModal(maneuvers, netThrust) {
  return new Promise((resolve) => {
    document.querySelector('.confirm-modal-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay hazard-confirm-overlay';
    const close = (val) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(val);
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close('cancel'); });
    const onKey = (e) => { if (e.key === 'Escape') close('cancel'); };
    document.addEventListener('keydown', onKey);

    const n = maneuvers.length;
    const cost = n * finaoPer();
    const have = getAqua();
    const canPay = have >= cost;
    const list = maneuvers.map((m) =>
      `<li><span class="haz-glyph">🏭</span> `
      + `${esc(m.kind === 'liftoff' ? 'Lift off from' : 'Land on')} `
      + `<strong>${esc(m.site.name || m.site.id)}</strong> `
      + `<em class="muted">net thrust ${netThrust} ≤ size ${m.size}</em></li>`
    ).join('');

    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel hazard-confirm-panel';
    panel.innerHTML = `
      <h3>🏭 Factory assist required</h3>
      <p>Your thrust can't manage ${n === 1 ? 'this maneuver' : 'these maneuvers'} alone,
        but a factory can carry ${n === 1 ? 'it' : 'them'} as a hazard roll:</p>
      <ul class="hazard-list">${list}</ul>
      <p class="hazard-warning">
        <strong>Whatever you pick, this move CANNOT be undone.</strong>
        End the turn to clear the lockout.
      </p>
      <div class="hazard-cost-row">
        <span>💎 Aqua balance: <strong>${have}</strong></span>
        <span>FINAO cost: <strong>${cost}</strong>
          <em class="muted">(${finaoPer()}/assist)</em></span>
      </div>
      <div class="turn-confirm-actions hazard-actions">
        <button type="button" class="popup-btn primary" data-act="pay"
          ${canPay ? '' : 'disabled'}
          title="${canPay ? 'Spend ' + cost + ' aqua (FINAO) to guarantee the assist' : 'Not enough aqua for FINAO'}">
          💎 Pay ${cost} aqua (FINAO)
        </button>
        <button type="button" class="popup-btn" data-act="roll"
          title="Roll a d6 for each assist. 1 destroys the rocket. Cannot be undone.">
          🎲 Roll ${n} d6 (1 = boom, no undo)
        </button>
        <button type="button" class="popup-btn" data-act="cancel"
          title="Return to planning; no move spent">
          ✕ Cancel move
        </button>
      </div>
      ${canPay ? '' : '<p class="muted hazard-need-aqua">FINAO disabled - need '
        + (cost - have) + ' more aqua. Roll or cancel instead.</p>'}
    `;
    for (const b of panel.querySelectorAll('button[data-act]')) {
      b.addEventListener('click', () => close(b.dataset.act));
    }
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

// Animated hazard-roll modal. One 3D die per hazard, rolled in
// parallel; once every die settles the player can confirm to
// apply the result (any 1 = critical, rocket explodes at that
// node). Cancel is intentionally absent - the player already
// committed to rolling in the prior confirm; this modal just
// reveals the dice.
function hazardRollModal(hazards) {
  return new Promise((resolve) => {
    document.querySelector('.hazard-roll-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay hazard-roll-overlay';
    let settled = false;
    let rolls = null;
    const close = () => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(rolls || []);
    };
    const onKey = (e) => {
      // Enter confirms once the dice have all landed - keeps
      // the modal keyboard-friendly without letting the player
      // skip past the suspense.
      if (e.key === 'Enter' && settled) { e.preventDefault(); close(); }
    };
    document.addEventListener('keydown', onKey);

    // Pre-roll every die's outcome so the visual + the logged
    // result + the explosion decision all agree.
    rolls = hazards.map((h) => ({
      site: h.site, label: h.label, glyph: h.glyph,
      d6: 1 + Math.floor(Math.random() * 6),
    }));

    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel hazard-roll-panel';
    panel.innerHTML = `
      <h3>🎲 Hazard rolls</h3>
      <p class="muted hazard-roll-sub">
        Each die rolls separately. Any <strong>1</strong>
        destroys the rocket at that hazard.
      </p>
      <ul class="hazard-roll-list"></ul>
      <p class="hazard-roll-result muted">Rolling…</p>
      <div class="turn-confirm-actions">
        <button type="button" class="popup-btn primary hazard-roll-confirm" disabled>
          Confirm result
        </button>
      </div>
    `;
    const list = panel.querySelector('.hazard-roll-list');
    const resultLine = panel.querySelector('.hazard-roll-result');
    const confirmBtn = panel.querySelector('.hazard-roll-confirm');

    // Build the rows + dice. Dice spin together; row gets
    // `is-critical` / `is-safe` once its die settles so the
    // colour band updates inline.
    const rowEls = rolls.map((r) => {
      const li = document.createElement('li');
      li.className = 'hazard-roll-row';
      li.innerHTML = `
        <div class="hazard-roll-site">
          <span class="haz-glyph">${r.glyph}</span>
          <strong>${esc(r.site.name)}</strong>
          <em class="muted">${esc(r.label)}</em>
        </div>
        <div class="hazard-roll-die-host"></div>
        <div class="hazard-roll-verdict"></div>
      `;
      list.appendChild(li);
      const dieHost = li.querySelector('.hazard-roll-die-host');
      const verdict = li.querySelector('.hazard-roll-verdict');
      const die = buildDie(1);
      dieHost.appendChild(die);
      return { row: li, die, verdict, roll: r };
    });

    overlay.appendChild(panel);
    mountOverlay(overlay);

    // Spin every die in parallel; once they all land, update
    // each row's verdict + the summary line, and arm Confirm.
    Promise.all(rowEls.map(({ die, roll }) => rollDie(die, roll.d6)))
      .then(() => {
        let criticalCount = 0;
        for (const { row, verdict, roll } of rowEls) {
          const isCrit = roll.d6 === 1;
          if (isCrit) criticalCount++;
          row.classList.add(isCrit ? 'is-critical' : 'is-safe');
          verdict.innerHTML = isCrit
            ? `<strong class="bad">✗ destroyed</strong>`
            : `<strong class="ok">✓ survived</strong>`;
        }
        if (criticalCount > 0) {
          resultLine.innerHTML = `<strong class="bad">💥 Rocket destroyed</strong> `
            + `- ${criticalCount} critical roll${criticalCount === 1 ? '' : 's'}.`;
          confirmBtn.textContent = 'Confirm - lose the rocket';
          confirmBtn.classList.add('hazard-roll-confirm-bad');
        } else {
          resultLine.innerHTML = `<strong class="ok">All survived</strong> `
            + `- continue to destination.`;
          confirmBtn.textContent = 'Confirm - continue';
        }
        resultLine.classList.remove('muted');
        settled = true;
        confirmBtn.disabled = false;
      });
    confirmBtn.addEventListener('click', () => { if (settled) close(); });
  });
}

// Rad-hardness threshold: a card on the stack survives the rad
// zone iff its rad-hard >= the rolled d6. Cards that fail are
// decommissioned to the player's hand. Per the HF4 idiom, the
// active thruster's THRUST stat can skip the test entirely -
// a fast / hot rocket outruns the radiation. Red-season raises
// the bypass bar by 2 so the Sun is harder to dodge.
const RAD_BYPASS_THRUST     = 6;
const RAD_BYPASS_THRUST_RED = 8;
// Highest face of the rad die. The worst a single zone can throw is a 6
// (plus the red-season bonus), so a card is "at risk" of being lost when
// its rad-hard plus the active thruster's FINAL thrust can't clear that
// worst case: radHard + thrust < MAX_RAD_DIE + seasonBonus.
const MAX_RAD_DIE = 6;
function radBypassThreshold() {
  let season = null;
  try { season = getSeason(); } catch { season = null; }
  return season && season.name === 'red' ? RAD_BYPASS_THRUST_RED : RAD_BYPASS_THRUST;
}

// Resolve the current rocket stack into [{id, name, radHardness}] rows for
// the rad-hardness check - used both by the upfront at-risk preview in the
// confirm modal and by the per-zone roll modal. Name + rad-hard are read off
// the INSTALLED face (the black / secondary side when a card is flipped), NOT
// the white-side default, so a flipped card is checked against its actual
// rad-hardness instead of its old white-side value. Crew live on the face too.
// L5s Cancer Hospital (promoted, anchored): "Your Crew and Human Colonists
// have a rad-hard of at least 7." Mirror of the server's
// hasPromotedCancerHospital, so the client's pre-roll at-risk warning agrees
// with what the server will actually decommission.
function myHasPromotedCancerHospital() {
  return getMyBernals().some((bn) => bn && bn.anchored && bn.cardId === 'ber_l5s_cancer_hospital'
    && (bn.promoted || bn.face === 'secondary'));
}
function radStackCards() {
  const radFloor = myHasPromotedCancerHospital();
  // V9 Sirens, "Diamonds Aren't Forever": Sirenian Crew and Colonists are
  // CONSIDERED rad-hard 0 - a read-time rule modifier, not a change to the card
  // data. Reads the SAME set the card faces draw the struck-through 0 from
  // (net-bridge#sirenRadZeroIds: a Siren's crew by owner, a colonist by which
  // queue it came out of, robots excluded), so this pre-roll at-risk warning,
  // the card face, and the server's effectiveRadHardness cannot disagree.
  return getRocketStack()
    .map((slot) => {
      const patent = PATENTS_BY_ID[slot.id];
      if (patent) {
        const face = (slot.face === 'secondary' && patent.faces && patent.faces.secondary)
          ? patent.faces.secondary : ((patent.faces && patent.faces.primary) || patent);
        // Sails (Photon Kite Sail, Photon Heliogyro, Electric Sail) are immune to
        // Belt rolls while that face is installed - a belt zone never decommissions
        // them. Read the power off the installed face's name.
        const pw = facePower(face.name);
        const immuneBelt = !!(pw && pw.immuneBelt);
        // A radiator's rad-hardness is its DEPLOYED side's (heavy is more
        // fragile); a heavy one degrades to light instead of being lost.
        if (patent.type === 'radiator') {
          return {
            id: slot.id, name: patent.name, type: 'radiator', radSide: slot.radSide || 'heavy',
            radHardness: radiatorRadHardness(face, slot.radSide), immuneBelt,
          };
        }
        let radHardness = face.radHardness != null ? face.radHardness
          : (patent.radHardness != null ? patent.radHardness : 0);
        const isHumanColonist = patent.type === 'colonist' && patent.colonistKind === 'Human';
        if (isHumanColonist && isSirenRadZero(slot.id)) radHardness = 0;
        else if (radFloor && isHumanColonist) radHardness = Math.max(radHardness, 7);
        return { id: slot.id, name: face.name || patent.name, radHardness, immuneBelt };
      }
      const crew = CREW_BY_ID[slot.id];
      if (crew) {
        const f = crew.faces[slot.face === 'secondary' ? 'secondary' : 'primary'] || crew.faces.primary || {};
        const pw = facePower(f.name);
        let radHardness = f.radHardness != null ? f.radHardness : 0;
        if (isSirenRadZero(slot.id)) radHardness = 0;
        else if (radFloor) radHardness = Math.max(radHardness, 7);
        return { id: slot.id, name: f.name || crew.id, radHardness, immuneBelt: !!(pw && pw.immuneBelt) };
      }
      return null;
    })
    .filter(Boolean);
}

// Cards from `stackCards` that could be decommissioned on the worst roll of
// a single zone (d6 = 6): rad-hard < MAX_RAD_DIE + seasonBonus - thrust.
// `thrust` is the active thruster's final modified thrust; clamping the
// worst rad at 0 means a stack that out-thrusts the die returns [].
function radAtRiskCards(stackCards, thrust, seasonBonus) {
  const worstRad = Math.max(0, MAX_RAD_DIE + (seasonBonus | 0) - Math.max(0, thrust | 0));
  if (worstRad <= 0) return [];
  return (stackCards || [])
    // Belt-immune cards (sails) are never at risk - a belt roll can't touch them.
    .filter((c) => !c.immuneBelt && (c.radHardness || 0) < worstRad)
    .sort((a, b) => (a.radHardness || 0) - (b.radHardness || 0));
}

// Pre-roll confirm dialog for rad zones. Mirrors the
// hazardConfirmModal idiom (list of zones, scary warning,
// pick-an-action buttons) but tailored to the rad rules: no
// aqua bypass option, and the body explains the thrust + season
// math + whether the active thruster auto-clears the bar.
// Resolves to 'confirm' or 'cancel'. Always shown when the
// route crosses ≥1 rad zone so the player can back out before
// the dice roll.
function radConfirmModal(radHazards, thrust, seasonBonus, bypassThreshold, stackCards) {
  return new Promise((resolve) => {
    document.querySelector('.confirm-modal-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay rad-confirm-overlay';
    const close = (val) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(val);
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close('cancel'); });
    const onKey = (e) => { if (e.key === 'Escape') close('cancel'); };
    document.addEventListener('keydown', onKey);

    const n = radHazards.length;
    const list = radHazards.map((h) =>
      `<li><span class="haz-glyph">${h.glyph}</span> `
      + `${esc(h.site.name || h.label)} <em class="muted">${esc(h.label)}</em></li>`
    ).join('');
    const willBypass = thrust > bypassThreshold;
    // A rocket that is not thrust-bypassing still skips the roll when NO card
    // in the stack can fail the worst die (rad-hard + thrust clears a 6 + the
    // red-season bonus). Nothing is at stake, so the dice are pointless and the
    // move stays undoable. noRisk drives the honest button label + note below.
    const atRiskList = willBypass ? [] : radAtRiskCards(stackCards, thrust, seasonBonus);
    const noRisk = !willBypass && Array.isArray(stackCards) && stackCards.length > 0 && atRiskList.length === 0;
    const seasonLine = seasonBonus > 0
      ? `Red season adds <strong>+${seasonBonus}</strong> to every rad die.`
      : '';
    // Build the maths preview so the player sees the formula
    // before committing to roll. Active-thrust 0 reads as
    // "no subtraction" rather than "−0" which looks weird.
    const formulaParts = [`d6`];
    if (seasonBonus > 0) formulaParts.push(`+ ${seasonBonus}`);
    if (thrust > 0)      formulaParts.push(`− ${thrust}`);
    const formula = formulaParts.join(' ');
    const bypassNote = willBypass
      ? `<p class="rad-confirm-bypass ok">
          ✓ Active thrust <strong>${thrust}</strong> &gt; <strong>${bypassThreshold}</strong>
          - the rocket outruns the radiation. No roll, no
          decommissions.
         </p>`
      : noRisk
      ? `<p class="rad-confirm-bypass ok">
          ✓ <strong>No roll needed.</strong> Every card's rad-hard plus
          active thrust <strong>${thrust}</strong> clears even the worst die,
          so nothing can be lost. The stack crosses freely and the move can
          still be undone.
         </p>`
      : `<p class="rad-confirm-warning">
          <strong>Cannot bypass.</strong> Active thrust
          <strong>${thrust}</strong> ≤ <strong>${bypassThreshold}</strong>
          - one d6 rolls per zone. Cards with rad-hard less
          than the worst <em>final</em> rad get decommissioned
          to your hand. <strong>Aqua cannot bypass a rad
          roll.</strong>
         </p>`;

    // Up-front "what could I lose" list. A card is at risk when its
    // rad-hard plus the final thrust can't clear the worst die (a 6, plus
    // the red-season bonus). Only meaningful when the stack actually rolls;
    // a bypassing rocket loses nothing, so the list is skipped there.
    let atRiskNote = '';
    if (!willBypass && atRiskList.length) {
      // Right-hand side of the at-risk test: a card is lost when its
      // rad-hard + thrust can't reach the worst die (6) plus the season bonus.
      const riskThreshold = MAX_RAD_DIE + (seasonBonus | 0);
      const items = atRiskList.map((c) =>
        `<li><span class="rad-atrisk-name">${esc(c.name)}</span>`
        + `<span class="rad-atrisk-rh">rad-hard ${c.radHardness || 0}</span></li>`
      ).join('');
      atRiskNote = `
        <div class="rad-confirm-atrisk">
          <p class="rad-confirm-atrisk-head">
            ⚠ At risk on the worst roll
            <span class="muted">(rad-hard + thrust ${thrust || 0}
            &lt; ${riskThreshold})</span>:
          </p>
          <ul class="rad-confirm-atrisk-list">${items}</ul>
        </div>`;
    }

    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel rad-confirm-panel';
    panel.innerHTML = `
      <h3>☢ Radiation zone${n === 1 ? '' : 's'} ahead</h3>
      <p>Your planned route passes through
        <strong>${n}</strong> rad zone${n === 1 ? '' : 's'}:</p>
      <ul class="hazard-list">${list}</ul>
      ${seasonLine ? `<p class="rad-confirm-season muted">${seasonLine}</p>` : ''}
      <p class="rad-confirm-formula muted">
        Final radiation per zone = <code>${formula}</code>
        (active thrust ${thrust || 0}, bypass at &gt; ${bypassThreshold}).
      </p>
      ${bypassNote}
      ${atRiskNote}
      <div class="turn-confirm-actions hazard-actions">
        <button type="button" class="popup-btn primary" data-act="confirm"
          title="${willBypass ? 'Continue - the thrust check skips the roll'
            : noRisk ? 'Continue - nothing at risk, no roll, still undoable'
            : 'Open the rad-hardness roll modal'}">
          ${willBypass ? '✓ Confirm - bypass'
            : noRisk ? '✓ Confirm - move (no roll)'
            : '🎲 Confirm - roll rad check'}
        </button>
        <button type="button" class="popup-btn" data-act="cancel"
          title="Return to planning; no move spent">
          ✕ Cancel move
        </button>
      </div>
    `;
    for (const b of panel.querySelectorAll('button[data-act]')) {
      b.addEventListener('click', () => close(b.dataset.act));
    }
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

// Animated rad-hardness check modal. Different from the regular
// hazard-roll modal in three ways:
//   1. No aqua bypass - radiation can't be paid off.
//   2. Cards in the stack are checked individually against the
//      rolled d6 - rad-hard < d6 = decommissioned (sent to hand).
//   3. Resolves to a list of card-ids to decommission, not a
//      pass / fail flag.
// One d6 per rad zone; the worst die across all zones is the
// effective threshold per card (so two rad crossings = two
// chances to lose a card). Confirm button arms once every die
// has settled so the player has to acknowledge the outcome.
function radHardnessRollModal(radHazards, stackCards, thrust, seasonBonus) {
  return new Promise((resolve) => {
    document.querySelector('.rad-roll-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay rad-roll-overlay';
    let settled = false;
    let rolls = null;
    let toDecommission = [];
    const close = () => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve({ rolls: rolls || [], decommission: toDecommission });
    };
    const onKey = (e) => {
      if (e.key === 'Enter' && settled) { e.preventDefault(); close(); }
    };
    document.addEventListener('keydown', onKey);

    // Pre-roll all dice so visual + log + decommission agree.
    // `rad` is the FINAL radiation strength per zone after the
    // season bonus is added and the active thruster's thrust is
    // subtracted - clamped at 0 because a "negative" radiation
    // strength can't hurt any non-negative rad-hard card. The
    // raw d6 stays alongside so the UI can show the maths.
    const t = Math.max(0, thrust | 0);
    const bonus = (seasonBonus | 0) || 0;
    rolls = radHazards.map((h) => {
      const d6 = 1 + Math.floor(Math.random() * 6);
      const rad = Math.max(0, d6 + bonus - t);
      return { site: h.site, glyph: h.glyph, d6, rad, bonus, thrust: t };
    });

    const seasonNote = bonus > 0
      ? `Red season adds <strong>+${bonus}</strong> to every die.` : '';
    const thrustNote = t > 0
      ? `Active thrust <strong>${t}</strong> is subtracted from the die.`
      : `No active thrust - no subtraction.`;

    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel rad-roll-panel';
    panel.innerHTML = `
      <h3>☢ Rad-hardness check</h3>
      <p class="muted rad-roll-sub">
        ${thrustNote} ${seasonNote}
        Final radiation = die${bonus > 0 ? ' + ' + bonus : ''}${t > 0 ? ' − ' + t : ''}.
        Cards whose rad-hard is <strong>less than</strong> the
        worst final radiation get decommissioned to your hand.
        Aqua cannot bypass a rad roll.
      </p>
      <ul class="rad-roll-dice"></ul>
      <p class="rad-roll-result muted">Rolling…</p>
      <ul class="rad-roll-cards"></ul>
      <div class="turn-confirm-actions">
        <button type="button" class="popup-btn primary rad-roll-confirm" disabled>
          Confirm result
        </button>
      </div>
    `;
    const diceList = panel.querySelector('.rad-roll-dice');
    const cardsList = panel.querySelector('.rad-roll-cards');
    const resultLine = panel.querySelector('.rad-roll-result');
    const confirmBtn = panel.querySelector('.rad-roll-confirm');

    // Build a die row per rad zone. The "math chip" to the
    // right of each die is filled in once the die settles so
    // the player can watch the formula resolve as the rolls
    // land.
    const dieEls = rolls.map((r) => {
      const li = document.createElement('li');
      li.className = 'rad-roll-die-row';
      li.innerHTML = `
        <div class="rad-roll-site">
          <span class="haz-glyph">${r.glyph}</span>
          <strong>${esc(r.site.name)}</strong>
        </div>
        <div class="rad-roll-die-host"></div>
        <div class="rad-roll-math muted">…</div>
      `;
      diceList.appendChild(li);
      const dieHost = li.querySelector('.rad-roll-die-host');
      const die = buildDie(1);
      dieHost.appendChild(die);
      return { die, mathEl: li.querySelector('.rad-roll-math'), roll: r };
    });

    // Build the per-card rows: name + rad-hard. Decorated
    // post-roll with safe / decommissioned tags.
    const cardRowEls = stackCards.map((c) => {
      const li = document.createElement('li');
      li.className = 'rad-roll-card';
      li.innerHTML = `
        <span class="rad-roll-card-name">${esc(c.name)}</span>
        <span class="rad-roll-card-rad">RAD <strong>${c.radHardness != null ? c.radHardness : '-'}</strong></span>
        <span class="rad-roll-card-verdict muted">…</span>
      `;
      cardsList.appendChild(li);
      return { el: li, card: c };
    });
    if (!cardRowEls.length) {
      cardsList.innerHTML = '<li class="muted">Empty stack - nothing to test.</li>';
    }

    overlay.appendChild(panel);
    mountOverlay(overlay);

    Promise.all(dieEls.map(({ die, roll }) => rollDie(die, roll.d6))).then(() => {
      // Worst (highest) FINAL radiation across rad zones is the
      // effective threshold per card. Bonus and thrust are
      // already baked into roll.rad above.
      const worst = rolls.reduce((m, r) => Math.max(m, r.rad), 0);
      // Fill in each math chip so the player can read the
      // breakdown: "5 + 2 - 7 = 0" etc.
      for (const { mathEl, roll } of dieEls) {
        const parts = [String(roll.d6)];
        if (roll.bonus > 0) parts.push(`+ ${roll.bonus}`);
        if (roll.thrust > 0) parts.push(`− ${roll.thrust}`);
        const formula = parts.join(' ');
        mathEl.classList.remove('muted');
        mathEl.innerHTML = `${formula} = <strong>rad ${roll.rad}</strong>`;
        if (roll.rad === worst && worst > 0) mathEl.classList.add('is-worst');
      }
      let lost = 0;
      for (const { el, card } of cardRowEls) {
        const v = el.querySelector('.rad-roll-card-verdict');
        const rh = card.radHardness != null ? card.radHardness : 0;
        // Belt-immune cards (sails) shrug off the roll no matter how high it
        // lands - never decommissioned, always read "immune".
        if (card.immuneBelt) {
          el.classList.add('is-safe');
          v.classList.remove('muted');
          v.innerHTML = `<strong class="ok">✓ immune</strong>`;
          continue;
        }
        // Decommission iff final radiation > card rad-hard.
        // A rad-hard 0 card survives a worst-rad of 0; fails
        // a worst-rad of 1.
        const failed = worst > rh;
        if (failed) {
          toDecommission.push(card.id);
          lost++;
          el.classList.add('is-decommissioned');
          v.classList.remove('muted');
          v.innerHTML = `<strong class="bad">✗ decommissioned</strong>`;
        } else {
          el.classList.add('is-safe');
          v.classList.remove('muted');
          v.innerHTML = `<strong class="ok">✓ safe</strong>`;
        }
      }
      const dCount = rolls.length;
      resultLine.classList.remove('muted');
      if (!cardRowEls.length) {
        resultLine.innerHTML = `${dCount} rad zone${dCount === 1 ? '' : 's'} rolled - nothing in stack.`;
      } else if (lost > 0) {
        resultLine.innerHTML = `Worst final radiation <strong>${worst}</strong>: `
          + `<strong class="bad">${lost} card${lost === 1 ? '' : 's'} decommissioned</strong>.`;
        confirmBtn.classList.add('rad-roll-confirm-bad');
        confirmBtn.textContent = `Confirm - lose ${lost} card${lost === 1 ? '' : 's'}`;
      } else {
        resultLine.innerHTML = `Worst final radiation <strong>${worst}</strong>: `
          + `<strong class="ok">stack survived intact</strong>.`;
        confirmBtn.textContent = 'Confirm - continue';
      }
      settled = true;
      confirmBtn.disabled = false;
    });
    confirmBtn.addEventListener('click', () => { if (settled) close(); });
  });
}

// Small info modal used when the player tries to undo a hazardous
// move. Single OK button; the lockout is informational only.
// Mid-route choice between hazards. Pops after each roll
// resolves (and the rocket survived) so the player can:
//   - Continue: roll the next hazard.
//   - Stop here: halt the route at the current node. Remaining
//     planned segments stay in the route so a later turn can
//     pick them up.
//   - Pay X aqua to bypass the remaining GENERIC hazards
//     (rad zones can't be paid, so they still roll). Only
//     enabled when generic hazards remain unresolved AND the
//     balance covers the cost.
// Resolves to 'continue' | 'stop' | 'pay'.
function midRouteChoiceModal({ atSiteName, remaining, aquaBalance }) {
  return new Promise((resolve) => {
    document.querySelector('.mid-route-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay mid-route-overlay';
    const close = (val) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(val);
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close('stop'); });
    const onKey = (e) => {
      if (e.key === 'Escape') close('stop');
      else if (e.key === 'Enter') close('continue');
    };
    document.addEventListener('keydown', onKey);

    const remGeneric = remaining.filter((r) => r.hazard.site.type !== 'radhaz');
    const remRad     = remaining.filter((r) => r.hazard.site.type === 'radhaz');
    const payCost = remGeneric.length * finaoPer();
    const canPay = remGeneric.length > 0 && aquaBalance >= payCost;
    const list = remaining.map((r) =>
      `<li><span class="haz-glyph">${r.hazard.glyph}</span> `
      + `${esc(r.hazard.site.name || '')} <em class="muted">${esc(r.hazard.label)}</em></li>`
    ).join('');

    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel mid-route-panel';
    panel.innerHTML = `
      <h3>🛸 Pause at ${esc(atSiteName)}</h3>
      <p>Survived. <strong>${remaining.length}</strong> more
        hazard${remaining.length === 1 ? '' : 's'} along the
        route:</p>
      <ul class="hazard-list">${list}</ul>
      <div class="mid-route-balance muted">
        💧 Aqua balance: <strong>${aquaBalance}</strong>
        ${remRad.length ? ` · ${remRad.length} rad zone${remRad.length === 1 ? '' : 's'} can't be paid` : ''}
      </div>
      <div class="turn-confirm-actions mid-route-actions">
        <button type="button" class="popup-btn primary" data-act="continue"
          title="Roll the next hazard in line">
          ▶ Continue
        </button>
        ${remGeneric.length ? `
          <button type="button" class="popup-btn" data-act="pay"
            ${canPay ? '' : 'disabled'}
            title="${canPay ? 'Spend ' + payCost + ' aqua to skip the remaining generic rolls' : 'Not enough aqua to bypass remaining generic hazards'}">
            💧 Pay ${payCost} aqua to bypass ${remGeneric.length} generic
          </button>` : ''}
        <button type="button" class="popup-btn" data-act="stop"
          title="Halt the move here. Remaining segments stay in the planned route for a future turn.">
          ⏹ Stop here
        </button>
      </div>
    `;
    for (const b of panel.querySelectorAll('button[data-act]')) {
      b.addEventListener('click', () => close(b.dataset.act));
    }
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

function blockedUndoModal() {
  return confirmModal({
    title: '⚠ Move locked',
    body: 'This turn\'s move flew through a hazard spot. '
      + 'Hazard rolls and aqua bypasses commit the move - it '
      + 'cannot be undone. End the turn to start fresh.',
    yes: 'OK',
    no: '',
  });
}

// Sunspot Cube d6 events. Rules text + lookup live in turn-clock.js
// (single source of truth - the tracker modal reads the same table).
// **Sandbox mode**: we DO NOT apply the event to game state. The
// d6 still rolls so the player sees what the cube would have
// triggered at the table, but no decks rotate, no cards
// decommission, no Glitch disks get placed. Log entries are
// prefixed "Would fire:" to keep that distinction obvious. When
// the engine ships (Stage 3+) the application path goes here.
function applyEventDieEffect(event) {
  if (!event || typeof event.dieRoll !== 'number') return;
  const season = getSeasonForSlot(event.turn);
  const e = getEventForRoll(event.dieRoll, season && season.name);
  if (!e) return;
  // SOLO event effects. Inspiration (d6 = 1 or 2) cycles every
  // patent deck (topmost card to the bottom) automatically; the
  // remaining events still log as "Would fire" table reminders in
  // the sandbox. ONLINE every event resolves server-side
  // (engine resolveSunspotEvent) - this function never runs there,
  // since the clock hydrates from the snapshot. No parity work for
  // the other five is planned: the sandbox is being replaced by a
  // server-backed solo mode that runs the same engine resolution
  // (user decision 2026-06-12).
  let applied = false;
  if (e.rolls.includes(event.dieRoll) && e.name === 'Inspiration') {
    cycleAllDecks();
    applied = true;
  }
  logAction({
    type: 'event_d6',
    icon: e.icon,
    summary: applied
      ? `${e.name} fired (d6 = ${event.dieRoll}) - every market deck cycled top → bottom.`
      : `Would fire: ${e.name} (d6 = ${event.dieRoll}) - ${e.text}`,
    undoable: false,
    data: {
      dieRoll: event.dieRoll,
      eventName: e.name,
      season: season && season.name,
      applied,
    },
  });
}

// Prospect roll. The site's `siteSize` from the planner data
// encodes the difficulty as "<n><spectral>" (e.g. "9H", "11C",
// "1S"); we parse the leading integer as the prospect threshold.
// Falls back to a class-letter -> number map when siteSize is
// absent (the curated SITES table uses A/B/C/D letters).
//
// Rules: roll 1d6. If roll <= threshold, SUCCESS - player's
// colour disc lands over the site (claim marker). If roll >
// threshold, FAIL - a red disc lands (site exhausted, can't be
// re-prospected in this sandbox session until the player
// manually clears the disc).
const CLASS_TO_NUMBER = { A: 3, B: 5, C: 7, D: 9 };
function siteProspectThreshold(site) {
  if (!site) return 4;
  const ss = site.siteSize;
  if (typeof ss === 'string') {
    const m = ss.match(/^(\d+)/);
    if (m) return Math.max(1, Math.min(11, parseInt(m[1], 10)));
  }
  const cls = String(site.class || '').toUpperCase();
  if (cls in CLASS_TO_NUMBER) return CLASS_TO_NUMBER[cls];
  return 4;
}

// The site's "size" - the integer printed in the board hexagon
// (the leading digit of siteSize, e.g. "9H" -> 9). Used by the
// land / liftoff thrust gate: a rocket needs net thrust strictly
// greater than this to settle onto or climb off the site. Orbital
// waypoints (LEO + lagranges) have no siteSize, so they return 0
// and are always free to enter / leave.
function siteSizeNumber(site) {
  if (!site) return 0;
  const ss = site.siteSize;
  if (typeof ss === 'string') {
    const m = ss.match(/^(\d+)/);
    if (m) return Math.max(0, parseInt(m[1], 10));
  }
  if (typeof ss === 'number' && Number.isFinite(ss)) return Math.max(0, ss | 0);
  return 0;
}

// Land / liftoff gate for a single site given the rocket's current
// net (band-adjusted) thrust. The rule: net thrust must strictly
// exceed the site's size to settle onto or climb off it (so a size-1
// site needs net thrust >= 2). When it doesn't, a FACTORY at the site
// permits the maneuver anyway as a "factory assist" - a hazard roll. A
// COLONY at the site waives the roll. The ONE exception is a Freighter
// (M1, opts.isFreighter), which may settle onto a size-1 site even
// under-thrust. Returns:
//   ok        - the maneuver is allowed (true unless under-thrust
//               with no factory to assist)
//   assist    - true when a factory is carrying the maneuver
//   needsRoll - true when the assist still requires a hazard roll
//               (i.e. no colony to waive it)
//   size      - the site size used for the comparison
// Mirror of planner-graph.js#siteHasLanderBurn via the SHARED walk: does this
// site sit behind a lander-burn pad in its well? The client classifies a site
// node's type as a body class (not 'site'), but the walk only keys on 'burn'
// (success) + 'decorative' (traverse) and treats everything else as the well
// boundary, so it resolves identically to the server. Cached - the map is static.
// Is this SINGLE node itself a lander-burn pad (the H6c "cannot halt on a
// lander burn" flag)? Distinct from siteHasLanderBurn (which asks "does the
// SITE sit behind one in its well") - used to gate where the hazard stepper
// (below) may offer "Stop here".
function isLanderBurnNodeClient(slug) {
  return !!(slug && NODE_TAGS[slug] && NODE_TAGS[slug].lander);
}
const _landerBurnCache = new Map();
function siteHasLanderBurn(site) {
  const id = site && site.id;
  if (!id) return false;
  if (_landerBurnCache.has(id)) return _landerBurnCache.get(id);
  const v = (_activeData && typeof _activeData.neighborsOf === 'function')
    ? isLanderBurnSite(
        id,
        (n) => _activeData.neighborsOf(n),
        (n) => { const nd = _activeData.byId && _activeData.byId[n]; return nd ? nd.type : null; },
      )
    : false;
  _landerBurnCache.set(id, v);
  return v;
}
function maneuverGate(site, netThrust, opts = {}) {
  const size = siteSizeNumber(site);
  if (size <= 0 || netThrust > size) {
    return { ok: true, assist: false, needsRoll: false, size };
  }
  // Freighter exception (M1): a Freighter can land on / lift off a size-1
  // site with any operational thruster, even though its net thrust does not
  // beat the size. Ordinary spacecraft do NOT get this - they must satisfy
  // net thrust > site size (or use a factory assist) like every other site.
  if (size === 1 && opts.isFreighter && netThrust > 0 && isRocketActive().active) {
    return { ok: true, assist: false, needsRoll: false, size };
  }
  // High-Gravity Limit (H5e / H6c): factory-assist cannot carry a maneuver into
  // or out of a lander-burn space. Such a site needs real net thrust > size, an
  // aerobrake landing, or an Acetylene Rocketplane Liftoff (opts.acetylene: the
  // move commit validates the atmospheric site + usable factory + the 2 x wet
  // mass site-water cost before granting it). GEO Elevator / Lofstrom Loop
  // Bernal (promoted, anchored anywhere) waives the hard block ("treat lander
  // burns as normal Burn Spaces"); like opts.powersat below, this defaults to
  // the LOCAL player's own Bernals but a caller / test may force it via
  // opts.bernalLanderBurnWaived. Mirror of the server maneuverGate.
  if (siteHasLanderBurn(site) && !opts.acetylene) {
    const bernalWaived = (opts.bernalLanderBurnWaived != null)
      ? !!opts.bernalLanderBurnWaived : myBernalWaivesLanderBurn();
    if (!bernalWaived) return { ok: false, assist: false, needsRoll: false, size, landerBurn: true };
  }
  const factory = site && getFactory(site.id);
  if (!factory) return { ok: false, assist: false, needsRoll: false, size };
  const colony = getColony(site.id);
  // Safe Factory-Assist (Powersat rule e): a Powersat holder's factory-assist
  // needs no Hazard Roll, the same waiver a colony pad grants. Every caller here
  // gates the LOCAL player's own maneuver, so myHasPowersat() is the right read;
  // opts.powersat lets a caller / test force it. Mirrors the server maneuverGate.
  const powersat = (opts.powersat != null) ? !!opts.powersat : myHasPowersat();
  return { ok: true, assist: true, needsRoll: !colony && !powersat, size };
}

// Refueling at a hydrated site. Two distinct refining sources
// per the HF4 rules:
//
//   1. A Refinery card (card.type === 'refinery') with its
//      supports met: a FLAT +7 water per op. Refineries are
//      dedicated processing plants, not water-rated rigs.
//
//   2. An active ISRU rig (the prospector with an ISRU property,
//      until dedicated refinery support lands in Stage 3): yield
//      = site number - ISRU + 1. The site number is the same
//      value the prospect roll checks against.
//
// Either path needs the rocket parked ON the site and the site's
// number > 0. The refinery path is preferred when both are
// available because it produces more water (7 > typical formula).
// One refining op per (turn, site) so a player can't strip-mine.
const STORAGE_REFUEL_LOG = 'hf-sandbox-refuel-log';   // {turn: number, sites: [id]}
function getRefuelLog() {
  try {
    const s = localStorage.getItem(STORAGE_REFUEL_LOG);
    return s ? JSON.parse(s) : null;
  } catch { return null; }
}
function markRefueledThisTurn(siteId) {
  const turn = getTurn();
  let log = getRefuelLog();
  if (!log || log.turn !== turn) log = { turn, sites: [] };
  if (!log.sites.includes(siteId)) log.sites.push(siteId);
  try { localStorage.setItem(STORAGE_REFUEL_LOG, JSON.stringify(log)); } catch {}
}
// Colocated Miner colonists of mine at this site. Each grants one EXTRA
// site refuel per turn (2C1) - a free repeat riding the same operation.
function myMinersAt(siteId) {
  if (!_online || !isM2()) return 0;
  const me = mySnapshotPlayer();
  if (!me) return 0;
  const slug = (_onlineMaps && toServerId(_onlineMaps, siteId)) || siteId;
  let n = 0;
  for (const e of snapshotColonistSlots(me)) {
    if (colonistColocatedWithClientSite(e, slug) && e.card.specialty === 'Miner') n += 1;
  }
  return n;
}
// Times I have already refined at this site this turn (online).
function refuelUsesThisTurn(siteId) {
  const me = (_onlineSnapshot && (_onlineSnapshot.players || [])
    .find((p) => p.profileId === mySeatId())) || null;
  const slug = (_onlineMaps && toServerId(_onlineMaps, siteId)) || siteId;
  if (!me || !Array.isArray(me.refueledSites)) return 0;
  return me.refueledSites.filter((s) => s === slug).length;
}
// The NEXT refuel here rides free on a Miner colonist (already refined once,
// but a colocated Miner grants the repeat). Lets the buttons say why.
function refuelIsMinerExtra(siteId) {
  if (!_online) return false;
  const uses = refuelUsesThisTurn(siteId);
  return uses >= 1 && uses < 1 + myMinersAt(siteId);
}
function hasRefueledThisTurn(siteId) {
  // Online: the server CLEARS refueledSites at the start of each of the player's
  // turns, so it is the authority on "already refuelled here this turn". Read it
  // from the snapshot. The local turn-clock log (getTurn()) does NOT advance per
  // the player's individual turn in a multiplayer game, so it would keep the
  // refuel button greyed across turns (user 2026-06-28). refueledSites stores
  // SERVER slugs, so convert the client site id first. The allowance is 1 plus
  // one EXTRA per colocated Miner colonist (2C1), mirroring the engine's
  // siteRefuelGate - a boolean here made the Miner's free repeat unreachable.
  if (_online) {
    return refuelUsesThisTurn(siteId) >= 1 + myMinersAt(siteId);
  }
  const log = getRefuelLog();
  if (!log || log.turn !== getTurn()) return false;
  return log.sites.includes(siteId);
}

// Dirt refuel is capped per turn (HF4 MOONCABLE: 7 tanks via the moon cable
// for a non-crew dirt triangle at LEO, else 1). Tracked cumulatively on the
// server (player.dirtTanksThisTurn, surfaced on the snapshot); the solo path
// (frozen legacy) only records "loaded this turn" coarsely in localStorage.
const STORAGE_DIRT_REFUEL_LOG = 'hf-sandbox-dirt-refuel-turn';   // turn number
function hasDirtRefueledThisTurn() {
  try { return Number(localStorage.getItem(STORAGE_DIRT_REFUEL_LOG)) === getTurn(); }
  catch { return false; }
}
function markDirtRefueledThisTurn() {
  try { localStorage.setItem(STORAGE_DIRT_REFUEL_LOG, String(getTurn())); } catch {}
}
// How many dirt tanks the active stack has loaded so far this turn (online
// reads the snapshot tally; solo is coarse - 1 once it has refuelled at all).
function dirtTanksLoadedThisTurn() {
  if (_online) {
    const me = _onlineSnapshot && (_onlineSnapshot.players || []).find((p) => p.profileId === mySeatId());
    return Number(me && me.dirtTanksThisTurn) || 0;
  }
  return hasDirtRefueledThisTurn() ? 1 : 0;
}

// Pick the best refining source available in the rocket stack.
// Returns either:
//   { kind: 'refinery', card, rawGain: 7 }
//   { kind: 'isru', card, rawGain: 1 + hydration - ISRU, isru }
//   null - nothing usable
//
// The ISRU formula is the published HF4 Site Refuel Op (I5a):
// "An Operational card with an ISRU platform produces a number
// of water FTs equal to one plus the Site's Hydration minus the
// card's ISRU rating." Gate: ISRU <= hydration (so gain >= 1).
//
// Site Refuel (I5a) uses ONLY the active prospector's ISRU rig.
// A REFINERY card is just a build part for a Factory - it is NOT
// a refuel source. The flat +7 refuel is Factory-only (I5b), and
// requires a built factory at the site.
// Aerostat detection: the 'aerostat' marker lives in the site SLUG. A client map
// node keeps that slug in id2 (its .id is the raw planner-point key, which never
// contains 'aerostat'), so testing .id alone always read false and silently
// killed every aerostat-only power (SCOOP's -2 ISRU, the Atmospheric Scoop's
// hydration-2 raise). Test id2 first, then .id, so a server-shaped site (whose
// .id IS the slug) still matches. Mirrors the server's isAerostatSite.
function siteIsAerostat(site) {
  return !!site && (/aerostat/i.test(String(site.id2 || '')) || /aerostat/i.test(String(site.id || '')));
}
function pickRefiningSource(site) {
  // Atmospheric Scoop (subsystem 5): an aerostat site you're parked at (refuel
  // is always colocated) counts as hydration 2. Adjacency is server-side only.
  const isAerostat = siteIsAerostat(site);
  const baseWater = Number.isFinite(site.hydration) ? site.hydration : 0;
  const water = (isAerostat && stackHasPower('aerostatHydration2')) ? Math.max(baseWater, 2) : baseWater;
  // SCAVENGING (Femtochemistry): a colocated card doubles refuel FTs.
  const scavenge = stackHasPower('doubleSiteRefuel') ? 2 : 1;
  // ISRU rig path: the active prospector with an ISRU rating (0 or
  // more), supports met, and ISRU <= site hydration so the
  // 1 + hydration - ISRU formula gives at least 1 water.
  const prosp = getActiveProspectorStats();
  if (prosp && prosp.canActivate) {
    // Colocated ISRU modifier (subsystem 3): lower the rig's effective ISRU
    // (floored at 0), matching the server refuel yield.
    const isru = Math.max(0, prosp.isru + colocatedIsruMod({ isAerostat }));
    // ISRU 0 is a valid rig (gain = 1 + water), so it refuels anywhere the
    // gate ISRU <= water allows - which for 0 is every site.
    if (isru >= 0 && isru <= water) {
      return { kind: 'isru', card: prosp.card, name: prosp.name, rawGain: (1 + water - isru) * scavenge, isru };
    }
  }
  return null;
}

function canRefuelAt(site) {
  // A GW thruster burns ISOTOPE, not water - so ISRU water refuel is not
  // allowed for an isotope ship. Its only refuel is the Factory Isotope Refuel
  // (1 FT/turn at a matching-spectral Factory).
  const activeId = getActiveThrusterId();
  const activeCard = activeId && cardById(activeId);
  if (activeCard && activeCard.type === 'gw-thruster') {
    return { ok: false, label: '💧 Refuel (isotope engine)', reason: 'A GW thruster runs on isotope - refine it at a matching Factory (Isotope Refuel), not via ISRU water.' };
  }
  // Effective hydration: an aerostat site with the Atmospheric Scoop aboard
  // counts as hydration 2 (the same raise pickRefiningSource + the server apply).
  // Without this the dry-site gate greyed a scoop-enabled aerostat refuel even
  // though the server allows it (user 2026-06-29: refuel greyed at Titan).
  const isAerostat = siteIsAerostat(site);
  const baseWater = Number.isFinite(site.hydration) ? site.hydration : 0;
  const water = (isAerostat && stackHasPower('aerostatHydration2')) ? Math.max(baseWater, 2) : baseWater;
  const tank  = getTankWater();
  const tmax  = getTankMax();
  if (water <= 0) {
    return { ok: false, label: `💧 Refuel (dry site)`, reason: isAerostat
      ? 'Aerostat has no water - carry an Atmospheric Scoop to make it hydration 2.'
      : 'Site has no water (hydration 0).' };
  }
  if (tank >= tmax) {
    return { ok: false, label: `💧 Tank full (${tank}/${tmax})`, reason: 'Tank is already at max.' };
  }
  const source = pickRefiningSource(site);
  if (!source) {
    return {
      ok: false,
      label: `💧 Refuel (no rig)`,
      reason: 'Need an active ISRU prospector with ISRU ≤ site water (a Factory gives the +7 refuel instead).',
    };
  }
  if (hasRefueledThisTurn(site.id)) {
    return { ok: false, label: `💧 Refueled this turn`, reason: 'Already refined here this turn. End turn to refresh.' };
  }
  const gain = Math.min(source.rawGain, tmax - tank);
  const minerExtra = refuelIsMinerExtra(site.id);
  return {
    ok: true,
    label: `💧 Refuel (+${gain} via ISRU${minerExtra ? ', Miner extra - free' : ''})`,
    reason: null, source,
  };
}

function doRefuel(site) {
  const chk = canRefuelAt(site);
  if (!chk.ok) {
    setStatus(`Refuel blocked: ${chk.reason}`);
    return;
  }
  // Online: the server refines the site's water into the tank with the
  // active ISRU rig and spends the op; the snapshot repaints the tank.
  if (_online) {
    const sid = toServerId(_onlineMaps, site.id);
    if (!sid) { _onlineToast('That site is not on the map.', 'error'); return; }
    submitOnlineOp({ kind: 'SITE_REFUEL', siteId: sid, mode: 'isru' });
    return;
  }
  // Rulebook I5a: ISRU Refuel is an Operation, consumes the
  // per-turn op slot. Factory-Refuel (I5b) will route through
  // this same gate when it lands.
  if (!requireOp('ISRU Refuel')) return;
  const source = chk.source;
  const tankBefore = getTankWater();
  const tmax = getTankMax();
  const gain = Math.min(source.rawGain, tmax - tankBefore);
  if (gain <= 0) return;
  loadFuel(gain);   // walk the red line so the wet chit lands on a node
  markRefueledThisTurn(site.id);
  const sourceName = source.name || source.card?.name || source.kind;
  const water = Number.isFinite(site.hydration) ? site.hydration : 0;
  const detail = `1 + water ${water} - ISRU ${source.isru} = ${source.rawGain} via <em>${esc(sourceName)}</em>`;
  setStatus(
    `💧 Refined <strong>${gain}</strong> water at `
    + `<strong>${esc(site.name)}</strong> (${detail}). `
    + `Tank ${tankBefore} → <strong>${tankBefore + gain}</strong>/${tmax}.`
  );
  logAction({
    type: 'refuel',
    icon: '💧',
    summary: `Refined +${gain} water at ${site.name} via ${source.kind} (${sourceName}); tank ${tankBefore + gain}/${tmax}`,
    undoable: false,
    data: {
      siteId: site.id, gain, source: source.kind,
      tankAfter: tankBefore + gain,
    },
  });
  // Visual: pop the tank modal showing water flowing in. Player
  // can click to skip or dismiss whenever.
  openFuelTankModal({ fromWater: tankBefore, toWater: tankBefore + gain });
}

// Outpost slot picker. Returns a Promise<letter|null>; resolves
// null on cancel / Escape. Shows the four A/B/C/D buttons in a
// row, dimming the ones whose slots are already taken. Used by
// the Rocket -> Outpost convert flow (user picks which slot
// letter the new outpost takes - variant rule, see
// industrialize.md "Outpost slot assignment").
function pickOutpostSlot({ title = '🏛 Pick a slot for the new Outpost', body = '' } = {}) {
  return new Promise((resolve) => {
    document.querySelector('.outpost-slot-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay outpost-slot-overlay';
    overlay.tabIndex = -1;
    const close = (letter) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(letter || null);
    };
    const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(null); } };
    document.addEventListener('keydown', onKey);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(null); });
    const free = new Set(getAvailableOutpostSlots());
    const dialog = document.createElement('div');
    dialog.className = 'outpost-slot-modal';
    dialog.innerHTML = `
      <div class="outpost-slot-head"><h3>${esc(title)}</h3></div>
      ${body ? `<div class="outpost-slot-body">${body}</div>` : ''}
      <div class="outpost-slot-buttons">
        ${OUTPOST_LETTERS.map((L) => {
          const taken = !free.has(L);
          return `<button type="button" class="outpost-slot-btn ${taken ? 'is-taken' : ''}" data-letter="${L}" ${taken ? 'disabled' : ''}>${L}</button>`;
        }).join('')}
      </div>
      <div class="card-modal-actions">
        <button type="button" class="modal-btn outpost-slot-cancel">Cancel</button>
      </div>
    `;
    overlay.appendChild(dialog);
    dialog.querySelectorAll('.outpost-slot-btn').forEach((btn) => {
      btn.addEventListener('click', () => {
        if (btn.disabled) return;
        close(btn.getAttribute('data-letter'));
      });
    });
    dialog.querySelector('.outpost-slot-cancel').addEventListener('click', () => close(null));
    document.body.appendChild(overlay);
    overlay.focus();
  });
}

// Rocket -> Outpost. Free action. Caller has validated the
// rocket has cards, is at a non-LEO site, and at least one
// outpost slot is free. Opens the slot picker; on confirm,
// snapshots the rocket stack + tank, dissolves the rocket
// (cards cleared, tank zeroed, rocket returns to LEO), and
// creates the outpost with the snapshotted state.
async function doConvertToOutpost(site) {
  const stack = getRocketStack();
  const tank  = getTankWater();
  if (!stack.length) return;
  // Online: the server parks the stack as an outpost (it picks the slot)
  // and recalls the rocket. Confirm, submit, let the snapshot re-hydrate.
  if (_online) {
    const ok = await confirmModal({
      title: `🚀→🏛 Convert Rocket to Outpost at ${site.name}`,
      body: `<p>${stack.length} card${stack.length === 1 ? '' : 's'} + ${tank} water will park as a new outpost here; your rocket returns to LEO empty.</p>`,
      yes: '🚀→🏛 Convert', no: 'Cancel',
    });
    if (!ok) return;
    await submitOnlineOp({ kind: 'CONVERT_OUTPOST' });
    return;
  }
  const letter = await pickOutpostSlot({
    title: `🚀→🏛 Convert Rocket to Outpost at ${site.name}`,
    body: `<p>${stack.length} card${stack.length === 1 ? '' : 's'} + ${tank} water will move to the new outpost.</p>`,
  });
  if (!letter) return;
  if (!createOutpost(letter, site.id)) {
    setStatus(`Convert failed - slot ${esc(letter)} could not be created.`);
    return;
  }
  // Move cards in order so the outpost's stack mirrors the
  // rocket's. We do NOT route through the patent deck or hand -
  // cards pass directly from one stack to the other.
  for (const slot of stack) {
    addCardToOutpost(letter, { id: slot.id, kind: slot.kind });
  }
  setOutpostTank(letter, tank);
  // Dissolve the rocket: clear its card list + tank, return it
  // to LEO. Same wipe pattern as explodeRocket minus the boom.
  rocketClearStack();
  setTankWater(0);
  _rocketSiteId = null;
  persistRocketSite();
  _plannedRoute = null;
  persistPlannedRoute();
  exitManualMoveMode();
  _rocketTrail = [];
  persistRocketTrail();
  if (_renderer) {
    _renderer.setRoute(null);
    _renderer.setRouteEndpoints(null, null);
    _renderer.setRocketTrail(null);
  }
  setStatus(
    `🚀→🏛 Converted rocket to Outpost <strong>${esc(letter)}</strong> at `
    + `<strong>${esc(site.name)}</strong>. `
    + `${stack.length} card${stack.length === 1 ? '' : 's'} + ${tank} water moved across; `
    + `rocket returns to LEO empty.`
  );
  logAction({
    type: 'convert_outpost',
    icon: '🚀→🏛',
    summary: `Converted rocket to Outpost ${letter} at ${site.name} (${stack.length} cards, ${tank} water)`,
    undoable: false,
    data: { siteId: site.id, letter, cards: stack.length, tank },
  });
}


// Pump water from the ROCKET tank into a colocated outpost (store it there).
// Whole units only; a sub-1 remainder stays in the rocket. Server-routed online.
async function doPumpFuelToOutpost(letter, max, amount = null) {
  if (max <= 0) return;
  const amt0 = amount != null ? Math.min(amount, max)
    : await pickFuelAmount({ title: `💧 Store fuel in Outpost ${letter}`, max });
  if (!amt0) return;
  if (_online) {
    await submitOnlineOp({ kind: 'TRANSFER_FUEL', letter, amount: amt0, direction: 'toOutpost' });
    return;
  }
  const op = getOutpost(letter);
  if (!op) return;
  const amt = Math.min(amt0, Math.floor(getTankWater()), max);
  if (amt <= 0) return;
  removeFuel(amt);
  setOutpostTank(letter, (op.tank | 0) + amt);
  setStatus(`💧 Stored ${amt} water from the rocket in Outpost ${letter}.`);
}

// Outpost water transfer for the ROCKET fuel-tank modal: one block per
// colocated outpost, styled like the LEO aqua-bank widget (two directions:
// Outpost -> Tank +1/+5/Max fill, Tank -> Outpost -1/-5/Store all). The buttons
// transfer immediately and the section refreshes in place.
function fuelTankOutpostSections() {
  const rs = getRocketSite();
  if (!rs || getRocketStack().length === 0) return '';
  let html = '';
  for (const letter of OUTPOST_LETTERS) {
    const op = getOutpost(letter);
    if (!op || op.siteId !== rs.id) continue;
    const L = esc(letter);
    html += `<div class="fuel-tank-aqua ft-outpost" data-letter="${L}">
      <div class="aqua-row"><span>🏛 Outpost ${L}</span><strong class="ft-op-bal">${op.tank | 0}</strong></div>
      <p class="muted aqua-help">At this site you can move water between Outpost ${L} and the rocket tank, 1:1, for free.</p>
      <div class="aqua-direction">
        <span class="aqua-direction-label">🏛 Outpost → 💧 Tank</span>
        <div class="aqua-actions">
          <button type="button" class="popup-btn popup-btn-secondary ft-op-btn" data-dir="in" data-amt="1">+1</button>
          <button type="button" class="popup-btn popup-btn-secondary ft-op-btn" data-dir="in" data-amt="5">+5</button>
          <button type="button" class="popup-btn ft-op-btn" data-dir="in" data-amt="max">Max fill</button>
        </div>
      </div>
      <div class="aqua-direction aqua-direction-reverse">
        <span class="aqua-direction-label">💧 Tank → 🏛 Outpost</span>
        <div class="aqua-actions">
          <button type="button" class="popup-btn popup-btn-secondary ft-op-btn" data-dir="out" data-amt="1">-1</button>
          <button type="button" class="popup-btn popup-btn-secondary ft-op-btn" data-dir="out" data-amt="5">-5</button>
          <button type="button" class="popup-btn ft-op-btn" data-dir="out" data-amt="all">Store all</button>
        </div>
      </div>
    </div>`;
  }
  return html;
}

// Pump water from a colocated outpost into the rocket tank. Prompts for
// an amount (capped by the outpost's water + the rocket's tank room),
// then routes through the server (TRANSFER_FUEL) online or mutates the
// local stacks in solo.
async function doPumpOutpostFuel(letter, max, amount = null) {
  if (max <= 0) return;
  const amt0 = amount != null ? Math.min(amount, max)
    : await pickFuelAmount({ title: `💧 Pump fuel from Outpost ${letter}`, max });
  if (!amt0) return;
  if (_online) {
    await submitOnlineOp({ kind: 'TRANSFER_FUEL', letter, amount: amt0 });
    return;
  }
  const op = getOutpost(letter);
  if (!op) return;
  const amt = Math.min(amt0, op.tank | 0, max);
  if (amt <= 0) return;
  setOutpostTank(letter, (op.tank | 0) - amt);
  addFuel(amt);
  setStatus(`💧 Pumped ${amt} water from Outpost ${letter} into the rocket.`);
}

// Footer button for the outpost inspector: pump the outpost's water into
// a colocated rocket. Empty string when not applicable (not an outpost,
// no rocket here, no water, or no tank room).
function outpostPumpBtnHtml(stackId) {
  if (!stackId.startsWith('outpost')) return '';
  const letter = stackId.slice('outpost'.length);
  const op = getOutpost(letter);
  if (!op || (op.tank | 0) <= 0) return '';
  const rs = getRocketSite();
  if (!rs || rs.id !== op.siteId || getRocketStack().length === 0) return '';
  const totals = getStackTotals();
  const room = Math.max(0, getTankMax() - (totals.dryMass || 0) - getTankWater());
  const max = Math.min(op.tank | 0, room);
  const disabled = max <= 0 ? 'disabled' : '';
  const title = max > 0 ? `Pump up to ${max} water into the rocket` : 'Rocket tank is full';
  return `<button type="button" class="modal-btn stack stack-pump-fuel" data-letter="${esc(letter)}" data-max="${max}" ${disabled} title="${title}">💧 Pump ${max > 0 ? max + ' ' : ''}→ rocket</button>`;
}

// The anchored Bernal a Dirtside-parked stack cooperates with for the Dirtside
// Ascent operation (2A7f), or null. stackId is a stack whose site may be Dirtside
// to one of my anchored Bernals. Mirrors the server's playerBernalDirtsideAt.
// Only real Dirtside stacks qualify (a rocket / freighter / outpost out at a
// site, never LEO and never a Bernal itself).
function dirtsideAscentBernalFor(stackId) {
  if (!_online || !isM2()) return null;
  if (!(stackId === 'rocket' || stackId === 'freighter'
    || (typeof stackId === 'string' && stackId.startsWith('outpost')))) return null;
  const clientSite = getStackSiteId(stackId);
  if (!clientSite || clientSite === getLeoSiteId()) return null;
  const siteSlug = (_onlineMaps && toServerId(_onlineMaps, clientSite)) || clientSite;
  const bernals = getMyBernals();
  for (let i = 0; i < bernals.length; i++) {
    const bn = bernals[i];
    if (bn && bn.anchored && clientBernalDirtsideSlugs(bn.siteId).includes(siteSlug)) {
      const card = cardById(bn.cardId);
      return { unit: `bernal${i}`, name: (card && card.name) || `Bernal ${i + 1}` };
    }
  }
  return null;
}
// Footer button for a Dirtside-parked stack: the Dirtside Ascent OPERATION -
// move ALL cards up to the cooperating anchored Bernal (2A7f). Costs the turn's
// operation, so it is my-turn + op gated. Empty string when not applicable.
function dirtsideAscentBtnHtml(stackId) {
  const bnl = dirtsideAscentBernalFor(stackId);
  if (!bnl) return '';
  const cards = getStackCards(stackId);
  const has = cards.some((c) => c.kind !== 'fuel');
  const myTurn = isOnlineMyTurn();
  const disabled = (!has || !myTurn) ? 'disabled' : '';
  const title = !has ? 'No cards here to ascend'
    : !myTurn ? 'Wait for your turn'
      : `Operation: move every card here up to ${esc(bnl.name)}`;
  return `<button type="button" class="modal-btn stack stack-dirtside-ascent" data-unit="${esc(bnl.unit)}" data-from="${esc(stackId)}" ${disabled} title="${title}">⬆ Dirtside Ascent</button>`;
}
// Footer button for the outpost inspector: store the colocated rocket's water
// IN this outpost (reverse of the pump-to-rocket button). Empty string when not
// applicable (not an outpost, no rocket here, or the rocket has no water).
function outpostFillBtnHtml(stackId) {
  if (!stackId.startsWith('outpost')) return '';
  const letter = stackId.slice('outpost'.length);
  const op = getOutpost(letter);
  if (!op) return '';
  const rs = getRocketSite();
  if (!rs || rs.id !== op.siteId || getRocketStack().length === 0) return '';
  const have = Math.floor(getTankWater());
  if (have <= 0) return '';
  return `<button type="button" class="modal-btn stack stack-fill-fuel" data-letter="${esc(letter)}" data-max="${have}" title="Store up to ${have} water from the rocket here">💧 Fill ${have} ← rocket</button>`;
}

// Footer button for an EMPTY outpost: decommission (dissolve) it to free
// the slot. Empty string when the outpost still holds cards. Never disabled
// for leftover water - any water still in the tank is destroyed along with
// the outpost, and the click handler (stack-dissolve-outpost below) warns
// about that loss before submitting instead of blocking the button.
function outpostDissolveBtnHtml(stackId) {
  if (!stackId.startsWith('outpost')) return '';
  const letter = stackId.slice('outpost'.length);
  const op = getOutpost(letter);
  if (!op || (op.cards && op.cards.length > 0)) return '';
  const water = Number(op.tank) || 0;
  const title = water >= 1
    ? `Decommission this empty outpost and free the slot. WARNING: ${Math.floor(water)} water still in its tank will be destroyed.`
    : water > 0
      ? `Decommission this empty outpost and free the slot (discards a ${Math.round(water * 100) / 100} water remainder that can't be transferred).`
      : 'Decommission this empty outpost and free the slot.';
  return `<button type="button" class="modal-btn decommission stack-dissolve-outpost" data-letter="${esc(letter)}" data-water="${water}" title="${esc(title)}">🗑 Decommission outpost${water >= 1 ? ` (${Math.floor(water)} water lost)` : ''}</button>`;
}

// Minimal amount-picker modal (stepper + "All"). Resolves to a positive
// integer or null on cancel.
function pickFuelAmount({ title = '💧 Transfer water', max = 1 } = {}) {
  return new Promise((resolve) => {
    document.querySelector('.fuel-amount-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay fuel-amount-overlay';
    let amount = Math.min(1, max);
    const close = (val) => { overlay.remove(); document.removeEventListener('keydown', onKey); resolve(val); };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(null); });
    const onKey = (e) => { if (e.key === 'Escape') close(null); else if (e.key === 'Enter') close(amount); };
    document.addEventListener('keydown', onKey);
    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel';
    panel.innerHTML = `
      <h3>${esc(title)}</h3>
      <div class="dump-stepper">
        <button type="button" class="popup-btn popup-btn-secondary fa-step" data-step="-5" aria-label="Less 5">−5</button>
        <button type="button" class="popup-btn popup-btn-secondary fa-step" data-step="-1" aria-label="Less 1">−1</button>
        <input type="number" class="fa-amount" min="1" max="${max}" value="${amount}" inputmode="numeric" aria-label="Water to transfer" />
        <button type="button" class="popup-btn popup-btn-secondary fa-step" data-step="1" aria-label="More 1">+1</button>
        <button type="button" class="popup-btn popup-btn-secondary fa-step" data-step="5" aria-label="More 5">+5</button>
        <button type="button" class="popup-btn fa-all" title="Transfer the maximum">Max (${max})</button>
      </div>
      <div class="turn-confirm-actions">
        <button type="button" class="popup-btn primary" data-act="yes">💧 Transfer <span class="fa-n">${amount}</span></button>
        <button type="button" class="popup-btn" data-act="no">Cancel</button>
      </div>
    `;
    const input = panel.querySelector('.fa-amount');
    const nLabel = panel.querySelector('.fa-n');
    const clamp = (v) => Math.max(1, Math.min(max, Math.round(Number(v)) || 1));
    const set = (v) => { amount = clamp(v); input.value = String(amount); nLabel.textContent = String(amount); };
    panel.querySelectorAll('.fa-step').forEach((b) => b.addEventListener('click', () => set(amount + Number(b.dataset.step))));
    panel.querySelector('.fa-all').addEventListener('click', () => set(max));
    input.addEventListener('input', () => set(input.value));
    panel.querySelector('[data-act="yes"]').addEventListener('click', () => close(amount));
    panel.querySelector('[data-act="no"]').addEventListener('click', () => close(null));
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

// Factory-Refuel handler (rulebook I5b). Adds water FTs to the
// rocket tank up to the cap; consumes the per-turn op and the
// per-site refuel lock. The flat 7-water yield is the "blue FT"
// rulebook value; the gold-FT (isotope) variant lands when
// isotope storage exists. Caller has already validated that a
// player-owned factory exists at the site, the rocket is parked,
// and tank headroom > 0.
function doFactoryRefuel(site, gain) {
  if (gain <= 0) return;
  // Online: the server runs the factory's flat +7 refine and spends the
  // op (gain is recomputed server-side); the snapshot repaints the tank.
  if (_online) {
    const sid = toServerId(_onlineMaps, site.id);
    if (!sid) { _onlineToast('That site is not on the map.', 'error'); return; }
    submitOnlineOp({ kind: 'SITE_REFUEL', siteId: sid, mode: 'factory' });
    return;
  }
  if (!requireOp('Factory-Refuel')) return;
  const tankBefore = getTankWater();
  const tmax = getTankMax();
  loadFuel(gain);   // walk the red line so the wet chit lands on a node
  markRefueledThisTurn(site.id);
  setStatus(
    `🏭 Factory-Refuel at <strong>${esc(site.name)}</strong>: `
    + `<strong>+${gain}</strong> water (factory produces 7 blue FTs, clamped by tank cap). `
    + `Tank ${tankBefore} → <strong>${tankBefore + gain}</strong>/${tmax}.`
  );
  logAction({
    type: 'factory_refuel',
    icon: '🏭',
    summary: `Factory-Refuel at ${site.name}: +${gain} water; tank ${tankBefore + gain}/${tmax}`,
    undoable: false,
    data: { siteId: site.id, gain, tankAfter: tankBefore + gain },
  });
  openFuelTankModal({ fromWater: tankBefore, toWater: tankBefore + gain });
}

// Refuel yield breakdown (user 2026-07-22): when a water refuel is boosted by
// an ability (Femtochemistry / Atmospheric Scoop / an ISRU modifier) or rides a
// colocated Miner's free repeat, show a popup that spells out how the base yield
// becomes the final fuel so the effect is unmistakable. Ability bonuses ride the
// player's OWN stack + colonists, so they apply at ANY usable factory - your own
// OR an opponent's granted one (the server applies them regardless of owner).
// Returns { mode, lines:[{icon,label,detail}], preClamp, room, finalGain, clamped,
// minerFree, hasEffects, tank, tmax }. `hasEffects` is the popup trigger.
function buildRefuelBreakdown(site, mode) {
  const tank = getTankWater();
  const tmax = getTankMax();
  const room = Math.max(0, tmax - tank);
  const lines = [];
  let gain = 0;
  let scoop = false, isruMod = 0;
  if (mode === 'factory') {
    gain = 7;
    lines.push({ icon: '🏭', label: 'Factory output', detail: '7 water (flat)' });
  } else {
    const isAerostat = siteIsAerostat(site);
    const baseWater = Number.isFinite(site.hydration) ? site.hydration : 0;
    scoop = isAerostat && stackHasPower('aerostatHydration2') && baseWater < 2;
    const water = scoop ? 2 : baseWater;
    const prosp = getActiveProspectorStats();
    const rigIsru = prosp ? (prosp.isru | 0) : 0;
    isruMod = colocatedIsruMod({ isAerostat });
    const isru = Math.max(0, rigIsru + isruMod);
    gain = 1 + water - isru;
    lines.push({ icon: '💧', label: 'ISRU refine', detail: `1 + hydration ${water} - ISRU ${isru} = ${gain}` });
    if (scoop) lines.push({ icon: '🌫️', label: 'Atmospheric Scoop', detail: 'aerostat counts as hydration 2' });
    if (isruMod < 0) lines.push({ icon: '⚙️', label: 'ISRU modifier', detail: `rig ISRU ${rigIsru} lowered to ${isru}` });
  }
  // SCAVENGING (Femtochemistry): a colocated card doubles refuel FTs.
  const scavenge = stackHasPower('doubleSiteRefuel');
  if (scavenge) { gain *= 2; lines.push({ icon: '🧪', label: 'Femtochemistry (Scavenging)', detail: 'doubles the refuel: x2' }); }
  // Miner colonist: once you have already refined here this turn, a colocated
  // Miner grants the repeat for FREE (no operation spent).
  const minerFree = refuelIsMinerExtra(site.id);
  if (minerFree) lines.push({ icon: '⛏️', label: 'Miner colonist', detail: 'extra refine rides free - no operation spent' });
  const preClamp = Math.floor(gain);
  const finalGain = Math.min(preClamp, room);
  const clamped = finalGain < preClamp;
  const hasEffects = scavenge || scoop || isruMod < 0 || minerFree;
  return { mode, lines, preClamp, room, finalGain, clamped, minerFree, hasEffects, tank, tmax };
}

// Show the yield breakdown, then run `onConfirm` (the actual submit) if the
// player commits. If nothing special modifies the yield, skip the popup and run
// straight away so plain refuels stay one tap.
function previewThenRefuel(site, mode, onConfirm) {
  const bd = buildRefuelBreakdown(site, mode);
  if (!bd || !bd.hasEffects) { onConfirm(); return; }
  openRefuelYieldModal(site, bd, onConfirm);
}

function openRefuelYieldModal(site, bd, onConfirm) {
  document.querySelector('.refuel-yield-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay confirm-modal-overlay refuel-yield-overlay';
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  const rows = bd.lines.map((l) =>
    `<li class="refuel-yield-row"><span class="refuel-yield-ic">${l.icon}</span>`
    + `<span class="refuel-yield-name">${esc(l.label)}</span>`
    + `<span class="refuel-yield-detail">${esc(l.detail)}</span></li>`).join('');
  const clampNote = bd.clamped
    ? `<p class="refuel-yield-clamp muted">Your tank only has room for <strong>${bd.room}</strong> of the <strong>${bd.preClamp}</strong> refined (tank ${bd.tank}/${bd.tmax}).</p>`
    : '';
  const opNote = bd.minerFree
    ? '<p class="refuel-yield-op ok">Free action: the Miner colonist covers this refine, so it does NOT spend your operation.</p>'
    : '';
  const panel = document.createElement('div');
  panel.className = 'turn-confirm-panel refuel-yield-panel';
  panel.innerHTML = `
    <button type="button" class="modal-x" aria-label="Close (Esc)" title="Close (Esc)">×</button>
    <h3>⛽ Refuel yield at ${esc(site.name)}</h3>
    <p class="muted">With these effects, this refuel gives:</p>
    <ul class="refuel-yield-list">${rows}</ul>
    <div class="refuel-yield-total">You gain <strong>+${bd.finalGain} water</strong></div>
    ${clampNote}
    ${opNote}
    <div class="turn-confirm-actions">
      <button type="button" class="popup-btn primary" data-act="go">⛽ Refuel (+${bd.finalGain})</button>
      <button type="button" class="popup-btn" data-act="cancel">Cancel</button>
    </div>`;
  panel.querySelector('.modal-x').addEventListener('click', close);
  panel.querySelector('[data-act="cancel"]').addEventListener('click', close);
  panel.querySelector('[data-act="go"]').addEventListener('click', () => { close(); onConfirm(); });
  overlay.appendChild(panel);
  mountOverlay(overlay);
}

// Refuel chooser: one modal that lists every refuel available at a site,
// grouped by destination (the rocket tank vs a factory outpost) so the site
// popup carries a single "Refuel" button instead of one per fuel type +
// destination. `options` is the collected list from the popup builder, each
// { dest:'rocket'|'outpost', fuel:'water'|'isotope', label, disabled, reason,
// onClick }. Picking one runs its own onClick (which submits the op and clears
// the popup); disabled rows stay visible with their reason so the player can see
// what is blocked and why.
function openRefuelChooserModal(site, options) {
  document.querySelector('.refuel-chooser-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay refuel-chooser-overlay';
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  const groups = [
    { key: 'rocket', title: '🚀 Into the rocket tank', items: options.filter((o) => o.dest === 'rocket') },
    { key: 'outpost', title: '🏭 Into a factory outpost', items: options.filter((o) => o.dest === 'outpost') },
  ].filter((g) => g.items.length);
  const panel = document.createElement('div');
  panel.className = 'turn-confirm-panel refuel-chooser-panel';
  panel.innerHTML = `
    <button type="button" class="modal-x" aria-label="Close (Esc)" title="Close (Esc)">×</button>
    <h3>⛽ Refuel at ${esc(site.name)}</h3>
    <p class="muted">Refine the local fuel. Choose where it goes.</p>
    ${groups.map((g, gi) => `
      <div class="refuel-chooser-group">
        <div class="refuel-chooser-group-title">${g.title}</div>
        <div class="refuel-chooser-btns">
          ${g.items.map((o, i) => `
            <button type="button" class="modal-btn refuel-opt-btn${o.disabled ? '' : ' primary'}"
              data-gi="${gi}" data-i="${i}"${o.disabled ? ' disabled' : ''}
              title="${esc(o.reason || '')}">${esc(o.label)}</button>`).join('')}
        </div>
      </div>`).join('')}
  `;
  panel.querySelector('.modal-x').addEventListener('click', close);
  groups.forEach((g, gi) => g.items.forEach((o, i) => {
    if (o.disabled) return;
    const btn = panel.querySelector(`.refuel-opt-btn[data-gi="${gi}"][data-i="${i}"]`);
    if (btn) btn.addEventListener('click', () => { close(); o.onClick(); });
  }));
  overlay.appendChild(panel);
  mountOverlay(overlay);
}

// Dirt refuel lives in the fuel-tank modal (openFuelTankModal's dirt
// section), gated on the ACTIVE engine being a dirt thruster - it's fueling
// that engine, so it sits with the water controls, not in the site popup.

// Delivery (rulebook): ship a Black-Side card from an outpost at one of your
// Factories back to LEO. Cost: zones-from-Earth x2 (+1 if site number > 7)
// water, paid FROM THE OUTPOST'S tank. Spends the turn's operation.
function deliveryCost(site) {
  const zones = zonesFromEarthClient(site && site.solarZone);
  return zones * 2 + (siteSizeNumber(site) > 7 ? 1 : 0);
}
function doDelivery(site, letter, cardId) {
  // Online: the server moves the card + spends the outpost water; snapshot
  // repaints the LEO stack + outpost.
  if (_online) {
    const sid = toServerId(_onlineMaps, site.id);
    if (!sid) { _onlineToast('That site is not on the map.', 'error'); return; }
    submitOnlineOp({ kind: 'DELIVERY', siteId: sid, letter, cardId });
    return;
  }
  if (!requireOp('Delivery')) return;
  const outpost = getOutpost(letter);
  if (!outpost || outpost.siteId !== site.id) { setStatus('No outpost there to deliver from.'); return; }
  const idx = (outpost.cards || []).findIndex((c) => c.id === cardId);
  if (idx < 0) { setStatus('That card is not in the outpost.'); return; }
  if (outpost.cards[idx].face !== 'secondary') { setStatus('Only a Black-Side card can be delivered.'); return; }
  const cost = deliveryCost(site);
  if ((Number(outpost.tank) || 0) < cost) {
    setStatus(`Outpost ${esc(letter)} needs ${cost} water to deliver; it has ${outpost.tank | 0}.`);
    return;
  }
  outpost.tank = (Number(outpost.tank) || 0) - cost;
  removeCardFromOutpost(letter, idx);
  addCardToLeo({ id: cardId, kind: 'patent', face: 'secondary' });
  const card = PATENTS_BY_ID[cardId];
  setStatus(`📦 Delivered <strong>${esc(card ? card.name : cardId)}</strong> to LEO (cost ${cost} water from Outpost ${esc(letter)}).`);
  logAction({
    type: 'delivery', icon: '📦',
    summary: `Delivered ${card ? card.name : cardId} from ${site.name} to LEO (cost ${cost} water)`,
    undoable: false,
    data: { siteId: site.id, letter, cardId, cost },
  });
}

// Heliocentric-zone distance from Earth (mirror of engine.js#zonesFromEarth).
const ZONE_ORDER_CLIENT = ['Mercury', 'Venus', 'Earth', 'Mars', 'Ceres', 'Jupiter', 'Saturn', 'Uranus', 'Neptune'];
function zonesFromEarthClient(zone) {
  const i = ZONE_ORDER_CLIENT.indexOf(zone);
  return i < 0 ? 0 : Math.abs(i - ZONE_ORDER_CLIENT.indexOf('Earth'));
}

// Wipe browse.js module-local state that the global resets in
// card-market.js#resetSandboxEconomy can't reach: the rocket
// position, planned route, trail, the undo snapshot, the
// per-turn refuel-log key, and the renderer's overlay layers.
// Pure cleanup; safe to call multiple times.
function doBrowseLocalReset() {
  _rocketSiteId = null;
  persistRocketSite();
  _rocketTrail = [];
  persistRocketTrail();
  _plannedRoute = null;
  persistPlannedRoute();
  _moveSnapshot = null;
  if (_renderer) {
    _renderer.setRoute(null);
    _renderer.setRouteEndpoints(null, null);
    _renderer.setRocketTrail(null);
  }
  try { localStorage.removeItem(STORAGE_REFUEL_LOG); } catch {}
  try { localStorage.removeItem(STORAGE_DIRT_REFUEL_LOG); } catch {}
}

// Full sandbox reset (Reset-sandbox button). Composition of
// doBrowseLocalReset + the global resetSandboxEconomy from
// card-market.js. The Card Market mode flag is preserved so a
// player who has explicitly opted into Card Market doesn't get
// silently flipped back by a Reset click.
function doSandboxReset() {
  doBrowseLocalReset();
  resetSandboxEconomy({ keepMode: true });
}

// Research Auction handler (rulebook I2). Opens the auction
// modal in the current Card Market mode. On commit: the picked
// patent enters the player's hand; in Card Market mode the
// sacrificed Hand card returns to the library. Op gated inside
// the commit so cancel doesn't burn the turn.
// Research Auction entry point. Opens the 🛒 Cart pane - the
// cart IS the auction UI (only the top of each deck is
// auctionable, via each deck's Buy button). You CANNOT auction
// from the card library or from the deck-tap inspect modal;
// the cart is the single place purchases happen.
function doResearchAuction() {
  showPane('cart');
}

// Free Market handler (rulebook I3). Only callable in Card
// Market mode (UI gates on this). Sells one Hand card for
// FREE_MARKET_AQUA aqua. Op gated inside the commit.
// Income Operation handler (rulebook I1). Consumes the
// per-turn op and credits +1 aqua to the Bank. Simple; the
// op-budget check + the aqua mutation is the whole
// transaction.
const INCOME_AQUA = 1;
function doIncomeOp() {
  // Online: the server credits the aqua + spends the op; the snapshot repaints.
  if (_online) { submitOnlineOp({ kind: 'INCOME' }); return; }
  if (!requireOp('Income')) return;
  addAqua(INCOME_AQUA);
  setStatus(`💰 Income: <strong>+${INCOME_AQUA}</strong> aqua. Bank now <strong>${esc(String(getAqua()))}</strong>.`);
  logAction({
    type: 'income',
    icon: '💰',
    summary: `Income: +${INCOME_AQUA} aqua (bank ${getAqua()})`,
    undoable: false,
    data: { delta: INCOME_AQUA, bankAfter: getAqua() },
  });
}

// Pass the turn without taking any other operation. Passing defaults to
// Income, so the player banks +1 aqua rather than wasting the turn's
// operation. Online: the server credits the income on the no-op END_TURN
// (see engine.js#applyEndTurn). Solo: credit it locally, then end the turn
// through the existing toolbar handler (the op is spent by then, so the
// button ends the turn instead of reopening the ops menu).
async function passTurn() {
  if (_online) {
    if (myBerthOpen()) {
      _onlineToast('Exomigrate your open colonist berth before ending your turn.', 'error');
      const me = mySnapshotPlayer();
      if (me) openExomigrateModal(me);
      return;
    }
    await submitOnlineOp({ kind: 'END_TURN' });
    return;
  }
  if (getOpsRemaining() > 0) {
    addAqua(INCOME_AQUA);
    consumeOp();
    setStatus(`💰 Passed and took income: <strong>+${INCOME_AQUA}</strong> aqua. Bank now <strong>${esc(String(getAqua()))}</strong>.`);
    logAction({
      type: 'income',
      icon: '💰',
      summary: `Passed and took income: +${INCOME_AQUA} aqua (bank ${getAqua()})`,
      undoable: false,
      data: { delta: INCOME_AQUA, bankAfter: getAqua() },
    });
  }
  document.getElementById('turn-end')?.click();
}

// Operations menu - opened by tapping the toolbar "op:N" tag. The
// player's main decision aid: it lists what they can spend their
// one operation on this turn, with the always-available ops as
// one-tap shortcuts (Income first) and the context ops as hints.
function openOpsMenu() {
  document.querySelector('.ops-menu-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay ops-menu-overlay';
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });

  const ops = getOpsRemaining();
  const moves = getMovesRemaining();
  const market = getMarketMode() === MARKET_MODE.MARKET;
  const handN = getHandSlots().length;
  const opCls = ops > 0 ? '' : ' class="muted"';

  const panel = document.createElement('div');
  panel.className = 'ops-menu-panel';
  panel.innerHTML = `
    <button type="button" class="modal-x" aria-label="Close (Esc)" title="Close (Esc)">×</button>
    <h2 class="ops-menu-title">⚙ Operations this turn</h2>
    <p class="muted ops-menu-sub">You have <strong${opCls}>op:${ops}</strong> and <strong>move:${moves}</strong> left. One operation per turn - pick wisely.</p>
    <div class="ops-menu-list" id="ops-menu-now"></div>
    <h4 class="ops-menu-head">At a site - where you've landed, or your factories &amp; outposts</h4>
    <div class="ops-menu-list" id="ops-menu-sites"></div>
    <h4 class="ops-menu-head">Free actions (no op)</h4>
    <ul class="ops-menu-hints">
      <li>🌐 Colonize a factory (consumes a colocated crew)</li>
      <li>🗑 Discard hand cards (any number) · 🔄 Transfer · ♻ Decommission to hand</li>
      <li>🛸 Move the rocket (uses the move budget, not an op)</li>
    </ul>
  `;
  const now = panel.querySelector('#ops-menu-now');
  const addOp = (label, title, fn, enabled = true) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'ops-menu-op modal-btn stack';
    b.disabled = !enabled;
    b.innerHTML = label;
    b.title = title;
    b.addEventListener('click', () => { close(); fn(); });
    now.appendChild(b);
    return b;
  };
  const m0On = !!(_onlineSnapshot && _onlineSnapshot.m0);
  // M0 replaces Income with Fundraise (opens the assembly window to act). Off M0
  // it's the plain Income op.
  if (m0On) {
    addOp('🏛 Fundraise', 'Open the assembly: place / move a delegate and gain aqua. Costs one operation.',
      () => openAssemblyModal('fundraise'));
  } else {
    addOp('💰 Income (+1 aqua)', 'Take 1 Aqua from the Pool into your Bank. Costs one operation.', doIncomeOp);
  }
  // Tag this one so the tutorial coach can point Buggy straight at it once the
  // Operations menu is open (step 1: auction a card to earn Aqua).
  addOp('🎯 Research Auction', 'Open the card market / auction. Costs one operation.', doResearchAuction)
    .setAttribute('data-tut-target', 'auction');
  if (market) {
    addOp(`💱 Free Market (+${FREE_MARKET_AQUA} aqua)`,
      handN > 0 ? 'Sell a hand card for aqua. Costs one operation.' : 'No hand cards to sell.',
      doFreeMarket, handN > 0);
  }
  // Pass: take no other operation. Passing banks income (+1 aqua) and ends the
  // turn in one tap. Offered under M0 too (user decision 2026-07-01): Fundraise
  // is the fuller income op there, but a player declining the assembly should
  // not need three extra taps every turn just to pass.
  addOp('⏭ Pass &amp; take income (+1 aqua)',
    'Take no other operation: bank +1 aqua and end your turn.',
    passTurn);

  // Site-op shortcuts: sites where a site-op is possible (your
  // factories - refuel / ET / colonize; claimed discs without a
  // factory - industrialize). Each flies the map there and opens
  // the site popup, where the actual op buttons live.
  const sitesHost = panel.querySelector('#ops-menu-sites');
  const siteById = (id) => (_activeData && (_activeData.byId?.[id] || _activeData.sites.find((s) => s.id === id))) || null;
  const opSites = [];
  const seen = new Set();
  // The site the rocket has LANDED on (not LEO): prospect / refuel live here.
  // This is the contextual case the player hits most - park, then act.
  const landed = _rocketSiteId ? getRocketSite() : null;
  if (landed && !isLeoSite(landed)) {
    seen.add(landed.id);
    opSites.push({ site: landed, hint: '🛸 landed here · prospect / refuel' });
  }
  for (const f of (allFactories() || [])) {
    // Individuality (Freedom to Roam) surfaces an opponent's factory too: refuel /
    // ET / deliver work there (colonize stays owner-only, gated in the popup).
    const mineFac = f.ownerId === myOwnerId();
    if ((!mineFac && !iCanUseLaw('individuality')) || seen.has(f.siteId)) continue;
    const site = siteById(f.siteId); if (!site) continue;
    seen.add(f.siteId);
    const acts = mineFac ? 'refuel / ET / deliver / colonize' : 'refuel / ET / deliver (Freedom to Roam)';
    opSites.push({ site, hint: `🏭 factory${getColony(f.siteId) ? ' + 🌐' : ''} · ${acts}` });
  }
  // getDiscs() is a { siteId: disc } map, not an array.
  const discs = getDiscs() || {};
  // Only YOUR successful claims can be industrialized - the server rejects
  // industrializing another player's claim. In multiplayer that's the local
  // player (whose turn it is): skip discs other players claimed. Sandbox discs
  // carry no owner, so they're all yours.
  const myClaimOwner = _online ? mySeatId() : null;
  for (const siteId of Object.keys(discs)) {
    const d = discs[siteId];
    if (!d || d.outcome !== 'success' || seen.has(siteId) || getFactory(siteId)) continue;
    if (myClaimOwner && d.ownerId && d.ownerId !== myClaimOwner) continue;
    const site = siteById(siteId); if (!site) continue;
    seen.add(siteId);
    opSites.push({ site, hint: '🔭 claimed · industrialize here' });
  }
  // Outposts: sites where you have a stack parked (deliver / transfer).
  for (const op of Object.values(getOutposts() || {})) {
    if (!op || !op.siteId || seen.has(op.siteId)) continue;
    const site = siteById(op.siteId); if (!site) continue;
    seen.add(op.siteId);
    opSites.push({ site, hint: `📦 Outpost ${op.letter || ''} · deliver / transfer` });
  }
  if (sitesHost) {
    if (!opSites.length) {
      sitesHost.innerHTML = '<p class="muted ops-menu-emptyhint">No site actions here yet. Land the rocket on a site to prospect / refuel it, or build a factory / outpost to act there. At LEO, use Boost / Income / Auction above.</p>';
    } else {
      for (const { site, hint } of opSites) {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'ops-menu-op ops-menu-site modal-btn stack';
        b.innerHTML = `📍 ${esc(site.name)} <span class="ops-site-hint">${esc(hint)}</span>`;
        b.title = `Fly to ${site.name} and open its site actions`;
        b.addEventListener('click', () => {
          close();
          if (_renderer && typeof _renderer.flyTo === 'function') _renderer.flyTo(site, locateZoom(4));
          showSitePopupFor(site);
        });
        sitesHost.appendChild(b);
      }
    }
  }

  overlay.appendChild(panel);
  panel.querySelector('.modal-x').addEventListener('click', close);
  mountOverlay(overlay);
}

function doFreeMarket() {
  if (getMarketMode() !== MARKET_MODE.MARKET) {
    setStatus('Free Market is only available in Card Market mode.');
    return;
  }
  const handIds = getHandSlots();
  if (!handIds.length) return;
  openFreeMarketModal({
    handIds,
    lookupCard: cardById,
    renderCardFn: renderCard,
    onCommit: ({ cardId }) => {
      if (!cardId) return;
      // Online: Free Market is the server FREE_MARKET op (sells the
      // card, credits aqua, spends the op). Submit + re-hydrate; skip
      // the local mutation that never persisted.
      if (_online) {
        // Freedom (Free Trade Act): offer pairing this card with a second for 5.
        const first = cardById(cardId);
        if (first && iCanUseLaw('freedom')) { openFreeTradeModal(first); return; }
        submitOnlineOp({ kind: 'FREE_MARKET', cardId });
        return;
      }
      if (!requireOp('Free Market')) return;
      const card = cardById(cardId);
      if (!card) {
        setStatus(`Free Market failed - unknown card ${esc(cardId)}.`);
        return;
      }
      if (!removeFromHand(cardId)) {
        setStatus(`Free Market failed - card not in hand.`);
        return;
      }
      // Sold card goes to the BOTTOM of its corresponding
      // deck (variant rule, user 2026-05-24: "free market
      // card ... goes to the back of the deck"). Routes by
      // type via addToBottom.
      addToBottom(cardId);
      addAqua(FREE_MARKET_AQUA);
      setStatus(
        `💱 Sold <em>${esc(card.name)}</em> for <strong>+${FREE_MARKET_AQUA}</strong> aqua. `
        + `Card returns to the bottom of the ${esc(card.type || 'patent')} deck.`
      );
      logAction({
        type: 'free_market',
        icon: '💱',
        summary: `Sold ${card.name} for +${FREE_MARKET_AQUA} aqua (Free Market)`,
        undoable: false,
        data: { cardId, aqua: FREE_MARKET_AQUA },
      });
    },
  });
}

// Resolve a hand/stack slot id to its underlying card record
// (patents or crew). Module-level helper so the popup builders
// and the Stage-3 op handlers all share one lookup; mirrors the
// two `const lookup` helpers that live inside the larger UI
// closures.
function cardById(id) {
  return PATENTS_BY_ID[id] || CREW_BY_ID[id] || null;
}

// ET Production handler (rulebook I8). Caller has validated
// that a player-owned factory is at the site, the rocket is
// parked, and there's at least one spectral-matching hand
// card with either an outpost present or a free slot. Op cost
// is committed inside the modal commit so cancelling doesn't
// burn the turn.
// The player's own Anchored Bernal that a Factory site is Dirtside to, if any,
// so ET Produce can deliver the product UP to it (I8). siteId is the CLIENT
// planner id of the factory site. Returns { bn, name, siteClientId } or null.
// Online + M2 only (Bernals live only in the server game).
function myDirtsideBernalForFactorySite(siteId) {
  if (!_online || !isM2()) return null;
  const me = mySnapshotPlayer();
  if (!me) return null;
  const siteSlug = (_onlineMaps && toServerId(_onlineMaps, siteId)) || siteId;
  const bn = (me.bernals || []).find((b) =>
    b && b.anchored && clientBernalDirtsideSlugs(b.siteId).includes(siteSlug));
  if (!bn) return null;
  const card = cardById(bn.cardId);
  const siteClientId = (_onlineMaps && toPlannerId(_onlineMaps, bn.siteId)) || bn.siteId;
  return { bn, name: (card && card.name) || 'the Bernal', siteClientId };
}
function doEtProduce(site, factory, options, outpostsAtSite, freeSlots) {
  const existingOutpost = outpostsAtSite.length > 0 ? outpostsAtSite[0].letter : null;
  // I8: if this Factory is Dirtside to one of my anchored Bernals, the product
  // may ride UP to it - into the Bernal's own stack, or an Outpost at the
  // Bernal's Space. Gather that Bernal's colocated outposts (same free-slot pool).
  const dirtBn = myDirtsideBernalForFactorySite(site.id);
  let bernal = null;
  if (dirtBn) {
    const bnOutposts = Object.values(getOutposts()).filter((o) => o.siteId === dirtBn.siteClientId);
    bernal = {
      name: dirtBn.name,
      existingOutpost: bnOutposts.length > 0 ? bnOutposts[0].letter : null,
      freeSlots,
    };
  }
  openEtProduceModal({
    siteName: site.name,
    factorySpectral: factory.spectralType,
    options,
    existingOutpost,
    freeSlots,
    bernal,
    onCommit: ({ cardId, letter, isNewOutpost, radSide, toBernal }) => {
      // A Bernal-Stack delivery carries no letter; every other destination does.
      if (!cardId || (!letter && !toBernal)) return;
      // Online: the server moves the hand card into the chosen destination
      // Black-Side-up; the snapshot repaints. radSide is the radiator's chosen
      // deployed side (Light / Heavy), ignored by non-radiators. toBernal (with
      // no letter) lands it in the Bernal's stack; toBernal + letter lands it in
      // an outpost at the Bernal's Space.
      if (_online) {
        const sid = toServerId(_onlineMaps, site.id);
        if (!sid) { _onlineToast('That site is not on the map.', 'error'); return; }
        // Building a hand ROBOT colonist may overflow the colonist limit
        // (2C2b Downsizing): pick who retires up front so the op carries it.
        const cardHere = cardById(cardId);
        if (cardHere && cardHere.type === 'colonist') {
          const me2 = mySnapshotPlayer();
          const held = me2 ? snapshotColonistSlots(me2) : [];
          const allowance = me2 ? snapshotColonistAllowance(me2) : 0;
          if (held.length + 1 > allowance) {
            openDownsizePicker(held, (downId) => {
              if (!downId) return;
              submitOnlineOp({ kind: 'ET_PRODUCE', siteId: sid, cardId, letter, isNewOutpost, downsizeColonistId: downId, ...(toBernal ? { toBernal: true } : {}) });
            });
            return;
          }
        }
        submitOnlineOp({ kind: 'ET_PRODUCE', siteId: sid, cardId, letter, isNewOutpost, radSide, ...(toBernal ? { toBernal: true } : {}) });
        return;
      }
      if (!letter) return;   // offline: only factory-site outposts (no Bernals)
      if (!requireOp('ET Production')) return;
      // If we need to create the outpost first, do that BEFORE
      // moving cards - otherwise addCardToOutpost will reject.
      if (isNewOutpost) {
        if (!createOutpost(letter, site.id)) {
          setStatus(`ET Produce failed - could not create Outpost ${esc(letter)}.`);
          return;
        }
      }
      const card = cardById(cardId);
      if (!card) {
        setStatus(`ET Produce failed - unknown card ${esc(cardId)}.`);
        return;
      }
      // Card moves from hand to outpost, Black-Side-up
      // (face='secondary'). removeFromHand first so the
      // addCard call doesn't trip the "already in hand" guard
      // if anything reads back through.
      removeFromHand(cardId);
      const added = addCardToOutpost(letter, {
        id: cardId,
        kind: 'patent',
        face: 'secondary',
        ...(radSide ? { radSide } : {}),
      });
      if (!added) {
        // Roll back: put card back in hand.
        addToHand(card);
        setStatus(`ET Produce failed - outpost ${esc(letter)} refused the card.`);
        return;
      }
      setStatus(
        `🏭 ET Produced <em>${esc(card.name)}</em> at <strong>${esc(site.name)}</strong> `
        + `into Outpost <strong>${esc(letter)}</strong> (Black-Side-up, spectral ${esc(factory.spectralType)}).`
        + (isNewOutpost ? ` New outpost created.` : '')
      );
      logAction({
        type: 'et_produce',
        icon: '🏭',
        summary: `ET Produced ${card.name} (Black-Side) at ${site.name} into Outpost ${letter}`
          + (isNewOutpost ? ' (new outpost)' : ''),
        undoable: false,
        data: {
          siteId: site.id, cardId, letter,
          factorySpectral: factory.spectralType,
          isNewOutpost,
        },
      });
    },
  });
}

// Single sandbox owner id - the local player. Used to tag
// factories + colonies until Stage 4 multi-player support
// arrives. Keeping it as a constant (rather than reading from a
// profile system that doesn't exist yet in the sandbox) is
// deliberate: when multi-player lands this becomes a parameter,
// not a runtime lookup.
const SANDBOX_OWNER_ID = 'sandbox-player';

// The owner id that marks "my" map tokens (factories, colonies, claimed
// discs). Online it's the local player's profile id (the SAME id the server
// stamps on the records it sends back); in the solo sandbox there's a single
// owner, the sandbox player. Every "is this mine?" check goes through here so
// the same UI code works in both modes instead of assuming the sandbox owner
// (which silently hid your own factories / ops online).
function myOwnerId() {
  return _online ? mySeatId() : SANDBOX_OWNER_ID;
}

// ----- hot seat ("pass the device") -----
//
// On a hot-seat table ONE account owns every seat and plays them in turn from
// this browser. The whole client already asks "which player record is mine?"
// through a single pair of idioms (myOwnerId() and `_onlineMe.id`), so making
// THAT answer follow the seat is what makes every existing panel - rocket,
// hand, stacks, budget, laws, scoring - track the player whose turn it is,
// instead of each one needing a hot-seat branch.
//
// In any normal game these helpers return the account id unchanged, so nothing
// about a non-hot-seat table changes by a single byte.

// The seat currently being played, when the local player owns the whole table.
// Null otherwise. Set from the snapshot on every apply (the seat the table is
// waiting on) and overridable by the player, so they can look at another seat.
let _hotSeatSeatId = null;

// Is the CURRENT online game a hot-seat table that I own?
function isHotSeatGame() {
  return !!(_online && !_spectator && _onlineSnapshot && _onlineMe
    && isHotSeatOwner(_onlineSnapshot, _onlineMe.id));
}

// Every seat I am playing. The whole table on a hot seat; just my own otherwise.
function mySeats() {
  if (!_onlineSnapshot || !Array.isArray(_onlineSnapshot.players)) return [];
  if (isHotSeatGame()) return _onlineSnapshot.players.slice();
  const mine = _onlineSnapshot.players.find((p) => p.profileId === (_onlineMe && _onlineMe.id));
  return mine ? [mine] : [];
}

// THE identity accessor: which player record the UI should treat as "me" right
// now. The account, except on a hot-seat table where it is the seat in play.
function mySeatId() {
  if (isHotSeatGame()) {
    const players = _onlineSnapshot.players || [];
    // Trust the stored seat only while it is still at the table.
    if (_hotSeatSeatId != null && players.some((p) => String(p.profileId) === String(_hotSeatSeatId))) {
      return _hotSeatSeatId;
    }
    const waiting = hotSeatWaitingOn(_onlineSnapshot);
    if (waiting != null) return waiting;
  }
  return _onlineMe && _onlineMe.id;
}

// The player record for the seat in play.
function mySeatPlayer() {
  const id = mySeatId();
  return (_onlineSnapshot && (_onlineSnapshot.players || []).find((p) => p.profileId === id)) || null;
}

// Stamp every outgoing op with the SEAT it is played as, then submit. On a
// hot-seat table the server needs to know which of my seats is acting (during
// an auction the table waits on several at once, so there is no single active
// player to infer). In any normal game `actAs` is simply my own account id,
// which is what the server would have used anyway, so this changes nothing.
// Every op in this module goes out through here.
function submitSeatOp(gameId, op, token) {
  return submitGameOp(gameId, { ...op, actAs: mySeatId() }, token);
}

// Point the UI at a different seat. Only meaningful on a hot-seat table; the
// caller re-renders. Returns true when the seat actually changed.
function setHotSeat(profileId) {
  if (!isHotSeatGame()) return false;
  const players = _onlineSnapshot.players || [];
  if (!players.some((p) => String(p.profileId) === String(profileId))) return false;
  if (String(_hotSeatSeatId) === String(profileId)) return false;
  _hotSeatSeatId = profileId;
  return true;
}

// The M0 ideology laws THIS player may benefit from right now: every law in
// force (the active gold-star law, plus any Unity also activates) is usable by
// ANYONE on their turn (O3b/O5: no delegate needed to USE an active law), plus
// any INACTIVE law they spent a Lobby free action on this turn. Mirror of the
// server's playerCanUseLaw, read off the cached snapshot. Empty when not online
// or not an M0 game.
function myActiveLaws() {
  const snap = _onlineSnapshot;
  if (!_online || !snap || !snap.m0 || !snap.assembly) return new Set();
  const myId = mySeatId();
  const me = (snap.players || []).find((p) => p.profileId === myId);
  const usable = new Set(Array.isArray(me && me.lobbiedLaws) ? me.lobbiedLaws : []);
  for (const key of assemblyActiveLaws(snap.assembly, snap.activeLawStar, !!snap.ceoSolo, !!snap.anarchy).active) {
    usable.add(key);
  }
  return usable;
}
function iCanUseLaw(key) { return myActiveLaws().has(key); }
// May this player USE the given factory for a NON-VICTORY op (Site Refuel, ET
// Produce, Delivery)? Their own always; an opponent's only under Individuality
// (Freedom to Roam). Mirror of the server's canUseFactoryNonVictory. Victory
// builds (Homesteading a colony) stay owner-only and must NOT call this.
function iCanUseFactory(factory) {
  if (!factory) return false;
  if (factory.ownerId === myOwnerId()) return true;
  if (iCanUseLaw('individuality')) return true;
  // Owner-granted standing access (Request -> Grant). Grants ride on the factory
  // record in the snapshot, keyed by profile id. Mirror of the server's
  // canUseFactoryNonVictory so a refuel / ET-produce the client offers is never
  // rejected for the same factory.
  if (factory.grants && factory.grants[String(myOwnerId())]) return true;
  return false;
}

// Industrialize handler (rulebook I7). The caller has already
// validated that the rocket is parked at a claimed site with no
// existing factory AND that findIndustrializeOptions(stack)
// returned at least one valid pair; we just open the modal and
// commit when the player confirms.
//
// Important: the op cost is consumed inside the modal commit
// callback (NOT at popup-click time) so cancelling the modal
// doesn't burn the turn. The chain cards are removed from the
// stack in reverse-index order so splices don't shift indices
// we haven't visited yet.
// Out of cubes for a factory: pick a delegate on the assembly to remove (frees
// one cube). Resolves the chosen place, or null if cancelled. M0 only.
function promptFreeDelegate(snapshot) {
  return new Promise((resolve) => {
    const myId = mySeatId();
    const dmap = (snapshot.assembly && snapshot.assembly.delegates) || {};
    const places = ASSEMBLY_PLACES.filter((p) => ((dmap[p] || {})[myId] | 0) > 0);
    if (!places.length) { _onlineToast('No delegates to remove - all 7 cubes are factories.', 'error'); resolve(null); return; }
    const back = document.createElement('div');
    back.className = 'mp-modal-back';
    const modal = document.createElement('div');
    modal.className = 'mp-trade-builder-modal';
    modal.style.maxWidth = '420px';
    const done = (v) => { back.remove(); resolve(v); };
    const h = document.createElement('div');
    h.className = 'mp-trade-head';
    h.innerHTML = '<h3>No cubes left</h3>';
    modal.appendChild(h);
    const note = document.createElement('div');
    note.className = 'mp-trade-colo no-colo';
    note.textContent = 'All 7 of your cubes are in play. Remove a delegate from the assembly to free a cube for this factory.';
    modal.appendChild(note);
    const list = document.createElement('div');
    list.className = 'mp-relocate-list';
    for (const p of places) {
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'modal-btn mp-relocate-item';
      b.textContent = 'Remove from ' + (p === 'centrist' ? 'Centrist' : (ASSEMBLY_IDEOLOGY_BY_KEY[p] || {}).name || p);
      b.addEventListener('click', () => done(p));
      list.appendChild(b);
    }
    modal.appendChild(list);
    const btns = document.createElement('div');
    btns.className = 'mp-trade-btns';
    const cancel = document.createElement('button');
    cancel.type = 'button'; cancel.className = 'modal-btn'; cancel.textContent = 'Cancel';
    cancel.addEventListener('click', () => done(null));
    btns.appendChild(cancel);
    modal.appendChild(btns);
    back.appendChild(modal);
    back.addEventListener('click', (e) => { if (e.target === back) done(null); });
    document.body.appendChild(back);
  });
}

// V5 Hermes Fall: industrializing one of the asteroid's halves must ALSO
// decommission an operational dirt rocket. Keyed off the node's SERVER slug,
// which is what data/hermes.js indexes (same idiom as the hermesAuto prospect
// read). MODULE scope on purpose - both the site popup that builds the options
// and doIndustrialize, which hands the flag to the modal's re-resolves, call it,
// and they live in different functions.
function hermesNeedsDirtRocket(site) {
  if (!isHermes() || !site) return false;
  return isHermesSite(String(site.id2 || site.id));
}
// `from` is the stack that holds the build set: 'rocket' (default) or an
// 'outpostX' letter. Sent to the server so it decommissions from the right
// stack, mirroring PROMOTE. The offline sandbox only ever builds from the rocket.
function doIndustrialize(site, stack, options, from = 'rocket') {
  openIndustrializeModal({
    siteName: site.name,
    spectralType: site.spectralType || 'C',
    stack,
    options,
    crewReactorKinds: myCrewReactorKinds(),
    // The modal re-resolves options through resolveOption, so it needs the same
    // Hermes flag the option list was built with or the dirt rocket is rebuilt
    // away between opening the modal and pressing the button.
    requireDirtRocket: hermesNeedsDirtRocket(site),
    onCommit: (opt) => {
      if (!opt) return;
      // Online: the server flips the claim to a factory + decommissions the
      // chain to hand; the snapshot repaints. Send the chosen chain ids.
      if (_online) {
        const sid = toServerId(_onlineMaps, site.id);
        if (!sid) { _onlineToast('That site is not on the map.', 'error'); return; }
        const cardIds = opt.chainIndices.map((idx) => stack[idx] && stack[idx].id).filter(Boolean);
        const snap = _onlineSnapshot || {};
        // Shared 7-cube pool: a factory needs a free cube. If the pool is full
        // (M0 delegates competing), offer to free one by removing a delegate.
        if (snap.m0 && myCubesFree(snap) <= 0) {
          promptFreeDelegate(snap).then((place) => {
            if (place) submitOnlineOp({ kind: 'INDUSTRIALIZE', siteId: sid, cardIds, freeDelegate: place, from });
          });
          return;
        }
        submitOnlineOp({ kind: 'INDUSTRIALIZE', siteId: sid, cardIds, from });
        return;
      }
      if (!requireOp('Industrialize')) return;
      // Remove chain cards in reverse index order so earlier
      // indices stay valid as we splice. Radiators were already
      // filtered out into opt.keptRadiators and are NOT in
      // chainIndices.
      const removed = [];
      for (const idx of [...opt.chainIndices].sort((a, b) => b - a)) {
        const slot = stack[idx];
        if (!slot) continue;
        // Crew NEVER gets decommissioned / removed by industrialize
        // (it can only move stack-to-stack or become a colony). Hard
        // guard so a crew slot can never silently vanish here.
        if (slot.kind === 'crew' || CREW.some((c) => c.id === slot.id)) continue;
        const ok = rocketRemoveCard(idx);
        if (ok) {
          removed.push(slot.id);
          // Variant rule (user, 2026-05-24): industrialize-
          // decommissioned cards return to the player's HAND
          // (NOT to the deck bottom - that earlier reading
          // was the user's pre-clarification draft). The
          // refinery + robonaut + support chain you spent
          // are re-collectable, not consumed.
          const reclaim = PATENTS_BY_ID[slot.id];
          if (reclaim) addToHand(reclaim);
        }
      }
      const spectral = site.spectralType || 'C';
      const built = createFactory(site.id, myOwnerId(), spectral);
      const refName = opt.refinery.card.name;
      const robName = opt.robonaut.card.name;
      const orphanNote = opt.orphans.length
        ? ` ⚠ ${opt.orphans.map((o) => o.card.name).join(', ')} now inactive (lost support).`
        : '';
      const keptNote = opt.keptRadiators.length
        ? ` Kept: ${opt.keptRadiators.map((r) => r.card.name).join(', ')}.`
        : '';
      if (built) {
        setStatus(
          `🏭 Industrialized <strong>${esc(site.name)}</strong> `
          + `(spectral ${esc(spectral)}). `
          + `Decommissioned <em>${esc(refName)}</em> + <em>${esc(robName)}</em>`
          + ` + ${removed.length - 2} support card${removed.length - 2 === 1 ? '' : 's'}.`
          + `${keptNote}${orphanNote}`
        );
        logAction({
          type: 'industrialize',
          icon: '🏭',
          summary: `Industrialized ${site.name} (spectral ${spectral}); `
            + `decommissioned ${removed.length} card${removed.length === 1 ? '' : 's'} `
            + `(refinery ${refName} + robonaut ${robName}` +
            (opt.orphans.length ? `; orphans: ${opt.orphans.map((o) => o.card.name).join(', ')}` : '') + ')',
          undoable: false,
          data: {
            siteId: site.id,
            spectralType: spectral,
            decommissioned: removed,
            keptRadiators: opt.keptRadiators.map((r) => r.id),
            orphans: opt.orphans.map((o) => o.id),
          },
        });
      } else {
        setStatus(`Industrialize failed to record - factory may already exist at ${esc(site.name)}.`);
      }
    },
  });
}

// Build Colony handler (rulebook G3, free action). The caller
// has already validated that the site has a player-owned
// factory, no existing colony, the player is under the cap,
// and at least one colocated Crew card exists.
//
// One crew -> auto-commit (picker is skipped). Multiple crews
// -> picker modal. On commit: the chosen crew slot is removed
// from the stack and the underlying crew card returns to the LEO
// Stack intact (crew always re-spawns in LEO). The colony dome is
// created on the factory.
//
// Free action: no requireOp call.
// After a Crew founds a Colony, ask where the crew re-settles: the Home Bernal
// or the LEO Stack (user 2026-07-07). cb(crewTo) with 'bernal<idx>' | 'leo', or
// cb(null) if the player cancels. Only called when a Home Bernal exists.
function chooseCrewColonyDest(home, cb, idx) {
  const card = cardById(home.cardId);
  const bernalName = `${(card && card.name) || 'Home Bernal'} (${bernalLocLabel(home)})`;
  const back = document.createElement('div');
  back.className = 'mp-modal-back';
  const modal = document.createElement('div');
  modal.className = 'mp-trade-builder-modal';
  modal.style.maxWidth = '420px';
  let done = false;
  const finish = (val) => { if (done) return; done = true; back.remove(); cb(val); };
  modal.innerHTML = `<div class="mp-trade-head"><h3>🌐 Where does the crew settle?</h3></div>
    <p class="muted" style="margin:0 0 12px">The colony dome stays on the factory. Send the freed crew to your Home Bernal or the LEO Stack.</p>`;
  const btns = document.createElement('div');
  btns.className = 'mp-trade-btns';
  btns.style.flexWrap = 'wrap';
  const bBernal = document.createElement('button');
  bBernal.type = 'button'; bBernal.className = 'modal-btn primary';
  bBernal.textContent = `🛰 ${bernalName}`;
  bBernal.addEventListener('click', () => finish(`bernal${idx}`));
  const bLeo = document.createElement('button');
  bLeo.type = 'button'; bLeo.className = 'modal-btn';
  bLeo.textContent = '🌍 the LEO Stack';
  bLeo.addEventListener('click', () => finish('leo'));
  const bCancel = document.createElement('button');
  bCancel.type = 'button'; bCancel.className = 'modal-btn';
  bCancel.textContent = 'Cancel';
  bCancel.addEventListener('click', () => finish(null));
  btns.append(bBernal, bLeo, bCancel);
  modal.appendChild(btns);
  back.appendChild(modal);
  back.addEventListener('click', (e) => { if (e.target === back) finish(null); });
  document.body.appendChild(back);
}
function doColonize(site, stack, options) {
  openColonizePicker({
    siteName: site.name,
    options,
    onCommit: (pick) => {
      if (!pick) return;
      // Online: the server settles the crew (returns it to LEO) and places
      // the colony; the snapshot repaints the colony ring. Build Colony is a
      // FREE action server-side, so no op is spent.
      if (_online) {
        // Send the colony's location type (the client has the site flags; the
        // server doesn't) so the server scores it by type at game end.
        const colonyType = colonyTypeOfSite(site.id) || 'other';
        const isCrew = pick.settlerKind === 'crew' || !!CREW_BY_ID[pick.id];
        const home = isCrew ? myHomeBernal() : null;
        // A settling COLONIST returns to the colonist deck (no choice). A settling
        // CREW re-settles at the player's chosen station: their Home Bernal or the
        // LEO Stack (user 2026-07-07). With no Home Bernal there's nothing to pick.
        if (home) {
          const idx = getMyBernals().indexOf(home);
          chooseCrewColonyDest(home, (crewTo) => {
            if (crewTo == null) return;   // cancelled
            submitOnlineOp({ kind: 'BUILD_COLONY', cardId: pick.id, colonyType, crewTo });
          }, idx);
        } else {
          submitOnlineOp({ kind: 'BUILD_COLONY', cardId: pick.id, colonyType });
        }
        return;
      }
      const crewCard = CREW_BY_ID[pick.id];
      if (!crewCard) {
        setStatus(`Colonize aborted - unknown crew id ${esc(pick.id)}.`);
        return;
      }
      // Re-find by id at commit time in the SOURCE the picker tagged (rocket
      // or a colocated outpost) - splices may have shifted indices since the
      // modal opened. removeCrew() pulls it and returns a restore() that puts
      // it back in the same place if a later step fails.
      const src = pick.source || 'rocket';
      let crewFace = null;
      let restore = null;
      if (src === 'rocket') {
        const cur = getRocketStack();
        const idx = cur.findIndex((s) => s.id === pick.id);
        if (idx === -1) {
          setStatus(`Colonize aborted - crew ${esc(pick.id)} is no longer in the stack.`);
          return;
        }
        crewFace = cur[idx].face;
      } else {
        const letter = src.outpost;
        const o = getOutpost(letter);
        const idx = (o && o.cards || []).findIndex((s) => s.id === pick.id);
        if (idx === -1) {
          setStatus(`Colonize aborted - crew ${esc(pick.id)} is no longer in Outpost ${esc(letter)}.`);
          return;
        }
        crewFace = o.cards[idx].face;
      }
      // Suppress per-crew reconciliation across the mutation dance:
      // we remove the crew, and roll it back on failure. Colonise
      // resolves the crew's own chits explicitly on success below.
      _suppressChitReconcile = true;
      try {
      if (src === 'rocket') {
        const cur = getRocketStack();
        const idx = cur.findIndex((s) => s.id === pick.id);
        if (idx === -1 || !rocketRemoveCard(idx)) {
          setStatus(`Colonize aborted - could not remove crew from stack.`);
          return;
        }
        restore = () => rocketAddCard(pick.id, 'crew', crewFace);
      } else {
        const letter = src.outpost;
        const o = getOutpost(letter);
        const idx = (o && o.cards || []).findIndex((s) => s.id === pick.id);
        if (idx === -1) {
          setStatus(`Colonize aborted - could not remove crew from Outpost ${esc(letter)}.`);
          return;
        }
        removeCardFromOutpost(letter, idx);
        restore = () => addCardToOutpost(letter, { id: pick.id, kind: 'crew', face: crewFace });
      }
      // Crew always re-spawns in the LEO Stack (variant rule,
      // user 2026-05). crewCard kept for naming only.
      void crewCard;
      const leoOk = addCardToLeo({ id: pick.id, kind: 'crew', face: crewFace });
      if (!leoOk) {
        // Roll back the removal so the crew isn't lost.
        restore();
        setStatus(`Colonize aborted - crew couldn't return to the LEO stack.`);
        return;
      }
      const created = createColony(site.id, myOwnerId());
      if (!created) {
        // Cap or duplicate. Roll back: pull crew back out of
        // the LEO stack, drop it back where it came from.
        removeCardFromLeoById(pick.id);
        restore();
        setStatus(`Colonize failed at <strong>${esc(site.name)}</strong> - cap or duplicate.`);
        return;
      }
      const crewName = pick.primary?.name || pick.card.id;
      setStatus(
        `🌐 Built colony at <strong>${esc(site.name)}</strong>. `
        + `<em>${esc(crewName)}</em> returns to your LEO Stack. `
        + `Colonies: <strong>${countColoniesByOwner(myOwnerId())}</strong>/${COLONY_CAP_PER_PLAYER}.`
      );
      logAction({
        type: 'colonize',
        icon: '🌐',
        summary: `Built colony at ${site.name} (crew ${crewName} returned to LEO stack); `
          + `${countColoniesByOwner(myOwnerId())}/${COLONY_CAP_PER_PLAYER} colonies`,
        undoable: false,
        data: { siteId: site.id, crewId: pick.id },
      });
      // The colonising crew leaves the rocket: ITS glory chits flip
      // face-up to their FRONT value (published rule: front = crew
      // colonised or died). Chits owned by other crews still aboard
      // stay carried and can still be brought home for the back value.
      const frontRes = resolveChitsForCrew(pick.id, 'front', `${crewName} colonised ${site.name}`);
      if (frontRes.vps) {
        logAction({
          type: 'glory_front',
          icon: '🎖',
          summary: `${frontRes.chits.length} glory chit${frontRes.chits.length === 1 ? '' : 's'} flipped face-up `
            + `for ${frontRes.vps} VP (${crewName} colonised instead of returning home)`,
          undoable: false,
        });
      }
      } finally {
        _suppressChitReconcile = false;
      }
    },
  });
}

// Fuel-tank modal. SVG cylinder; water rect grows from
// `fromWater` to `toWater` over ~1100 ms. Capacity = active
// thruster's max-liftable fuel (thrust - dryMass) when present,
// falling back to the engine's hard tank cap. Tap / click /
// Escape closes; tapping mid-animation skips to the end-state
// without dismissing so the player sees the final level.
// Lightweight confirm modal. Returns a Promise<boolean> that
// resolves true on the "yes" path, false on cancel / Esc /
// backdrop tap. Used for the afterburn engage prompt; future
// destructive actions can reuse it.
// After a successful online boost, the boosted cards sit in the LEO Stack and
// it's easy to forget to move them onto the rocket. If the rocket is at LEO
// (colocated with the LEO Stack), offer to transfer them now. `ids` are the
// just-boosted card ids; only those that actually landed in LEO are offered.
async function offerBoostTransfer(ids) {
  if (!_online || !_onlineSnapshot || !_onlineMe) return;
  const me = (_onlineSnapshot.players || []).find((p) => p.profileId === mySeatId());
  if (!me || !me.rocket) return;
  // Home stack -> rocket transfer needs the rocket at MY home base (or empty,
  // which forms there). A Siren's home is Cordelia, not LEO, so this asks where
  // my own stack stands rather than assuming Earth orbit.
  const home = homeSiteId();
  const where = homeLabel();
  const atHome = (me.rocket.siteId == null ? null : me.rocket.siteId) === home;
  const rocketEmpty = !((me.rocket.stack || []).length);
  if (!atHome && !rocketEmpty) return;
  const inLeo = new Set((me.leo || []).map((s) => s.id));
  const moveIds = (ids || []).filter((id) => inLeo.has(id));
  if (!moveIds.length) return;
  const n = moveIds.length;
  const names = moveIds.map((id) => cardLabel(id)).join(', ');
  const ok = await confirmModal({
    title: '🚀 Move boosted cards to your rocket?',
    body: `You boosted ${n} card${n === 1 ? '' : 's'} to your ${esc(where)} Stack (${esc(names)}). `
      + `Your rocket is at ${esc(where)} - load ${n === 1 ? 'it' : 'them'} onto the rocket now?`,
    yes: 'Transfer to rocket', no: `Leave in ${esc(where)}`,
  });
  if (!ok) return;
  await submitOnlineOp({ kind: 'TRANSFER', cardIds: moveIds, from: 'leo', to: 'rocket' });
}

// Pick the colony FIGURE (Kalpana spindle / Stanford torus) when CREATING a
// Bernal stack (boost or stack separation). The choice is fixed at creation
// (user 2026-06-27), so it is asked here, not in the in-play modal. Resolves to
// 'kalpana' | 'stanford' (defaults 'kalpana' on dismiss).
function chooseBernalFigure(card) {
  return new Promise((resolve) => {
    // Each Bernal figure (Kalpana / Stanford) is unique to a player: you can only
    // build a figure you have not built yet. Figures already on one of my Bernals
    // are shown greyed + unclickable ("already built"), and if only one is left
    // it is taken automatically (no choice to make).
    const used = new Set(getMyBernals().map((bn) => bn && bn.figure).filter(Boolean));
    const FIGS = [['kalpana', 'Kalpana', 'spindle'], ['stanford', 'Stanford', 'torus']];
    const avail = FIGS.filter(([fig]) => !used.has(fig));
    if (avail.length <= 1) { resolve((avail[0] && avail[0][0]) || 'kalpana'); return; }
    document.querySelector('.bernal-figure-pick-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay bernal-figure-pick-overlay';
    const panel = document.createElement('div');
    panel.className = 'card-modal-panel bernal-figure-pick';
    const title = document.createElement('h3');
    title.className = 'modal-title';
    title.textContent = '🏙 Choose the colony figure';
    panel.appendChild(title);
    const sub = document.createElement('p');
    sub.className = 'muted bernal-figure-pick-sub';
    sub.innerHTML = `Build <strong>${esc((card && card.name) || 'this Bernal')}</strong> on which figure? This is fixed once the colony is established.`;
    panel.appendChild(sub);
    const row = document.createElement('div');
    row.className = 'bernal-figure-pick-row';
    const colour = _online ? myRocketColour() : 'gold';
    const firstAvail = avail[0][0];
    const onKey = (e) => { if (e.key === 'Escape') done(firstAvail); };
    const done = (fig) => { overlay.remove(); document.removeEventListener('keydown', onKey); resolve(fig); };
    for (const [fig, label, kindSub] of FIGS) {
      const taken = used.has(fig);
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'bernal-figure-pick-btn' + (taken ? ' is-taken' : '');
      b.disabled = taken;
      const img = document.createElement('img');
      img.src = getBernalSprite(colour, { kind: fig }).src;
      img.alt = label;
      b.appendChild(img);
      const cap = document.createElement('div');
      cap.className = 'bernal-figure-pick-cap';
      cap.innerHTML = `<strong>${label}</strong> <span class="muted">${taken ? 'already built' : kindSub}</span>`;
      b.appendChild(cap);
      if (!taken) b.addEventListener('click', () => done(fig));
      row.appendChild(b);
    }
    panel.appendChild(row);
    overlay.appendChild(panel);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) done(firstAvail); });
    document.addEventListener('keydown', onKey);
    document.body.appendChild(overlay);
  });
}

// The Martian (H9b) driver: confirm (single mover) or pick (multiple), then
// submit the free action. The prompt spells out that the buggy stays put and it
// forms an Outpost, so the player is warned before committing.
async function driveMartian(site, toSiteId, movers) {
  let mover = movers[0];
  if (movers.length > 1) {
    mover = await pickMartianMover(movers, site.name);
    if (!mover) return;
  } else {
    const ok = await confirmModal({
      title: '🚙 The Martian',
      body: `Drive <b>${esc(mover.name)}</b> along the buggy road to <b>${esc(site.name)}</b>, forming an Outpost there? The buggy stays put. Free action (once per turn).`,
      yes: 'Drive', no: 'Cancel',
    });
    if (!ok) return;
  }
  const sent = await submitOnlineOp({ kind: 'THE_MARTIAN', from: 'rocket', humanCardId: mover.id, toSiteId });
  if (sent && _renderer && _renderer.clearSitePopup) _renderer.clearSitePopup();
}

// Pick which Crew / Colonist to drive when the rocket carries more than one.
// Resolves to the chosen { id, name } or null on cancel.
function pickMartianMover(movers, destName) {
  return new Promise((resolve) => {
    document.querySelector('.confirm-modal-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay';
    const close = (val) => { overlay.remove(); document.removeEventListener('keydown', onKey); resolve(val || null); };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(null); });
    const onKey = (e) => { if (e.key === 'Escape') close(null); };
    document.addEventListener('keydown', onKey);
    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel';
    panel.innerHTML = `
      <h3>🚙 The Martian</h3>
      <p>Drive who along the buggy road to <b>${esc(destName)}</b>? The buggy stays put; this forms an Outpost (free action, once per turn).</p>
      <div class="turn-confirm-actions" data-movers></div>
      <div class="turn-confirm-actions"><button type="button" class="popup-btn" data-act="no">Cancel</button></div>
    `;
    const row = panel.querySelector('[data-movers]');
    for (const m of movers) {
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'popup-btn primary'; b.textContent = m.name;
      b.addEventListener('click', () => close(m));
      row.appendChild(b);
    }
    panel.querySelector('[data-act="no"]').addEventListener('click', () => close(null));
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

function confirmModal({ title, body, yes = 'OK', no = 'Cancel' }) {
  return new Promise((resolve) => {
    document.querySelector('.confirm-modal-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay';
    const close = (val) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(!!val);
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(false); });
    const onKey = (e) => {
      if (e.key === 'Escape') close(false);
      else if (e.key === 'Enter') close(true);
    };
    document.addEventListener('keydown', onKey);
    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel';
    // Single-button (info) mode: pass no='' to hide the secondary
    // button so the modal reads as an acknowledge instead of a
    // yes/no. The remaining Yes resolves true on click + Enter.
    const noBtn = no
      ? `<button type="button" class="popup-btn" data-act="no">${esc(no)}</button>`
      : '';
    panel.innerHTML = `
      <h3>${esc(title)}</h3>
      <p>${body}</p>
      <div class="turn-confirm-actions">
        <button type="button" class="popup-btn primary" data-act="yes">${esc(yes)}</button>
        ${noBtn}
      </div>
    `;
    panel.querySelector('[data-act="yes"]').addEventListener('click', () => close(true));
    const noEl = panel.querySelector('[data-act="no"]');
    if (noEl) noEl.addEventListener('click', () => close(false));
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

// Boost confirm modal. Confirms the Aqua spend AND, for every radiator in the
// batch, lets the player pick its deployed light/heavy side - the choice LOCKS
// at construction (only radiation damage flips heavy -> light afterward), so
// this popup is the one chance to set it. Resolves { ok, radSides } where
// radSides maps each radiator id to 'light' | 'heavy' (default 'heavy', the
// max-cooling side). Cancel resolves { ok: false }.

// Mass a card adds when boosted = aqua cost contribution. A radiator's deployed
// side changes its mass (light = the base, heavy is heavier), so the side is
// passed through. Mirror of the server's boostMass in engine.js.
function boostMassOf(card, radSide) {
  if (card && card.type === 'radiator') {
    const f = card.faces && card.faces.primary;
    const side = radSide === 'light' ? 'light' : 'heavy';
    const blk = f && f[side];
    if (blk && blk.mass != null) return blk.mass | 0;
  }
  const f = (card && card.faces && card.faces.primary) || card || {};
  return (f.mass != null ? f.mass : (card && card.mass)) | 0;
}

// Aqua cost to boost direct to an anchored Bernal (mirror of the server's
// bernalBoostCost): doubled normally, plain mass only when the Bernal is the
// HOME Bernal AND its ability waives the doubling. Both waiver cards (GEO
// Elevator + L3 Lofstrom Loop) print the ability as "HOME: ... without doubling",
// so the waiver requires the Bernal to actually BE the Home Bernal (anchored at
// its Home Orbit). A GEO Elevator / Lofstrom anchored elsewhere doubles like any
// other Bernal. (Reading the card text alone waived the doubling for a GEO
// Elevator parked off-GEO - the bug. The GEO boost used to be free; nerfed to
// the card's text, user 2026-07-04.)
function bernalBoostCostClient(baseCost, bn, card) {
  const ability = (card && card.faces && card.faces.primary && card.faces.primary.ability)
    || (card && card.ability) || '';
  if (isHomeBernalUnit(bn) && /without doubling/i.test(ability)) return baseCost;
  return baseCost * 2;
}
// The player's anchored Bernals as boost destinations (online + M2 only): one
// entry per anchored colony with the data the boost modal needs to price + tag it.
function anchoredBoostTargets() {
  if (!_online || !isM2()) return [];
  return getMyBernals()
    .map((bn, i) => ({ bn, i }))
    // Only the HOME Bernal is a valid boost destination (the server enforces the
    // same); a Dirtside anchored Bernal raises the colonist allowance but is not
    // a boost / boarding station.
    .filter((x) => x.bn && x.bn.anchored && isHomeBernalUnit(x.bn))
    .map((x) => {
      const card = cardById(x.bn.cardId);
      const fig = x.bn.figure === 'stanford' ? 'Stanford' : 'Kalpana';
      return { id: `bernal${x.i}`, bn: x.bn, card, label: `${(card && card.name) || 'Bernal'} (${fig})`, isHome: isHomeBernalUnit(x.bn) };
    });
}

// Remembered boost side per radiator card id, set by flipping the card's
// Light/Heavy toggle while it sits in hand (see the card-ui hook below). The
// boost modal reads it as the per-radiator default so an in-hand flip carries
// through instead of the popup re-defaulting to Light every time.
const _radBoostSide = new Map();
function radBoostSidePref(id) {
  const s = _radBoostSide.get(id);
  return s === 'heavy' ? 'heavy' : (s === 'light' ? 'light' : null);
}
// Is this radiator currently in MY hand? Only then does an in-view flip persist
// as the boost default - flipping a radiator I don't hold (a catalog preview,
// an opponent's stack) must not silently set my launch preference.
function radiatorInMyHand(id) {
  const c = PATENTS_BY_ID[id];
  if (!c || c.type !== 'radiator') return false;
  if (_online) {
    const me = mySnapshotPlayer();
    return !!(me && Array.isArray(me.hand) && me.hand.includes(id));
  }
  try { return getHandSlots().includes(id); } catch { return false; }
}
setRadBoostSideHook({
  get: (id) => radBoostSidePref(id),
  set: (id, side) => { if (radiatorInMyHand(id)) _radBoostSide.set(id, side === 'heavy' ? 'heavy' : 'light'); },
});

function openBoostModal({ cards, have, opNote, boostTargets = [] }) {
  return new Promise((resolve) => {
    document.querySelector('.confirm-modal-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'card-modal-overlay confirm-modal-overlay';
    const radiators = (cards || []).filter((c) => c && c.type === 'radiator');
    const sides = {};
    // Default each radiator to the side the player already flipped it to in hand
    // (remembered per card), else its LIGHT deployed side - lighter, the cheapest
    // boost. The player can still flip any side here before confirming; the side
    // locks once boosted.
    for (const c of radiators) sides[c.id] = radBoostSidePref(c.id) || 'light';
    // Live total cost = total mass, with each radiator's mass taken from its
    // currently-selected side (heavy is heavier, so it costs more to boost).
    const baseCost = () => (cards || []).reduce((s, c) =>
      s + boostMassOf(c, c.type === 'radiator' ? sides[c.id] : undefined), 0);
    // A boosted Bernal card establishes its OWN colony, so it can't ride into
    // another Bernal - those boosts stay LEO-only.
    const hasBernalCard = (cards || []).some((c) => c && c.type === 'bernal');
    const targets = hasBernalCard ? [] : (boostTargets || []);
    // Default the destination to the player's anchored Home Bernal when they have
    // one - cards ride up to the Home Bernal by default, not LEO - and fall back
    // to the LEO Stack otherwise. The player can still pick LEO in the modal.
    const homeTarget = targets.find((t) => t.isHome) || null;
    let dest = homeTarget ? homeTarget.id : 'leo';   // 'leo' | 'bernalN'
    const destTarget = () => targets.find((t) => t.id === dest) || null;
    // Destination re-prices the boost: LEO = flat mass; an anchored Bernal =
    // doubled / waived / free (bernalBoostCostClient).
    const totalCost = () => {
      const base = baseCost();
      const t = destTarget();
      return t ? bernalBoostCostClient(base, t.bn, t.card) : base;
    };
    const close = (ok) => {
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      resolve(ok ? { ok: true, radSides: sides, cost: totalCost(), to: dest === 'leo' ? undefined : dest } : { ok: false });
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(false); });
    const onKey = (e) => {
      if (e.key === 'Escape') close(false);
      else if (e.key === 'Enter') { if (totalCost() <= have) close(true); }
    };
    document.addEventListener('keydown', onKey);
    const panel = document.createElement('div');
    panel.className = 'turn-confirm-panel';
    const n = (cards || []).length;
    const sideTherms = (c, which) => {
      const f = (c.faces && c.faces.primary) || c;
      const blk = f[which];
      return (blk && blk.therms != null) ? blk.therms : 0;
    };
    const radRows = radiators.map((c) => {
      const heavy = sides[c.id] === 'heavy';   // start on the remembered side
      return `
      <div class="boost-rad-row" data-id="${esc(c.id)}">
        <span class="boost-rad-name">${esc(c.name)}</span>
        <div class="boost-rad-toggle">
          <button type="button" class="boost-rad-side${heavy ? '' : ' is-active'}" data-side="light">Light · ${sideTherms(c, 'light')}🌡 · ${boostMassOf(c, 'light')} mass</button>
          <button type="button" class="boost-rad-side${heavy ? ' is-active' : ''}" data-side="heavy">Heavy · ${sideTherms(c, 'heavy')}🌡 · ${boostMassOf(c, 'heavy')} mass</button>
        </div>
      </div>`;
    }).join('');
    // Destination picker (M2 only): boost to LEO, or ride straight up to one of
    // your anchored Bernals. An anchored Bernal doubles the boost cost, unless
    // its ability waives the doubling (the GEO Elevator + Lofstrom Loop), in
    // which case it charges the plain total mass like a normal boost. A 1-of-N
    // vertical list of the SAME .boost-rad-side buttons the radiator picker uses,
    // so it reads the same as the rest of the modal.
    const destName = (d) => (d === 'leo' ? 'the LEO Stack' : ((targets.find((t) => t.id === d) || {}).label || 'the LEO Stack'));
    const costNote = () => {
      const t = destTarget();
      if (!t) return 'total mass';
      return totalCost() === baseCost() ? 'total mass' : 'double mass';
    };
    const destRow = targets.length ? `
      <div class="boost-dest">
        <span class="boost-rad-name">Boost to</span>
        <div class="boost-dest-opts">
          <button type="button" class="boost-rad-side${dest === 'leo' ? ' is-active' : ''}" data-dest="leo">🛰 LEO Stack</button>
          ${targets.map((t) => `<button type="button" class="boost-rad-side${dest === t.id ? ' is-active' : ''}" data-dest="${esc(t.id)}">🛰 ${esc(t.label)}</button>`).join('')}
        </div>
      </div>` : '';
    panel.innerHTML = `
      <h3>🛰 Boost${targets.length ? '' : ' to LEO'}</h3>
      <p>Boost <strong>${n}</strong> card${n === 1 ? '' : 's'} from your Hand to <span class="boost-dest-name">the LEO Stack</span>
        for <strong class="boost-cost-val"></strong> Aqua (<span class="boost-cost-note">total mass</span>).
        Bank: <strong>${have}</strong> → <strong class="boost-after-val"></strong>. ${opNote || 'The first boost spends your operation; keep boosting free for the rest of the turn.'}</p>
      ${destRow}
      ${radiators.length ? `<p class="muted boost-rad-help">Pick each radiator's deployed side - it locks once boosted (only radiation damage can flip heavy to light afterward). The heavy side cools more but weighs more, so it costs more Aqua to boost:</p>
      <div class="boost-rad-list">${radRows}</div>` : ''}
      <div class="hud-error boost-cost-warn" hidden></div>
      <div class="turn-confirm-actions">
        <button type="button" class="popup-btn primary" data-act="yes" data-tut-target="boost">🛰 Boost</button>
        <button type="button" class="popup-btn" data-act="no">Cancel</button>
      </div>`;
    const costEl = panel.querySelector('.boost-cost-val');
    const afterEl = panel.querySelector('.boost-after-val');
    const warnEl = panel.querySelector('.boost-cost-warn');
    const destNameEl = panel.querySelector('.boost-dest-name');
    const costNoteEl = panel.querySelector('.boost-cost-note');
    const yesBtn = panel.querySelector('[data-act="yes"]');
    const refreshCost = () => {
      const c = totalCost();
      const afford = c <= have;
      if (costEl) costEl.textContent = String(c);
      if (afterEl) afterEl.textContent = String(have - c);
      if (destNameEl) destNameEl.textContent = destName(dest);
      if (costNoteEl) costNoteEl.textContent = costNote();
      if (yesBtn) {
        yesBtn.textContent = `🛰 Boost (${c} aqua)`;
        yesBtn.disabled = !afford;
      }
      if (warnEl) {
        warnEl.hidden = afford;
        if (!afford) warnEl.textContent = `Not enough Aqua: need ${c}, have ${have}.${radiators.length ? ' Switch a radiator to its light side.' : ''}`;
      }
    };
    // Destination toggle: LEO vs an anchored Bernal (re-prices via totalCost).
    panel.querySelectorAll('.boost-dest .boost-rad-side').forEach((btn) => {
      btn.addEventListener('click', () => {
        dest = btn.dataset.dest;
        panel.querySelectorAll('.boost-dest .boost-rad-side').forEach((b) => b.classList.toggle('is-active', b === btn));
        refreshCost();
      });
    });
    panel.querySelectorAll('.boost-rad-row[data-id]').forEach((row) => {
      const id = row.dataset.id;
      row.querySelectorAll('.boost-rad-side').forEach((btn) => {
        btn.addEventListener('click', () => {
          sides[id] = btn.dataset.side === 'light' ? 'light' : 'heavy';
          row.querySelectorAll('.boost-rad-side').forEach((b) => b.classList.toggle('is-active', b === btn));
          refreshCost();
        });
      });
    });
    yesBtn.addEventListener('click', () => { if (totalCost() <= have) close(true); });
    panel.querySelector('[data-act="no"]').addEventListener('click', () => close(false));
    refreshCost();
    overlay.appendChild(panel);
    mountOverlay(overlay);
  });
}

// Interactive fuel-strip diagram for the rocket-stack header -
// the published HF4 "Net Thrust track". Mass positions 1..32 are
// grouped into the doubling weight-class bands (data/net-thrust-
// track.js is the single source of truth on the band boundaries
// and the per-band fuel-step fraction ladders):
//   WISP +2   mass 1       PROBE +1  mass 2-4
//   SCOUT 0   mass 5-8      TRANSPORT -1 mass 9-16
//   TUG -2    mass 17-32
// Each band shows its fraction ladder (the white sub-step ovals)
// stacked ABOVE its mass-position cells, matching the board's
// layered layout. Two chits overlay the cells: DRY at the
// rocket's dry mass, WET at the current wet mass. Black-line =
// FT spend (burn); red-dotted = refuel - see the legend. The
// strip is read-only for now.
function buildFuelStrip(host, totals = getStackTotals()) {
  host.innerHTML = '';
  // Recolour the strip by fuel grade: grey for dirt, gold for a GW thruster's
  // isotope, blue (default) for water. Mirrors the fuel-tank cylinder's grades.
  host.classList.toggle('is-dirt-fuel', getTankGrade() === 'dirt');
  host.classList.toggle('is-isotope-fuel', getTankGrade() === 'isotope');
  const wm = Math.max(0, totals.wetMass | 0);
  const dm = Math.max(0, totals.dryMass | 0);

  const label = document.createElement('div');
  label.className = 'rocket-fuel-strip-label';
  label.textContent = 'Fuel Strip Track';
  host.appendChild(label);

  // The whole strip is a button into the fuel-tank modal (the tank cylinder,
  // dump / aqua-bank / dirt controls, AND the detailed Net Thrust track all
  // live there). Opening the same modal as the water-tank button keeps a
  // single place to read + move fuel.
  const bands = document.createElement('div');
  bands.className = 'fuel-strip-bands is-clickable';
  bands.title = 'Open the fuel tank';
  bands.addEventListener('click', () => openFuelTankModal());
  // Cap how many mass cells a band lays out per row. Wide bands
  // (TUG spans 16) wrap onto extra rows instead of stretching the
  // strip past its box / off-screen on narrow viewports.
  const MAX_STRIP_COLS = 8;
  for (const wc of WEIGHT_CLASSES) {
    const span = wc.massMax - wc.massMin + 1;
    const cols = Math.min(span, MAX_STRIP_COLS);
    const band = document.createElement('div');
    band.className = 'fuel-strip-band';
    band.dataset.band = wc.id;
    // Width tracks the column count (not the full span) so a wrapped
    // band keeps the same cell size as the others rather than
    // hogging horizontal room for cells it stacks vertically.
    band.style.flexGrow = String(cols);
    band.style.setProperty('--band-color', wc.color);

    const head = document.createElement('div');
    head.className = 'fuel-strip-band-head';
    const mod = wc.netThrust >= 0 ? `+${wc.netThrust}` : String(wc.netThrust);
    head.innerHTML = `<span class="fs-band-name">${wc.id}</span><span class="fs-band-mod">${mod}</span>`;
    band.appendChild(head);

    // Fraction ladder (fuel sub-steps), ordered least -> greatest.
    // Whole-step bands (TUG) show a single "1".
    const fracs = document.createElement('div');
    fracs.className = 'fuel-strip-fracs';
    const ladder = (wc.fractions.length ? wc.fractions.slice() : ['1'])
      .slice()
      .sort((a, b) => fracValue(a) - fracValue(b));
    for (const fr of ladder) {
      const chip = document.createElement('span');
      chip.className = 'fs-frac';
      chip.textContent = fr;
      fracs.appendChild(chip);
    }
    band.appendChild(fracs);

    const cells = document.createElement('div');
    cells.className = 'fuel-strip-cells';
    // minmax(0, 1fr) lets the cells shrink to share the band's width
    // so the strip never overflows its box on narrow viewports.
    cells.style.gridTemplateColumns = `repeat(${cols}, minmax(0, 1fr))`;
    for (let i = wc.massMin; i <= wc.massMax; i++) {
      const cell = document.createElement('div');
      cell.className = 'fuel-strip-cell';
      let tip = `Mass ${i} - ${wc.id} weight class (${mod} net thrust)`;
      if (i === MIN_DRY_MASS) { cell.classList.add('is-min-dry'); tip += ' - MIN DRY MASS'; }
      if (i === MAX_DRY_MASS) { cell.classList.add('is-max-dry'); tip += ' - MAX DRY MASS'; }
      if (i === MAX_WET_MASS) { cell.classList.add('is-max-wet'); tip += ' - MAX WET MASS'; }
      // Dry / wet chit cells report their actual mass value on hover.
      if (i === dm) { cell.classList.add('is-dry-chit'); tip = `Dry mass: ${massLabel(dm)}`; }
      if (i === wm) { cell.classList.add('is-wet-chit'); tip = `Wet mass: ${massLabel(wm)}`; }
      if (i === dm && i === wm) { cell.classList.add('is-co-chit'); tip = `Dry + wet mass: ${massLabel(wm)}`; }
      cell.dataset.tip = tip;
      cell.title = tip;
      cell.textContent = String(i);
      cells.appendChild(cell);
    }
    band.appendChild(cells);
    bands.appendChild(band);
  }
  host.appendChild(bands);

  const wc = weightClassForMass(wm || 1);
  const netMod = wc.netThrust >= 0 ? `+${wc.netThrust}` : String(wc.netThrust);
  const legend = document.createElement('div');
  legend.className = 'rocket-fuel-strip-legend';
  legend.innerHTML = `
    <span><i class="chit-dot is-dry-chit"></i> Dry ${Math.round(dm * 100) / 100}</span>
    <span><i class="chit-dot is-wet-chit"></i> Wet ${Math.round(wm * 100) / 100} (${wc.id} ${netMod})</span>
    <span class="muted">Max wet ${MAX_WET_MASS}</span>
    <span class="fs-detail-hint">💧 click to open tank</span>
  `;
  host.appendChild(legend);
}

// Parse a "k/d" (or "1") fraction string to a number, for sorting.
function fracValue(s) {
  const str = String(s).trim();
  if (str.includes('/')) { const [a, b] = str.split('/').map(Number); return b ? a / b : 0; }
  return Number(str) || 0;
}

// Modal: the full Net Thrust node track (dark), opened by clicking
// the simplified strip. Shows two chits - DRY + WET - at the
// rocket's current masses, with the node connections (black burn /
// red refuel) the fuel logic follows.
function openNetThrustDetailModal() {
  document.querySelector('.ntd-overlay')?.remove();
  const totals = getStackTotals();
  const dm = Math.max(0, totals.dryMass | 0);
  const wm = Math.max(0, totals.wetMass | 0);
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay ntd-overlay';
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });

  const panel = document.createElement('div');
  panel.className = 'ntd-panel';
  panel.innerHTML = `
    <button type="button" class="modal-x" aria-label="Close (Esc)" title="Close (Esc)">×</button>
    <h2 class="ntd-title">Fuel Strip Track</h2>
    <p class="muted ntd-sub">Dry mass <strong>${esc(massLabel(dm))}</strong> · Wet mass <strong>${esc(massLabel(wm))}</strong>. Hover any node or chit for its value.</p>
    <div class="ntd-scroll"></div>
    <div class="ntd-legend">
      <span><i class="ntd-line burn"></i> burn (spend FT → dry mass)</span>
      <span><i class="ntd-line refuel"></i> refuel (load FT → wet mass)</span>
      <span><i class="ntd-chit dry"></i> dry</span>
      <span><i class="ntd-chit wet"></i> wet</span>
    </div>
  `;
  renderDetailTrack(panel.querySelector('.ntd-scroll'), { dryMass: dm, wetMass: wm });
  panel.querySelector('.modal-x').addEventListener('click', close);
  overlay.appendChild(panel);
  mountOverlay(overlay);
}

function openFuelTankModal({ fromWater = null, toWater = null } = {}) {
  document.querySelector('.fuel-tank-overlay')?.remove();
  const tankNow = Number.isFinite(toWater) ? toWater : getTankWater();
  // fromWater default is null (not 0): no-arg opens snap to the
  // current level immediately, no fill animation. Refuel calls
  // still pass fromWater explicitly to play the fill tween.
  const fromW   = Number.isFinite(fromWater) ? fromWater : tankNow;
  // Water is no longer integer: a burn walks the wet chit down fuel steps and
  // can leave a sub-1 remainder. Show the value with up to 2 decimals (no
  // trailing zeros), and call out the remainder - it can't be transferred out
  // (water moves in whole units).
  const fmtWater = (n) => String(Math.round((Number(n) || 0) * 100) / 100);
  const remOf = (n) => { const v = Number(n) || 0; return Math.round((v - Math.floor(v)) * 100) / 100; };
  const totals  = getStackTotals();
  const thrStats = getActiveThrusterStats();
  // Tank visualisation model: the cylinder always represents the
  // full TANK_MAX wet-mass cap (32). Dry mass occupies the bottom
  // of the cylinder as an immutable block; water floats on top
  // of it. The room left over for water = TANK_MAX − dry mass.
  // A separate LIFT marker is drawn at the active thruster's
  // thrust line so the player can see when extra water would
  // push the rocket below liftable mass.
  const TANK_VIS_MAX = getTankMax();
  const dryMass = Math.max(0, Math.min(TANK_VIS_MAX, totals.dryMass || 0));
  const cap = Math.max(0, TANK_VIS_MAX - dryMass);
  const thrust = (thrStats && Number.isFinite(thrStats.thrust)) ? thrStats.thrust : null;
  const liftCap = (thrust != null) ? Math.max(0, thrust - dryMass) : null;

  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay fuel-tank-overlay';

  let animating = false;
  let raf = 0;
  let finalReached = (fromW === tankNow);

  const close = () => {
    if (raf) cancelAnimationFrame(raf);
    // Defensive - drops were appended to a child of the overlay
    // so they vanish with overlay.remove(), but null out the
    // array so a stale rAF can't touch detached nodes.
    activeDrops.length = 0;
    overlay.remove();
    document.removeEventListener('keydown', onKey);
  };
  const onKey = (e) => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);

  // Net Thrust readout: wet mass -> weight class -> net thrust,
  // mirroring the published Net Thrust track (data/net-thrust-
  // track.js). Net thrust = base thrust + weight-class modifier.
  const wmNow = Math.max(0, totals.wetMass | 0);
  const wcNow = weightClassForMass(wmNow || 1);
  const ntMod = wcNow.netThrust >= 0 ? `+${wcNow.netThrust}` : String(wcNow.netThrust);
  const netThrustVal = (thrust != null) ? (thrust + wcNow.netThrust) : null;
  const fracLadder = wcNow.fractions.length ? wcNow.fractions.join(' ') : 'whole steps';

  const panel = document.createElement('div');
  // The active engine drives the fuel grade: a dirt thruster takes dirt, a
  // water thruster takes water, and the two never mix in the tank. The
  // LIQUID colour follows what's actually LOADED (water already aboard stays
  // blue even under a dirt engine); an empty tank styles by the active
  // engine, since that's the grade you'd load next.
  const activeDirt = getActiveFuelGrade() === 'dirt';
  const activeIso = getActiveFuelGrade() === 'isotope';
  const isDirt = (getTankWater() > 0) ? (getTankGrade() === 'dirt') : activeDirt;
  const isIso = (getTankWater() > 0) ? (getTankGrade() === 'isotope') : activeIso;
  // Does the tank PHYSICALLY hold dirt right now? Water controls (dump / pump /
  // aqua fill) stay available unless dirt is actually loaded, because every
  // thruster can burn water: a water thruster burns ONLY water, a dirt thruster
  // burns water OR dirt. So an empty dirt-engine tank can still take on water.
  const tankDirt = getTankWater() > 0 && getTankGrade() === 'dirt';
  // Isotope (M1 GW thruster) is a third grade: it can't mix with water and has
  // no aqua value, so a loaded isotope tank hides the water controls too.
  const tankIso = getTankWater() > 0 && getTankGrade() === 'isotope';
  const tankNonWater = tankDirt || tankIso;
  const fuelWord = isIso ? 'isotope' : (isDirt ? 'dirt' : 'water');
  panel.className = 'fuel-tank-panel' + (isDirt ? ' is-dirt-fuel' : '') + (isIso ? ' is-isotope-fuel' : '');
  panel.innerHTML = `
    <button type="button" class="modal-x" aria-label="Close (Esc)" title="Close (Esc)">×</button>
    <h2 class="fuel-tank-title">${isIso ? '🟡 Isotope tank' : (isDirt ? '🟤 Dirt tank' : '💧 Water tank')}</h2>
    <p class="muted fuel-tank-sub">Tap outside or press Esc to close</p>
    <div class="fuel-tank-body">
    <div class="fuel-tank-col fuel-tank-col-stage">
    <div class="fuel-tank-stage">
      ${fuelTankCylinderMarkup()}
      <div class="fuel-tank-readout">
        <div class="fuel-tank-amount">
          <strong class="tank-now">${fmtWater(fromW)}</strong>
          <span class="tank-sep">/</span>
          <strong class="tank-cap">${cap}</strong>
        </div>
        <em class="muted">${fuelWord}</em>
        <div class="fuel-tank-wet muted">wet mass <strong class="tank-wet">${fmtWater(dryMass + fromW)}</strong></div>
      </div>
    </div>
    </div>
    <div class="fuel-tank-col fuel-tank-col-strip">
      <div class="ntd-title-mini muted">Fuel Strip Track</div>
      <div class="fuel-tank-strip ntd-scroll"></div>
      <div class="ntd-legend">
        <span><i class="ntd-line burn"></i> burn (spend FT → dry mass)</span>
        <span><i class="ntd-line refuel"></i> refuel (load FT → wet mass)</span>
        <span><i class="ntd-chit dry"></i> dry</span>
        <span><i class="ntd-chit wet"></i> wet</span>
      </div>
    </div>
    <div class="fuel-tank-col fuel-tank-col-controls">
    <div class="fuel-tank-actions">
      ${tankNonWater ? '' : `
      <div class="aqua-direction aqua-direction-reverse fuel-tank-dump-row">
        <span class="aqua-direction-label">💧⤓ DUMP</span>
        <div class="aqua-actions">
          <button type="button" class="popup-btn popup-btn-secondary" id="water-dump-1"
            title="Jettison 1 fuel step of water">-1</button>
          <button type="button" class="popup-btn popup-btn-secondary" id="water-dump-5"
            title="Jettison 5 fuel steps of water">-5</button>
          <button type="button" class="popup-btn" id="water-dump-max"
            title="Jettison all water down to dry mass">max</button>
        </div>
      </div>`}
      ${tankIso ? `
      <div class="aqua-direction aqua-direction-reverse fuel-tank-dump-row">
        <span class="aqua-direction-label">🟡⤓ DUMP</span>
        <div class="aqua-actions">
          <button type="button" class="popup-btn popup-btn-secondary" id="iso-dump-1"
            title="Jettison 1 fuel step of isotope">-1</button>
          <button type="button" class="popup-btn popup-btn-secondary" id="iso-dump-5"
            title="Jettison 5 fuel steps of isotope">-5</button>
          <button type="button" class="popup-btn" id="iso-dump-max"
            title="Jettison all isotope down to dry mass. An empty tank frees the rocket to re-form elsewhere.">max</button>
        </div>
      </div>` : ''}
      ${(_online && !isDirt && getTankWater() > 0) ? `
      <div class="aqua-direction aqua-direction-reverse fuel-tank-can-row">
        <span class="aqua-direction-label">📦 CAN → cargo</span>
        <div class="aqua-actions">
          <button type="button" class="popup-btn popup-btn-secondary" id="fuel-can-1"
            title="Package 1 ${isIso ? 'isotope' : 'water'} from the tank into a movable fuel cargo card">1</button>
          <button type="button" class="popup-btn popup-btn-secondary" id="fuel-can-5"
            title="Package 5 ${isIso ? 'isotope' : 'water'} into a fuel cargo card">5</button>
          <button type="button" class="popup-btn" id="fuel-can-max"
            title="Package the whole tank into a fuel cargo card you can carry to another stack">all</button>
        </div>
      </div>` : ''}
    </div>
    ${tankNonWater ? '' : fuelTankOutpostSections()}
${fuelTransferSectionMarkup({
      wrapClass: 'fuel-tank-aqua', wrapId: 'tank-aqua-section', wrapHidden: true,
      icon: '🏦', title: 'Aqua bank', balance: getAqua(), balanceId: 'aqua-balance',
      help: 'At LEO, or at your anchored Home Bernal, you can swap aqua between your bank and the rocket tank, 1:1, for free.',
      rows: [
        { label: '🏦 Bank → 💧 Tank', btns: [
          { id: 'aqua-buy-1', text: '+1', title: 'Move 1 aqua from your bank into the tank' },
          { id: 'aqua-buy-5', text: '+5', title: 'Move 5 aqua from your bank into the tank' },
          { id: 'aqua-buy-max', text: 'Max fill', primary: true, title: 'Fill the tank to its cap from your aqua bank' },
        ] },
        { label: '💧 Tank → 🏦 Bank', reverse: true, btns: [
          { id: 'aqua-cash-1', text: '-1', title: 'Drain 1 water from the tank back into your aqua bank' },
          { id: 'aqua-cash-5', text: '-5', title: 'Drain 5 water from the tank back into your aqua bank' },
          { id: 'aqua-cash-all', text: 'Cash out', primary: true, title: 'Empty the tank back into your aqua bank' },
        ] },
      ],
    })}
    ${fuelTransferSectionMarkup({
      wrapClass: 'fuel-tank-dirt', wrapId: 'tank-dirt-section', wrapHidden: true,
      help: "A dirt thruster scoops grey propellant for free, any amount per turn, at a site with a factory or ISRU platform. Dirt has no aqua value and can't mix with water.",
      helpId: 'dirt-help', helpAfter: true,
      rows: [
        { label: '⛏ Scoop → 🟤 Tank', btns: [
          { id: 'dirt-fill-1', text: '+1', title: 'Scoop 1 dirt FT into the tank' },
          { id: 'dirt-fill-5', text: '+5', title: 'Scoop 5 dirt FTs into the tank' },
          { id: 'dirt-fill-max', text: 'Max fill', primary: true, title: 'Fill the tank to its cap with dirt' },
        ] },
        { label: '🟤 Tank → ⤓ Dump', reverse: true, btns: [
          { id: 'dirt-dump-1', text: '-1', title: 'Jettison 1 dirt fuel step' },
          { id: 'dirt-dump-5', text: '-5', title: 'Jettison 5 dirt fuel steps' },
          { id: 'dirt-dump-all', text: 'Dump all', primary: true, title: 'Jettison all dirt down to dry mass' },
        ] },
      ],
    })}
    <p class="muted fuel-tank-dump-note">
      Dumped ${fuelWord} is destroyed for now. Stage 3+ turns this into
      an outpost-stack drop once factories land.
    </p>
    <div class="fuel-tank-foot muted">
      Tank cap = <strong>${TANK_VIS_MAX}</strong> − dry mass
      <strong>${dryMass}</strong> = <strong>${cap}</strong> water room.
    </div>
    <div class="fuel-tank-netthrust">
      <div class="ntt-head">🚀 Fuel Strip Track</div>
      <div class="ntt-body">
        <div class="ntt-row">
          Wet mass <strong>${wmNow}</strong> → <strong>${wcNow.id}</strong>
          weight class (<strong>${ntMod}</strong> net thrust)
        </div>
        ${thrust != null
          ? `<div class="ntt-row">Base thrust <strong>${thrust}</strong>
               ${ntMod} weight = net thrust <strong>${netThrustVal}</strong></div>`
          : '<div class="ntt-row muted">(no active thruster - no base thrust)</div>'}
        <div class="ntt-row muted">Fuel steps this band: <strong>${fracLadder}</strong></div>
      </div>
      <p class="muted ntt-note">
        Heavier stacks read a lower net thrust. A burn spends fuel
        and walks the wet-mass chit toward dry mass (black line);
        refuelling walks it back up (red dotted). Each band spends
        fuel in finer fractions as mass grows.
      </p>
    </div>
    </div>
    </div>
  `;

  const waterRect = panel.querySelector('.tank-water');
  const foamRect  = panel.querySelector('.tank-water-foam');
  const dryRect   = panel.querySelector('.tank-dry');
  const liftLine  = panel.querySelector('.tank-lift-line');
  const nowReadout = panel.querySelector('.tank-now');
  const wetReadout = panel.querySelector('.tank-wet');
  const ticksG     = panel.querySelector('.tank-ticks');

  // Fuel strip (middle column). This is the SAME detailed Fuel Strip
  // Track as the click-to-open modal (renderDetailTrack), reused
  // as-is. The Net Thrust readout text moves under it so they read
  // as one block. As water moves (dump / pump / refuel / aqua) the
  // track re-renders at the new wet mass, so the WET chit walks the
  // ladder and the blue burn path grows / shrinks in lockstep with
  // the tank cylinder beside it. Re-render is bounded: only when the
  // wet mass crosses an integer or shifts by a fuel-step (~0.1), so
  // a tween redraws a handful of times, not 60x a second.
  const stripCol  = panel.querySelector('.fuel-tank-col-strip');
  const ntBlock   = panel.querySelector('.fuel-tank-netthrust');
  if (stripCol && ntBlock) stripCol.appendChild(ntBlock);
  const stripHost = panel.querySelector('.fuel-tank-strip');
  const nttBody   = ntBlock && ntBlock.querySelector('.ntt-body');
  let lastRenderWet = -999;
  // Net Thrust readout text under the strip, recomputed from the live wet mass
  // (it used to render once at open and go stale as the tank moved).
  function updateNetThrustText(wet) {
    if (!nttBody) return;
    const wm = Math.max(0, wet);
    const wc = weightClassForMass(Math.max(1, wm));
    const mod = wc.netThrust >= 0 ? `+${wc.netThrust}` : String(wc.netThrust);
    const nt = (thrust != null) ? (thrust + wc.netThrust) : null;
    const frac = (wc.fractions && wc.fractions.length) ? wc.fractions.join(' ') : 'whole steps';
    nttBody.innerHTML = `
      <div class="ntt-row">Wet mass <strong>${esc(massLabel(wm))}</strong> → <strong>${esc(wc.id)}</strong> weight class (<strong>${mod}</strong> net thrust)</div>
      ${thrust != null
        ? `<div class="ntt-row">Base thrust <strong>${thrust}</strong> ${mod} weight = net thrust <strong>${nt}</strong></div>`
        : '<div class="ntt-row muted">(no active thruster - no base thrust)</div>'}
      <div class="ntt-row muted">Fuel steps this band: <strong>${frac}</strong></div>`;
  }
  function updateStrip(level) {
    if (!stripHost) return;
    const wet = Math.max(0, dryMass + level);
    updateNetThrustText(wet);
    if (Math.abs(wet - lastRenderWet) < 0.09
        && Math.round(wet) === Math.round(lastRenderWet)) return;
    renderDetailTrack(stripHost, { dryMass, wetMass: wet });
    lastRenderWet = wet;
    // Keep the moving WET chit in view as the wide track scrolls.
    const range = stripHost.scrollWidth - stripHost.clientWidth;
    if (range > 0) {
      const frac = Math.max(0, Math.min(1, wet / MAX_WET_MASS));
      stripHost.scrollLeft = frac * range;
    }
  }
  updateStrip(fromW);

  // Geometry: 200 svg units span TANK_VIS_MAX wet-mass units.
  // The dry-mass block fills the bottom; water sits above it.
  const unitPx = 200 / TANK_VIS_MAX;
  const dryHeightPx = dryMass * unitPx;
  const dryTopY = 210 - dryHeightPx;
  if (dryRect) {
    dryRect.setAttribute('y', String(dryTopY));
    dryRect.setAttribute('height', String(dryHeightPx));
  }
  // Lift-cap marker. Only show when the active thruster is set
  // AND the lift cap is BELOW the visual tank cap (i.e., the
  // rocket would be over-massed before the tank fills).
  if (liftLine) {
    if (thrust != null && liftCap < cap && thrust > 0) {
      const liftY = 210 - (dryMass + liftCap) * unitPx;
      liftLine.setAttribute('y1', String(liftY));
      liftLine.setAttribute('y2', String(liftY));
      liftLine.setAttribute('opacity', '0.85');
    } else {
      liftLine.setAttribute('opacity', '0');
    }
  }

  // Tick marks. One short hatch every 5 units on the right edge,
  // across the full TANK_VIS_MAX scale so the player sees the
  // absolute wet-mass position (matches the Net Thrust track).
  for (let v = 5; v <= TANK_VIS_MAX; v += 5) {
    const ty = 210 - v * unitPx;
    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    line.setAttribute('x1', 100); line.setAttribute('x2', 110);
    line.setAttribute('y1', ty);  line.setAttribute('y2', ty);
    line.setAttribute('stroke', 'rgba(125, 211, 252, 0.55)');
    line.setAttribute('stroke-width', '1.5');
    ticksG.appendChild(line);
  }

  // Current water surface y (svg coord). Drops use this to know
  // when they've hit the surface. setLevel writes it each frame.
  // Water floats on top of the dry block, never inside it.
  let _surfaceY = dryTopY;
  function setLevel(level) {
    const clamped = Math.max(0, Math.min(cap, level));
    const h = clamped * unitPx;
    const waterTopY = dryTopY - h;
    _surfaceY = waterTopY;
    waterRect.setAttribute('y', String(waterTopY));
    waterRect.setAttribute('height', String(h));
    foamRect.setAttribute('y',  String(waterTopY - 3));
    foamRect.setAttribute('height', String(Math.min(6, h)));
    nowReadout.textContent = fmtWater(clamped);
    // Wet mass = dry mass + water. Keep it live under the tank number so the
    // player can read where the WET chit sits on the fuel strip beside it.
    if (wetReadout) wetReadout.textContent = fmtWater(dryMass + clamped);
    // Shrink the font so the number always stays CONTAINED in the fixed-width
    // readout box. The box never resizes, so the font changing never moves the
    // tank; longer (fractional) values just get a smaller font.
    const len = nowReadout.textContent.length;
    nowReadout.style.fontSize = len >= 6 ? '20px' : len >= 5 ? '24px' : len >= 4 ? '30px' : '38px';
    // The fuel strip + Net Thrust text are pinned to the COMMITTED tank via the
    // onRocketChange sync below (not per animation frame), so they always match
    // the real tank instead of lagging a tween or flickering as the cylinder
    // drains.
  }
  // Seed the initial water level (the static HTML only renders the number).
  setLevel(fromW);

  // Falling-droplet animation. Spawns teardrop <path>s at the
  // top of the tank and lets gravity drop them onto the water
  // surface. On impact, a quick splash ring expands + fades.
  // Two cadences:
  //   - fast (~110ms) while a fill / drain tween is running
  //   - ambient (~2-5s, random) while idle, so the modal has a
  //     bit of life without feeling like the tank is filling
  const dropsLayer = panel.querySelector('.tank-drops');
  const SVG_NS = 'http://www.w3.org/2000/svg';
  const activeDrops = [];
  let lastSpawn = 0;
  let nextAmbient = 0;
  function spawnDrop(now, opts = {}) {
    const x = 30 + Math.random() * 60;      // within the tank interior
    const path = document.createElementNS(SVG_NS, 'path');
    // Teardrop shape ~6px tall, 4px wide at base.
    path.setAttribute('d', 'M 0 -3 C 2 0 2 3 0 3 C -2 3 -2 0 0 -3 Z');
    path.setAttribute('fill', '#7dd3fc');
    // Ambient drops are quieter (lower opacity, slower fall) so
    // the eye reads them as background pulse rather than fill.
    path.setAttribute('opacity', opts.ambient ? '0.55' : '0.9');
    path.setAttribute('transform', `translate(${x.toFixed(1)} 14)`);
    dropsLayer.appendChild(path);
    activeDrops.push({
      el: path, x, y: 14,
      vy: opts.ambient ? (20 + Math.random() * 15) : (60 + Math.random() * 30),
      bornAt: now,
    });
  }
  function spawnSplash(x, y) {
    const ring = document.createElementNS(SVG_NS, 'circle');
    ring.setAttribute('cx', String(x.toFixed(1)));
    ring.setAttribute('cy', String(y.toFixed(1)));
    ring.setAttribute('r', '1');
    ring.setAttribute('fill', 'none');
    ring.setAttribute('stroke', '#bae6fd');
    ring.setAttribute('stroke-width', '1.2');
    ring.setAttribute('opacity', '0.85');
    dropsLayer.appendChild(ring);
    const t0 = performance.now();
    const splashTick = (now) => {
      const t = Math.min(1, (now - t0) / 350);
      const r = 1 + t * 6;
      const op = 0.85 * (1 - t);
      ring.setAttribute('r', String(r.toFixed(2)));
      ring.setAttribute('opacity', String(op.toFixed(2)));
      if (t < 1) requestAnimationFrame(splashTick);
      else ring.remove();
    };
    requestAnimationFrame(splashTick);
  }
  function stepDrops(now, dtMs) {
    // Fill / drain mode: spawn rapidly so the column reads as
    // pouring water. Idle: spawn sparingly so the modal has a
    // bit of pulse without looking like the tank is refilling
    // on its own.
    if (animating) {
      if (now - lastSpawn > 110) {
        spawnDrop(now);
        lastSpawn = now;
      }
    } else if (nextAmbient && now >= nextAmbient) {
      spawnDrop(now, { ambient: true });
      nextAmbient = now + 2000 + Math.random() * 3000;
    } else if (!nextAmbient) {
      // First idle frame seeds the schedule so we don't spawn
      // a drop instantly on modal open - players see the still
      // tank first, then a quiet drop after a beat.
      nextAmbient = now + 1500 + Math.random() * 1500;
    }
    for (let i = activeDrops.length - 1; i >= 0; i--) {
      const d = activeDrops[i];
      const dts = dtMs / 1000;
      d.vy += 220 * dts;        // gravity (px/s^2)
      d.y  += d.vy * dts;
      // Landed on the water surface? Spawn splash + remove drop.
      if (d.y >= _surfaceY - 1) {
        spawnSplash(d.x, _surfaceY);
        d.el.remove();
        activeDrops.splice(i, 1);
        continue;
      }
      d.el.setAttribute('transform', `translate(${d.x.toFixed(1)} ${d.y.toFixed(1)})`);
    }
  }
  function clearDrops() {
    for (const d of activeDrops) d.el.remove();
    activeDrops.length = 0;
  }

  // Initial position.
  setLevel(fromW);

  // Skip / close. The first tap during animation jumps to the
  // final state; subsequent taps (or a tap when already final)
  // close the modal. Two-state click is intentional so the
  // player has a moment to read the result before dismissing.
  const onTap = (e) => {
    if (e.target.classList.contains('modal-x')) return;
    if (animating) {
      // Skip animation - snap the level to the active tween's
      // target and tear the tween down. The main rAF stays alive
      // (it's also driving ambient drops), so we only clear the
      // tween state + in-flight drops.
      const target = tween ? tween.to : tankNow;
      tween = null;
      animating = false;
      setLevel(target);
      clearDrops();
      finalReached = true;
      return;
    }
    if (finalReached) close();
  };
  overlay.addEventListener('click', onTap);
  panel.querySelector('.modal-x').addEventListener('click', close);

  overlay.appendChild(panel);
  mountOverlay(overlay);

  // Continuous tick. Runs from open to close so ambient drops
  // can fall while the modal sits idle. Level tweens (initial
  // refuel, drain on dump, aqua → water transfer) share this
  // loop via the `tween` slot below - they set { from, to, t0,
  // dur, onDone } and the step function handles the rest.
  // `animating` keys stepDrops's cadence so a running tween
  // pours drops fast and idle frames pour sparingly.
  let lastTick = performance.now();
  let tween = null;
  if (fromW !== tankNow) {
    tween = {
      from: fromW, to: tankNow,
      t0: performance.now(), dur: 1100,
    };
    animating = true;
  } else {
    finalReached = true;
  }
  const step = (now) => {
    const dt = now - lastTick;
    lastTick = now;
    if (tween) {
      const t = Math.min(1, (now - tween.t0) / tween.dur);
      const eased = 1 - Math.pow(1 - t, 3);  // ease-out cubic
      const v = tween.from + (tween.to - tween.from) * eased;
      setLevel(v);
      if (t >= 1) {
        const done = tween.onDone;
        tween = null;
        animating = false;
        finalReached = true;
        if (done) done();
      }
    }
    stepDrops(now, dt);
    raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
  // Note: close() already nulls activeDrops + removes the
  // overlay, so any in-flight drops vanish when the user
  // dismisses mid-animation.

  // Dump-fuel buttons. Drain water from the tank without forming
  // an outpost stack (that lands once factories ship in Stage
  // 3+). Each click: removeFuel(N), then animate the level
  // dropping from before-value to after-value over ~250ms. The
  // readout updates each frame; in-flight droplets are cleared
  // because dumping should feel like emptying, not filling.
  const waterDump1   = panel.querySelector('#water-dump-1');
  const waterDump5   = panel.querySelector('#water-dump-5');
  const waterDumpMax = panel.querySelector('#water-dump-max');
  const refreshDumpButtons = () => {
    const cur = getTankWater();
    const dry = Math.max(0, getStackTotals().dryMass | 0);
    const steps = blackStepsBetween(dry, dry + cur);
    if (waterDump1)   waterDump1.disabled   = steps < 1;
    if (waterDump5)   waterDump5.disabled   = steps < 5;
    if (waterDumpMax) waterDumpMax.disabled = steps < 1;
  };
  refreshDumpButtons();
  function drainTo(targetLevel, durationMs = 250) {
    // Hand off to the unified tween: the continuous step picks
    // it up next frame and animates setLevel without disturbing
    // ambient drops. Clearing in-flight drops keeps the visual
    // honest - emptying shouldn't look like pouring in.
    clearDrops();
    const fromLevel = parseFloat(nowReadout.textContent || String(getTankWater()));
    const toLevel = Math.max(0, targetLevel);
    if (fromLevel === toLevel) {
      refreshDumpButtons();
      return;
    }
    animating = true;
    tween = {
      from: fromLevel, to: toLevel,
      t0: performance.now(), dur: durationMs,
      onDone: () => refreshDumpButtons(),
    };
  }
  // Dump fuel by FUEL STEP (water OR dirt - same path). -1 walks the wet chit
  // one black connection down the ladder (the same non-linear mass drop a burn
  // spends, so it can be a fraction); max walks all the way to dry mass. Logs
  // the tank before / after so the step amount is visible in the console.
  const round6 = (n) => Math.round((Number(n) || 0) * 1e6) / 1e6;
  async function dumpFuelBySteps(steps, e, onRefresh) {
    // Stop the overlay's onTap handler from reading this click as
    // "skip animation / close".
    e?.stopPropagation();
    const before = getTankWater();
    const dry = Math.max(0, getStackTotals().dryMass | 0);
    const wet = dry + before;
    const maxSteps = blackStepsBetween(dry, wet);
    const k = Math.min(steps, maxSteps);
    const grade = getTankGrade();
    if (k < 1) {
      console.log('[dump] nothing to dump', { grade, tankWater: round6(before), dryMass: dry, wetMass: round6(wet), maxSteps, stepsRequested: steps });
      onRefresh && onRefresh();
      return;
    }
    const drain = Math.max(0, round6(wet - walkBlackDown(wet, k)));
    console.log('[dump] BEFORE', { grade, tankWater: round6(before), dryMass: dry, wetMass: round6(wet), stepsRequested: steps, stepsToDump: k, maxSteps, drainWater: drain });
    if (drain <= 0) { console.log('[dump] drain is 0, aborting'); onRefresh && onRefresh(); return; }
    // Online: jettisoning is the server DUMP op; await it so the snapshot
    // lowers the tank first, then drain-animate to the new level.
    if (_online) {
      const ok = await submitOnlineOp({ kind: 'DUMP', amount: drain });
      const afterOnline = getTankWater();
      console.log('[dump] AFTER (online)', { ok, requestedDrain: drain, tankWater: round6(afterOnline), removed: round6(before - afterOnline) });
      if (!ok) { onRefresh && onRefresh(); return; }
      drainTo(afterOnline, afterOnline <= 0 ? 600 : 250);
      onRefresh && onRefresh();
      return;
    }
    removeFuel(drain);
    const after = getTankWater();
    console.log('[dump] AFTER', { grade, tankWater: round6(after), removed: round6(before - after), wetMassAfter: round6(dry + after) });
    drainTo(after, after <= 0 ? 600 : 250);
    logAction({
      type: 'dump',
      icon: grade === 'dirt' ? '🟤⤓' : '💧⤓',
      summary: after <= 0
        ? `Dumped ${k} ${grade} fuel step${k === 1 ? '' : 's'} (tank empty)`
        : `Dumped ${k} ${grade} fuel step${k === 1 ? '' : 's'} (tank ${massLabel(after)}/${getTankMax()})`,
      undoable: false,
    });
    onRefresh && onRefresh();
  }
  waterDump1?.addEventListener('click',   (e) => dumpFuelBySteps(1, e, refreshDumpButtons));
  waterDump5?.addEventListener('click',   (e) => dumpFuelBySteps(5, e, refreshDumpButtons));
  waterDumpMax?.addEventListener('click', (e) => dumpFuelBySteps(Infinity, e, refreshDumpButtons));
  // Isotope dump (M1 GW-thruster fuel): isofuel can't be transferred to an
  // outpost or cashed, so DUMP is the only way to empty the tank - which is what
  // frees a location-locked rocket to re-form elsewhere. Grade-agnostic handler.
  const isoDump1 = panel.querySelector('#iso-dump-1');
  const isoDump5 = panel.querySelector('#iso-dump-5');
  const isoDumpMax = panel.querySelector('#iso-dump-max');
  isoDump1?.addEventListener('click',   (e) => dumpFuelBySteps(1, e, refreshDumpButtons));
  isoDump5?.addEventListener('click',   (e) => dumpFuelBySteps(5, e, refreshDumpButtons));
  isoDumpMax?.addEventListener('click', (e) => dumpFuelBySteps(Infinity, e, refreshDumpButtons));
  // Can fuel: package tank fuel (water or isofuel) into a movable cargo card in
  // the rocket stack. Whole units only; the server clamps to the tank. After it
  // resolves the modal reopens so the tank level + strip repaint.
  const canFuel = async (amount) => {
    const ok = await submitOnlineOp({ kind: 'CAN_FUEL', ...(amount === Infinity ? {} : { amount }) });
    if (ok) openFuelTankModal({});
  };
  panel.querySelector('#fuel-can-1')?.addEventListener('click', () => canFuel(1));
  panel.querySelector('#fuel-can-5')?.addEventListener('click', () => canFuel(5));
  panel.querySelector('#fuel-can-max')?.addEventListener('click', () => canFuel(Infinity));

  // Aqua → water transfer panel. Gated behind LEO presence -
  // refilling water from the aqua reserve is a "back at port"
  // affordance, not something you can do mid-burn. Tank cap is
  // the lift-limit `cap` already computed above so the buttons
  // can't push past wet=32 or past thrust-mass.
  const aquaSection = panel.querySelector('#tank-aqua-section');
  const aquaBalEl   = panel.querySelector('#aqua-balance');
  const aquaBuy1Btn = panel.querySelector('#aqua-buy-1');
  const aquaBuy5Btn = panel.querySelector('#aqua-buy-5');
  const aquaBuyMaxBtn = panel.querySelector('#aqua-buy-max');
  const aquaCash1Btn  = panel.querySelector('#aqua-cash-1');
  const aquaCash5Btn  = panel.querySelector('#aqua-cash-5');
  const aquaCashAllBtn = panel.querySelector('#aqua-cash-all');
  // Aqua <-> water works at MY HOME BASE and while docked at my own anchored
  // Home Bernal - a home base doubles as a fuel depot (user 2026-07-04). "Home
  // base" is LEO for an Earthling and CORDELIA for a Siren (V9c), which is what
  // the server's rocketAtRefuelDepot has always meant: this read tested the
  // node literally named LEO, so a Siren parked at their own home could not
  // touch the bank at all (user 2026-08-01). Kept in the `atLeo` name so the
  // section-reveal + both handlers below pick it up.
  const _rsForDepot = getRocketSite();
  const _homeForDepot = myHomeBernal();
  const _homeSlug = homeSiteId();
  const atLeo = (_homeSlug
      ? !!(_rsForDepot && String(_rsForDepot.id2) === String(_homeSlug))
      : isLeoSite(_rsForDepot))
    || !!(_homeForDepot && _rsForDepot && String(_rsForDepot.id2) === String(_homeForDepot.siteId));
  // Aqua <-> water is WATER-ONLY: dirt has no aqua value, and water can't be
  // poured onto a dirt tank (the grades can't mix). The bank panel shows
  // whenever the tank ISN'T already holding dirt, so a dirt-engine rocket with
  // an empty tank can still take on water (a dirt thruster burns water too).
  if (atLeo && !tankNonWater && aquaSection) aquaSection.hidden = false;
  const refreshAquaButtons = () => {
    if (!aquaSection || aquaSection.hidden) return;
    const bal = getAqua();
    const cur = getTankWater();
    const room = Math.max(0, cap - cur);
    if (aquaBalEl) aquaBalEl.textContent = String(bal);
    if (aquaBuy1Btn)   aquaBuy1Btn.disabled   = bal < 1 || room < 1;
    if (aquaBuy5Btn)   aquaBuy5Btn.disabled   = bal < 5 || room < 1;
    if (aquaBuyMaxBtn) aquaBuyMaxBtn.disabled = bal < 1 || room < 1;
    // Reverse direction: tank → bank requires water in the tank
    // to drain back. No upper cap on the bank balance, so the
    // only gate is "do we have anything to cash out?".
    if (aquaCash1Btn)   aquaCash1Btn.disabled   = cur < 1;
    if (aquaCash5Btn)   aquaCash5Btn.disabled   = cur < 5;
    if (aquaCashAllBtn) aquaCashAllBtn.disabled = cur < 1;
  };
  refreshAquaButtons();
  // Reuse the same drainTo-style animation in reverse: get the
  // visual "from" off the on-screen readout and tween up to the
  // new tank water level. Wraps the spend + addFuel pair so a
  // failed spend doesn't leave the level mid-animation.
  // Tween the visible tank level from whatever's displayed to the
  // current tank value (fill OR drain - the tween handles both).
  // Shared by the solo + online aqua<->water paths so every transfer
  // animates the same way, including the free server REFUEL /
  // CASH_WATER ops in multiplayer.
  const animateTankLevel = () => {
    const fromLevel = parseFloat(nowReadout.textContent || String(getTankWater()));
    const toLevel = getTankWater();
    if (fromLevel === toLevel) { refreshAquaButtons(); return; }
    animating = true;
    tween = {
      from: fromLevel, to: toLevel,
      t0: performance.now(), dur: 400,
      onDone: () => { refreshAquaButtons(); refreshDumpButtons(); refreshDirtButtons(); },
    };
  };
  const fillFromAqua = async (amount, e) => {
    e?.stopPropagation();
    if (!atLeo) return;
    const cur = getTankWater();
    const room = Math.max(0, cap - cur);
    const want = Math.min(amount, room, getAqua());
    if (want <= 0) { refreshAquaButtons(); return; }
    // Online: aqua->water is the server REFUEL op. AWAIT it so the
    // snapshot re-hydrates the tank first, THEN play the same fill
    // animation from the old displayed level to the new tank value
    // (previously it returned early and the tank just snapped).
    if (_online) {
      const ok = await submitOnlineOp({ kind: 'REFUEL', amount: want });
      if (!ok) { refreshAquaButtons(); return; }
      animateTankLevel();
      return;
    }
    if (!spendAqua(want)) { refreshAquaButtons(); return; }
    setTankGrade('water');   // aqua converts to WATER (never dirt)
    loadFuel(want);   // walk the red line so the wet chit lands on a node
    animateTankLevel();
    logAction({
      type: 'aqua_transfer',
      icon: '💎→💧',
      summary: `Converted ${want} aqua → ${want} water (tank ${getTankWater()}/${cap})`,
      undoable: false,
    });
  };
  aquaBuy1Btn?.addEventListener('click',   (e) => fillFromAqua(1, e));
  aquaBuy5Btn?.addEventListener('click',   (e) => fillFromAqua(5, e));
  aquaBuyMaxBtn?.addEventListener('click', (e) => fillFromAqua(cap, e));
  // Reverse: drain water from the tank back into the aqua
  // bank (1:1). Only available at LEO. Same tween path as
  // dump-fuel, but credits the player's bank instead of
  // destroying the water.
  const cashOutToAqua = async (amount, e) => {
    e?.stopPropagation();
    if (!atLeo) return;
    const cur = getTankWater();
    const want = Math.min(amount, cur);
    if (want <= 0) { refreshAquaButtons(); return; }
    // Online: water->aqua is the server CASH_WATER op. Await it so the
    // snapshot updates the tank, then drain-animate to the new level.
    if (_online) {
      const ok = await submitOnlineOp({ kind: 'CASH_WATER', amount: want });
      if (!ok) { refreshAquaButtons(); return; }
      animateTankLevel();
      return;
    }
    removeFuel(want);
    addAqua(want);
    animateTankLevel();
    logAction({
      type: 'aqua_cashout',
      icon: '💧→🏦',
      summary: `Cashed ${want} water → ${want} aqua (bank ${getAqua()})`,
      undoable: false,
    });
  };
  aquaCash1Btn?.addEventListener('click',   (e) => cashOutToAqua(1, e));
  aquaCash5Btn?.addEventListener('click',   (e) => cashOutToAqua(5, e));
  aquaCashAllBtn?.addEventListener('click', (e) => cashOutToAqua(getTankWater(), e));

  // Outpost <-> tank transfer. Mirrors the aqua-bank widget above (same
  // two-direction layout, same tween) but moves water between a colocated
  // outpost and the rocket tank, 1:1, for free. Whole units only; a sub-1
  // remainder stays in the rocket. Each section refreshes in place.
  const outpostSections = panel.querySelectorAll('.ft-outpost');
  const refreshOutpostSections = () => {
    const room = Math.max(0, cap - getTankWater());
    const tankWhole = Math.floor(getTankWater());
    outpostSections.forEach((sec) => {
      const letter = sec.dataset.letter;
      const op = getOutpost(letter);
      if (!op) { sec.hidden = true; return; }
      const opWater = op.tank | 0;
      const bal = sec.querySelector('.ft-op-bal');
      if (bal) bal.textContent = String(opWater);
      sec.querySelectorAll('.ft-op-btn').forEach((btn) => {
        const dir = btn.dataset.dir;
        const amt = btn.dataset.amt;
        if (dir === 'in') {
          // Outpost -> Tank: need outpost water + tank room.
          const need = amt === 'max' ? 1 : Number(amt);
          btn.disabled = opWater < need || room < 1;
        } else {
          // Tank -> Outpost: need whole water units in the tank.
          const need = amt === 'all' ? 1 : Number(amt);
          btn.disabled = tankWhole < need;
        }
      });
    });
  };
  refreshOutpostSections();
  const pumpOutpostIn = async (letter, amt, e) => {
    e?.stopPropagation();
    const op = getOutpost(letter);
    if (!op) return;
    const room = Math.max(0, cap - getTankWater());
    const max = Math.min(op.tank | 0, room);
    const want = amt === 'max' ? max : Math.min(amt, max);
    if (want <= 0) { refreshOutpostSections(); return; }
    if (_online) {
      const ok = await submitOnlineOp({ kind: 'TRANSFER_FUEL', letter, amount: want });
      if (!ok) { refreshOutpostSections(); return; }
      animateTankLevel();
      refreshOutpostSections();
      return;
    }
    setOutpostTank(letter, (op.tank | 0) - want);
    addFuel(want);
    animateTankLevel();
    refreshOutpostSections();
    logAction({
      type: 'fuel_transfer', icon: '💧',
      summary: `Pumped ${want} water from Outpost ${letter} into the rocket`,
      undoable: false,
    });
  };
  const storeOutpostOut = async (letter, amt, e) => {
    e?.stopPropagation();
    const op = getOutpost(letter);
    if (!op) return;
    const tankWhole = Math.floor(getTankWater());
    const want = amt === 'all' ? tankWhole : Math.min(amt, tankWhole);
    if (want <= 0) { refreshOutpostSections(); return; }
    if (_online) {
      const ok = await submitOnlineOp({ kind: 'TRANSFER_FUEL', letter, amount: want, direction: 'toOutpost' });
      if (!ok) { refreshOutpostSections(); return; }
      animateTankLevel();
      refreshOutpostSections();
      return;
    }
    removeFuel(want);
    setOutpostTank(letter, (op.tank | 0) + want);
    animateTankLevel();
    refreshOutpostSections();
    logAction({
      type: 'fuel_transfer', icon: '💧',
      summary: `Stored ${want} water from the rocket in Outpost ${letter}`,
      undoable: false,
    });
  };
  outpostSections.forEach((sec) => {
    const letter = sec.dataset.letter;
    sec.querySelectorAll('.ft-op-btn').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const dir = btn.dataset.dir;
        const amtRaw = btn.dataset.amt;
        const amt = (amtRaw === 'max' || amtRaw === 'all') ? amtRaw : Number(amtRaw);
        if (dir === 'in') pumpOutpostIn(letter, amt, e);
        else storeOutpostOut(letter, amt, e);
      });
    });
  });

  // Dirt refuel section: shown when the ACTIVE engine is a dirt thruster.
  // Loading dirt is fueling that engine, so it lives here next to the water
  // controls (never the site popup). Dirt scoops free from the ground at a
  // site with an ISRU card aboard, or from LEO; it can't mix with water, and
  // a crew dirt thruster takes only 1 FT per turn. Same fill granularity as
  // the water bank panel (+1 / +5 / Max); no cash-out, since dirt has no
  // aqua value.
  const dirtSection = panel.querySelector('#tank-dirt-section');
  const dirtFill1   = panel.querySelector('#dirt-fill-1');
  const dirtFill5   = panel.querySelector('#dirt-fill-5');
  const dirtFillMax = panel.querySelector('#dirt-fill-max');
  const dirtDump1   = panel.querySelector('#dirt-dump-1');
  const dirtDump5   = panel.querySelector('#dirt-dump-5');
  const dirtDumpAll = panel.querySelector('#dirt-dump-all');
  const dirtHelp    = panel.querySelector('#dirt-help');
  // Dirt needs NO ISRU rig. At LEO it takes the MOON CABLE (a NASRDA crew card
  // aboard - need NOT be the active thruster) to pipe dirt up; at a real site
  // any active dirt thruster scoops from the ground. Keyed off the CARD, not
  // the suspendable Mooncable faction privilege.
  // The CARD must be aboard AND the Mooncable privilege must actually be live:
  // the server checks both (stackHasMoonCable(rocket, state, player)), so a
  // client that only looked at the card offered dirt under Anarchy - or under
  // the M2 privilege lock - and the op came back refused. Off-line (no
  // snapshot) there is no privilege layer, so the card alone stands.
  const _mePriv = (_onlineSnapshot && Array.isArray(_onlineSnapshot.players))
    ? _onlineSnapshot.players.find((p) => p.profileId === mySeatId()) : null;
  const hasMooncable = stackHasMoonCable()
    && (!_mePriv || playerHasPrivilege(_mePriv, 'MOONCABLE'));
  // Scooping dirt at a site needs an ISRU SOURCE colocated: a factory at the
  // site, or an ISRU platform (a card with an ISRU rating) aboard the rocket.
  // At LEO it's the moon cable instead (no ground to scoop).
  const dirtHere = getRocketSite();
  const dirtFactoryHere = !!(dirtHere && getFactory(dirtHere.id));
  const dirtIsruAboard = getDirtCapability().hasIsru;
  const dirtIsruSource = dirtFactoryHere || dirtIsruAboard;
  const canScoopDirt = atLeo ? hasMooncable : (!!dirtHere && dirtIsruSource);
  // Show the scoop panel whenever the tank is in DIRT MODE (dirt loaded, or
  // an empty tank under a dirt engine) so the player always sees the dirt
  // controls, not just when the dirt thruster happens to be the active
  // engine. The fill buttons stay disabled (with a reason) until the dirt
  // thruster IS the active engine - loading dirt fuels the active engine, and
  // a water engine can't burn it. (A missile robonaut like Wakefield e-Beam
  // can be both the active prospector AND the active thruster; it must be the
  // active THRUSTER to scoop.)
  //
  // Show the scoop section whenever a DIRT THRUSTER is active, even if the tank
  // still holds WATER: you may add dirt onto water (it converts the tank to
  // dirt grade, with a warning). Gating on `isDirt` (which is false for a
  // water-holding tank) hid the controls and forced players to dump water
  // first - the exact Pine Point bug.
  if ((isDirt || activeDirt) && dirtSection) dirtSection.hidden = false;
  // A CREW dirt thruster scoops only 1 dirt FT per turn; a card dirt thruster
  // scoops as much as the tank holds, any number of times. Mirror of the
  // server's applyDirtRefuel cap, keyed off the active thruster being a crew
  // card (the engine doing the scooping). The per-turn tally reads the snapshot
  // online and the local turn-stamp solo (dirtTanksLoadedThisTurn).
  const crewDirtBurner = activeDirt && !!CREW_BY_ID[getActiveThrusterId()];
  const dirtAllowance = (room) => {
    if (!crewDirtBurner) return room;
    return Math.max(0, Math.min(room, 1 - dirtTanksLoadedThisTurn()));
  };
  function refreshDirtButtons() {
    if (!dirtSection || dirtSection.hidden) return;
    const cur = getTankWater();
    const room = Math.max(0, cap - cur);
    // Load as much as fits (card dirt thruster) or just the 1-FT-per-turn crew
    // allowance, any number of times this turn while room remains.
    const fillable = dirtAllowance(room);
    const blocked = !activeDirt || !canScoopDirt || fillable < 1;
    if (dirtFill1)   dirtFill1.disabled   = blocked;
    if (dirtFill5)   dirtFill5.disabled   = blocked || fillable < 5;
    if (dirtFillMax) dirtFillMax.disabled = blocked;
    // Dump (jettison) needs no engine: you can always vent loaded dirt, so
    // the only gate is "are there fuel steps to dump?". Dumping walks the
    // fuel ladder (same as a burn / the water dump), so it's gated on the
    // black steps from wet down to dry, not whole tank units.
    const dirtDry = Math.max(0, (getStackTotals().dryMass | 0));
    const dirtSteps = blackStepsBetween(dirtDry, dirtDry + cur);
    if (dirtDump1)   dirtDump1.disabled   = dirtSteps < 1;
    if (dirtDump5)   dirtDump5.disabled   = dirtSteps < 5;
    if (dirtDumpAll) dirtDumpAll.disabled = dirtSteps < 1;
    if (dirtHelp) {
      dirtHelp.textContent = !activeDirt
        ? 'Make your dirt thruster the active engine to scoop dirt (a water engine can\'t burn it).'
        : !canScoopDirt
          ? (atLeo
              ? 'Carry the moon cable (a NASRDA crew card, privilege live) to take on dirt at LEO or your anchored Home Bernal, or park at a site with a factory or ISRU platform.'
              : !dirtHere
                ? 'Park at a site to scoop dirt.'
                : 'Scooping dirt needs an ISRU source here: a factory at this site, or an ISRU platform (an ISRU-rated card) aboard.')
          : room < 1
            ? 'Tank is full.'
            : (crewDirtBurner && dirtTanksLoadedThisTurn() >= 1)
              ? 'A crew dirt thruster scoops only 1 dirt FT per turn - you have already loaded it this turn.'
              : crewDirtBurner
                ? 'A crew dirt thruster scoops just 1 dirt FT per turn. No aqua value; adding dirt converts a water tank to dirt grade, and dirt can\'t be transferred.'
                : 'Scoop as much dirt as the tank holds - it\'s free and unlimited per turn. No aqua value; adding dirt converts a water tank to dirt grade, and dirt can\'t be transferred.';
    }
  }
  refreshDirtButtons();
  const fillDirt = async (amount, e) => {
    e?.stopPropagation();
    if (!activeDirt || !canScoopDirt) return;
    const cur = getTankWater();
    // Adding dirt to a tank that holds WATER converts the whole tank to dirt
    // grade (it "sums up to dirt"): the active dirt thruster still burns it, but
    // a water-only engine no longer can. Warn before converting so a water tank
    // is never silently changed under the player.
    if (cur > 0 && getTankGrade() === 'water') {
      const ok = await confirmModal({
        title: '🟤 Convert tank to dirt?',
        body: `Your tank holds <b>${fmt(cur)}</b> water. Adding dirt converts the whole tank to <b>dirt grade</b> - your dirt thruster still burns it, but a water-only engine no longer can. Continue?`,
        yes: 'Add dirt', no: 'Cancel',
      });
      if (!ok) { refreshDirtButtons(); return; }
    }
    const room = Math.max(0, cap - cur);
    const fillable = dirtAllowance(room);
    if (fillable < 1) { refreshDirtButtons(); return; }
    const want = amount > 0 ? Math.min(amount, fillable) : fillable;
    // Online: the server validates the active dirt thruster + grade + scoop
    // location and fills (and enforces the crew 1-FT-per-turn cap); the
    // snapshot repaints the grey tank and the per-turn tally.
    if (_online) {
      const ok = await submitOnlineOp({ kind: 'DIRT_REFUEL', amount: want });
      if (!ok) { refreshDirtButtons(); return; }
      animateTankLevel();
      return;
    }
    setTankGrade('dirt');
    loadFuel(want);   // dirt burns down the same ladder, so load it up the red line
    if (crewDirtBurner) markDirtRefueledThisTurn();
    animateTankLevel();
    logAction({
      type: 'dirt_refuel', icon: '🟤',
      summary: `Dirt refuel +${want} (tank ${getTankWater()} dirt)`,
      undoable: false,
    });
  };
  dirtFill1?.addEventListener('click',   (e) => fillDirt(1, e));
  dirtFill5?.addEventListener('click',   (e) => fillDirt(5, e));
  dirtFillMax?.addEventListener('click', (e) => fillDirt(Infinity, e));
  // Dump dirt: same inline -1 / -5 / Dump-all UX as the scoop row, routed
  // through the shared fuel-step dump (walks the black ladder down, logs
  // before / after), so dirt vents by fuel step exactly like water.
  dirtDump1?.addEventListener('click',   (e) => dumpFuelBySteps(1, e, refreshDirtButtons));
  dirtDump5?.addEventListener('click',   (e) => dumpFuelBySteps(5, e, refreshDirtButtons));
  dirtDumpAll?.addEventListener('click', (e) => dumpFuelBySteps(Infinity, e, refreshDirtButtons));

  const unsubAqua = onAquaChange(refreshAquaButtons);
  const unsubRocket = onRocketChange(() => {
    refreshAquaButtons(); refreshDirtButtons(); refreshOutpostSections();
    refreshDumpButtons();
    // Keep the fuel strip + Net Thrust text pinned to the live tank. This
    // fires on every tank change INCLUDING an online snapshot hydrate, so the
    // strip never lags behind a dump / refuel the way a tween-only update can.
    updateStrip(getTankWater());
  });
  // Cleanup: detach listeners when the overlay tears down so a
  // closed modal doesn't keep responding to balance changes.
  const origRemove = overlay.remove.bind(overlay);
  overlay.remove = () => {
    unsubAqua();
    unsubRocket();
    origRemove();
  };
}

// Read the prospector's ISRU rating off the active face's
// properties. ISRU is a numeric property (1..N); missing /
// zero means "no water requirement". Returns the integer.
// NOTE: the active prospector's ISRU + name come from
// getActiveProspectorStats() (prosp.isru / prosp.name), which reads the
// INSTALLED face. Don't re-derive them from card.faces.primary: the black
// side is a different tech with a different ISRU rating, and a primary-face
// read mis-gates prospect / refuel for a flipped card (the Flora buggy bug).

// Free-market a single already-chosen Hand card. Same cost + payout
// as the Free Market operation (1 op, +FREE_MARKET_AQUA aqua, card to
// the bottom of its deck), but skips the picker and goes straight to
// Discard one hand card to the bottom of its deck (free action, unlimited per
// turn). Online routes the DISCARD server op so the discard persists and is
// validated server-side; solo mutates locally. Shared by the hand quick-action
// trash icon and the card modal's Discard button so the two behave identically.
// afterFn runs once the discard fires (e.g. to close the card popup).
async function discardHandCard(card, idx, afterFn) {
  if (!card) return;
  const dest = PATENTS_BY_ID[card.id]
    ? `the bottom of the ${card.type || 'patent'} deck`
    : 'out of play';
  const ok = await confirmModal({
    title: '🗑 Discard card',
    body: `Discard <strong>${esc(card.name)}</strong> to ${dest}? Discarding is a free action you can take any number of times this turn.`,
    yes: '🗑 Discard', no: 'Cancel',
  });
  if (!ok) return;
  if (_online) {
    submitOnlineOp({ kind: 'DISCARD', cardId: card.id });
    if (afterFn) afterFn();
    return;
  }
  consumeDiscard();
  removeFromHandAt(idx);
  // Patents return to the bottom of their type's deck; crew just leave.
  if (PATENTS_BY_ID[card.id]) addToBottom(card.id);
  setStatus(`🗑 Discarded <em>${esc(card.name)}</em> to the bottom of the ${esc(card.type || 'crew')} deck.`);
  logAction({
    type: 'discard',
    icon: '🗑',
    summary: `Discarded ${card.name} to the bottom of the ${card.type || 'crew'} deck`,
    undoable: false,
    data: { cardId: card.id, deckType: card.type || null },
  });
  if (afterFn) afterFn();
}

// the irreversible-sale confirm. afterFn runs once the sale commits
// (e.g. to close the card popup).
function freeMarketSellFromHand(card, afterFn) {
  if (!card) return;
  // Freedom (Free Trade Act): online, when the law is usable, offer to pair this
  // card with a second hand card and sell BOTH for 5 aqua (else 1 for 3).
  if (_online && iCanUseLaw('freedom')) {
    openFreeTradeModal(card, afterFn);
    return;
  }
  openSellConfirmModal({
    card,
    aqua: FREE_MARKET_AQUA,
    renderCardFn: renderCard,
    onConfirm: () => {
      // Online: route to the server FREE_MARKET op (was client-only).
      if (_online) {
        submitOnlineOp({ kind: 'FREE_MARKET', cardId: card.id });
        if (afterFn) afterFn();
        return;
      }
      if (!requireOp('Free Market')) return;
      removeFromHand(card.id);
      addToBottom(card.id);
      addAqua(FREE_MARKET_AQUA);
      setStatus(
        `💱 Free Market: <em>${esc(card.name)}</em> nets `
        + `<strong>+${FREE_MARKET_AQUA}</strong> aqua and returns to the `
        + `bottom of the ${esc(card.type || 'patent')} deck.`
      );
      logAction({
        type: 'free_market',
        icon: '💱',
        summary: `Free Market: ${card.name} for +${FREE_MARKET_AQUA} aqua`,
        undoable: false,
        data: { cardId: card.id, aqua: FREE_MARKET_AQUA },
      });
      if (afterFn) afterFn();
    },
  });
}

// Freedom (Free Trade Act): sell the chosen Hand card alone for 3 aqua, or pair
// it with one more Hand card and sell BOTH for 5. Online-only (the law lives on
// the server snapshot). Submits FREE_MARKET with cardId (1) or cardIds (2).
// Homesteading picker (M2, 2A4): the player chooses WHICH Black-Side product
// in LEO to surrender and, when they hold more than one colonist, WHICH
// colonist settles the new Colony. Mirrors the Free Trade picker's shape.
// Rendered-card pick grid (the same .et-cards / .et-card-pick language the
// ET-produce and Sunspot event modals use): one selectable REAL card per
// option instead of a bare name button. entries: { id, card, kind, face,
// sub } - sub is a small caption ribbon (e.g. where a colonist stands).
function cardPickGrid(entries, getSel, onPick) {
  const grid = document.createElement('div');
  grid.className = 'et-cards';
  const syncSel = () => {
    for (const el of grid.querySelectorAll('.et-card-pick')) {
      const on = el.dataset.id === String(getSel() ?? '');
      el.classList.toggle('is-selected', on);
      el.setAttribute('aria-pressed', on ? 'true' : 'false');
    }
  };
  for (const e of entries) {
    const wrap = document.createElement('div');
    wrap.className = 'et-card-wrap';
    const pick = document.createElement('button');
    pick.type = 'button';
    pick.className = 'et-card-pick';
    pick.dataset.id = e.id;
    try {
      pick.appendChild(renderCard(e.card, { type: e.kind || 'patent', face: e.face || 'primary' }));
    } catch { pick.textContent = (e.card && e.card.name) || e.id; }
    if (e.sub) {
      const sub = document.createElement('span');
      sub.className = 'et-pick-sub';
      sub.textContent = e.sub;
      pick.appendChild(sub);
    }
    const tick = document.createElement('span');
    tick.className = 'et-pick-tick';
    tick.textContent = '✓';
    pick.appendChild(tick);
    pick.addEventListener('click', () => { onPick(e.id); syncSel(); });
    wrap.appendChild(pick);
    grid.appendChild(wrap);
  }
  syncSel();
  return grid;
}

// Homesteading can be STARTED from the LEO Stack or the Home Bernal (where the
// surrendered Black-Side product lives), not only from the target Factory's
// popup. Gather what the op needs so a button there enables or greys out with a
// reason. Mirrors the server applyHomestead requirements.
function homesteadEligibility() {
  const me = mySnapshotPlayer();
  if (!_online || !isM2() || !me) return { ok: false, reason: null, factories: [], products: [], colonists: [] };
  const snap = _onlineSnapshot || {};
  const myId = myOwnerId();
  // My Factories with no Colony yet (the settle targets). Resolve each snapshot
  // key to the SERVER site slug (the snapshot may key by the server slug OR a
  // planner id depending on the source); SITES_BY_ID is keyed by the server slug,
  // so a hit means it already is one, otherwise convert via toServerId.
  const factories = [];
  for (const [key, f] of Object.entries(snap.factories || {})) {
    if (!(f && f.ownerId === myId)) continue;
    if (snap.colonies && snap.colonies[key]) continue;   // already colonized
    const serverId = SITES_BY_ID[key] ? key : (toServerId(_onlineMaps, key) || key);
    factories.push({ slug: serverId, label: onlineSiteLabel(serverId) });
  }
  // Black-Side products in the LEO Stack + the Home Bernal (the two surrender
  // hosts the server scans). The black face is PRIMARY for GW thrusters /
  // freighters, secondary for everything else.
  const blackFaceOf = (c) => (c && (c.type === 'gw-thruster' || c.type === 'freighter')) ? 'primary' : 'secondary';
  const products = [];
  const scan = (slots) => {
    for (const s of (slots || [])) {
      if (!s || s.kind === 'crew') continue;
      const c = cardById(s.id);
      if (!c || c.type === 'colonist' || c.type === 'bernal') continue;
      if ((s.face === 'secondary' ? 'secondary' : 'primary') === blackFaceOf(c)) products.push(s);
    }
  };
  scan(me.leo);
  const home = (me.bernals || []).find(isHomeBernalUnit);
  if (home) scan(home.stack);
  const colonists = snapshotColonistSlots(me);
  const hasOp = getOpsRemaining() > 0;
  const ok = factories.length > 0 && products.length > 0 && colonists.length > 0 && hasOp;
  const reason = ok ? null
    : !factories.length ? 'Needs one of your Factories with no Colony yet (industrialize a claim first).'
    : !products.length ? 'Needs a Black-Side product in your LEO Stack or Home Bernal to surrender.'
    : !colonists.length ? 'Needs a colonist of yours in play (anchor a Bernal to exomigrate one).'
    : !hasOp ? 'No operation left this turn.'
    : 'Homesteading is not available right now.';
  return { ok, reason, factories, products, colonists };
}
// Start Homesteading from LEO / the Home Bernal: pick the target Factory (only
// when more than one qualifies), then hand off to the existing product +
// colonist picker.
function openHomesteadFrom() {
  const e = homesteadEligibility();
  if (!e.ok) { if (e.reason) _onlineToast(e.reason, 'error'); return; }
  const go = (slug, label) => openHomesteadPicker({ id: slug, name: label }, e.products, e.colonists);
  if (e.factories.length === 1) { go(e.factories[0].slug, e.factories[0].label); return; }
  const back = document.createElement('div');
  back.className = 'mp-modal-back';
  const modal = document.createElement('div');
  modal.className = 'mp-trade-builder-modal';
  modal.style.maxWidth = '420px';
  const h = document.createElement('div');
  h.className = 'mp-trade-head';
  h.innerHTML = '<h3>\u{1F3E0} Homestead which Factory?</h3>';
  modal.appendChild(h);
  for (const f of e.factories) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'modal-btn';
    b.style.cssText = 'display:block;width:100%;margin:6px 0';
    b.textContent = f.label;
    b.addEventListener('click', () => { back.remove(); go(f.slug, f.label); });
    modal.appendChild(b);
  }
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'modal-btn';
  cancel.textContent = 'Cancel';
  cancel.addEventListener('click', () => back.remove());
  modal.appendChild(cancel);
  back.appendChild(modal);
  back.addEventListener('click', (ev) => { if (ev.target === back) back.remove(); });
  document.body.appendChild(back);
}

function openHomesteadPicker(site, products, colonists) {
  const back = document.createElement('div');
  back.className = 'mp-modal-back';
  const modal = document.createElement('div');
  modal.className = 'mp-trade-builder-modal';
  modal.style.maxWidth = '460px';
  const close = () => back.remove();
  const h = document.createElement('div');
  h.className = 'mp-trade-head';
  h.innerHTML = `<h3>\u{1F3E0} Homestead ${esc(site.name)}</h3>`;
  modal.appendChild(h);
  const note = document.createElement('div');
  note.className = 'mp-trade-colo no-colo';
  note.textContent = 'Surrender a Black-Side product from LEO (it returns to the bottom of its deck), settle a colonist here as the new Colony, and a fresh colonist exomigrates to you. Costs your operation.';
  modal.appendChild(note);
  let productId = products.length === 1 ? products[0].id : null;
  let colonistId = colonists.length === 1 ? colonists[0].slot.id : null;
  const commit = document.createElement('button');
  const sync = () => {
    commit.disabled = !productId || !colonistId || _onlineBusy;
    commit.textContent = (!productId) ? 'Pick a product to surrender'
      : (!colonistId) ? 'Pick the settling colonist'
      : '\u{1F3E0} Homestead';
  };
  // Real card visuals for both picks (the shared rendered-card grid).
  modal.style.maxWidth = '780px';
  const mkGrid = (title, entries, getSel, setSel) => {
    const cap = document.createElement('div');
    cap.className = 'mp-detail-label';
    cap.textContent = title;
    modal.appendChild(cap);
    modal.appendChild(cardPickGrid(entries, getSel, (id) => { setSel(id); sync(); }));
  };
  mkGrid('Surrender which Black-Side product?', products.map((s) => ({
    id: s.id, card: cardById(s.id) || { name: s.id }, face: s.face || 'secondary',
  })), () => productId, (v) => { productId = v; });
  if (colonists.length > 1) {
    mkGrid('Which colonist settles the Colony?', colonists.map((e) => ({
      id: e.slot.id, card: e.card, kind: 'colonist', face: e.slot.face,
      sub: e.where === 'leo' ? 'at LEO' : `at ${e.where}`,
    })), () => colonistId, (v) => { colonistId = v; });
  }
  const btns = document.createElement('div');
  btns.className = 'mp-trade-btns';
  commit.type = 'button';
  commit.className = 'modal-btn primary';
  commit.addEventListener('click', () => {
    if (!productId || !colonistId) return;
    close();
    // Resolve the target to the SERVER site slug the engine's siteById wants.
    // Callers pass either a server slug (the LEO / Home-Bernal flow, keyed off the
    // snapshot's factory map) or a client PLANNER id (the site-popup's map site).
    // SITES_BY_ID is keyed by the server slug, so a hit means it is already one;
    // otherwise convert the planner id via toServerId (the same conversion the
    // Industrialize op uses). Without this a planner id reached the server and was
    // rejected as unknown_site.
    const sid = SITES_BY_ID[site.id] ? site.id : (toServerId(_onlineMaps, site.id) || site.id);
    submitOnlineOp({ kind: 'HOMESTEAD', siteId: sid, productCardId: productId, colonistCardId: colonistId });
  });
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'modal-btn';
  cancel.textContent = 'Cancel';
  cancel.addEventListener('click', close);
  btns.appendChild(commit);
  btns.appendChild(cancel);
  modal.appendChild(btns);
  sync();
  back.appendChild(modal);
  back.addEventListener('click', (e) => { if (e.target === back) close(); });
  document.body.appendChild(back);
}

// V9 solitaire Trade (the D/V moon rule): "If you land a Human on any D or V
// moon in the Uranian System, you may flip any white patent card in the landing
// stack to its Black-side." A free action, repeatable while the stack stays put.
//
// Which cards qualify, at THIS site, mirroring the server's applySirenTradeFlip:
// the landing stack is whichever of my units is standing here (the rocket, the
// freighter, or an outpost - not LEO, not a Bernal), a HUMAN has to have made
// the landing, and the card must be a patent still on its white face. Returns
// one group per colocated stack so the picker can say where each card is.
function sirenTradeGroupsAt(site) {
  const out = [];
  if (!_online || !isSirens()) return out;
  if (!(_onlineSnapshot && _onlineSnapshot.ceoSolo)) return out;
  // The popup's site carries BOTH ids; id2 is the stable server slug the rule
  // list is written in (same read isSirenHomeOrbit uses in the renderer).
  if (!isSirenTradeMoon(site && (site.id2 || site.id))) return out;
  const emancipated = !!(_onlineSnapshot && _onlineSnapshot.robotsEmancipated);
  const stackIds = ['rocket', 'freighter',
    ...Object.keys(getOutposts()).map((letter) => `outpost${letter}`)];
  for (const stackId of stackIds) {
    if (getStackSiteId(stackId) !== site.id) continue;
    const slots = getStackCards(stackId);
    if (!slots.length) continue;
    // A Human aboard, by the same test the colonize flow uses (a Crew card, or
    // a non-Robot colonist - or any colonist once robots are emancipated). Note
    // it returns { crews }, not a bare array.
    if (!(findColonizeOptions(slots, [], emancipated).crews || []).length) continue;
    const cards = [];
    for (const s of slots) {
      if (!s || s.kind === 'crew' || CREW_BY_ID[s.id]) continue;
      const card = PATENTS_BY_ID[s.id];
      if (!card) continue;
      const face = s.face === 'secondary' ? 'secondary' : 'primary';
      if (face === blackSideFaceClient(card)) continue;   // already traded / installed
      cards.push({ id: s.id, card, face });
    }
    if (cards.length) out.push({ stackId, label: stackLabel(stackId).name, cards });
  }
  return out;
}

// The picker for the rule above. Same shell + rendered-card grid the Homestead
// picker uses, so a flip looks like every other "choose a card" moment.
function openSirenTradePicker(site, groups) {
  const back = document.createElement('div');
  back.className = 'mp-modal-back';
  const modal = document.createElement('div');
  modal.className = 'mp-trade-builder-modal';
  modal.style.maxWidth = '780px';
  const close = () => back.remove();
  const h = document.createElement('div');
  h.className = 'mp-trade-head';
  h.innerHTML = `<h3>\u{1F91D} Trade with the Sirens at ${esc(site.name)}</h3>`;
  modal.appendChild(h);
  const note = document.createElement('div');
  note.className = 'mp-trade-colo no-colo';
  note.textContent = 'Your Humans have landed on one of their D or V moons. Flip any white patent in the landing stack to its Black-Side. Free, and you may trade again while the stack stays here.';
  modal.appendChild(note);
  let pick = null;
  const commit = document.createElement('button');
  const sync = () => {
    commit.disabled = !pick || _onlineBusy;
    commit.textContent = pick ? '\u{1F91D} Flip to Black-Side' : 'Pick a white patent';
  };
  for (const g of groups) {
    const cap = document.createElement('div');
    cap.className = 'mp-detail-label';
    cap.textContent = groups.length > 1 ? `In the ${g.label}` : 'Which patent flips?';
    modal.appendChild(cap);
    modal.appendChild(cardPickGrid(
      g.cards.map((c) => ({ id: c.id, card: c.card, face: c.face })),
      () => pick, (v) => { pick = v; sync(); },
    ));
  }
  const btns = document.createElement('div');
  btns.className = 'mp-trade-btns';
  commit.type = 'button';
  commit.className = 'modal-btn primary';
  commit.addEventListener('click', () => {
    if (!pick) return;
    close();
    // The op names only the card - the engine finds which colocated stack it is
    // in, so there is no site id on the wire and no planner/slug conversion.
    submitOnlineOp({ kind: 'SIREN_TRADE_FLIP', cardId: pick });
  });
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'modal-btn';
  cancel.textContent = 'Cancel';
  cancel.addEventListener('click', close);
  btns.appendChild(commit);
  btns.appendChild(cancel);
  modal.appendChild(btns);
  sync();
  back.appendChild(modal);
  back.addEventListener('click', (e) => { if (e.target === back) close(); });
  document.body.appendChild(back);
}

function openFreeTradeModal(firstCard, afterFn) {
  const others = getHandSlots().filter((id) => id !== firstCard.id);
  let second = null;
  // Base Free Trade Act discounts the pair to 5; the solitaire Free Trade Act
  // II lifts the one-card limit at full price (3 each = 6).
  const soloII = !!(_onlineSnapshot && _onlineSnapshot.ceoSolo);
  const pairGain = soloII ? 6 : 5;
  const back = document.createElement('div');
  back.className = 'mp-modal-back';
  const modal = document.createElement('div');
  modal.className = 'mp-trade-builder-modal';
  modal.style.maxWidth = '460px';
  const close = () => back.remove();
  const h = document.createElement('div');
  h.className = 'mp-trade-head';
  h.innerHTML = `<h3>💱 Free Market - Free Trade Act${soloII ? ' II' : ''}</h3>`;
  modal.appendChild(h);
  const note = document.createElement('div');
  note.className = 'mp-trade-colo no-colo';
  note.innerHTML = `Sell <strong>${esc(firstCard.name)}</strong> alone for <strong>+3</strong> aqua, `
    + `or add a second Hand card and sell both for <strong>+${pairGain}</strong>.`;
  modal.appendChild(note);
  modal.style.maxWidth = '780px';
  const sellTwo = document.createElement('button');
  // The card on the block, rendered for real (fixed - it is already the sale).
  const firstWrap = document.createElement('div');
  firstWrap.className = 'et-cards';
  const firstPick = document.createElement('div');
  firstPick.className = 'et-card-pick is-selected';
  try { firstPick.appendChild(renderCard(firstCard, { type: 'patent' })); }
  catch { firstPick.textContent = firstCard.name || firstCard.id; }
  const firstSub = document.createElement('span');
  firstSub.className = 'et-pick-sub';
  firstSub.textContent = 'selling';
  firstPick.appendChild(firstSub);
  firstWrap.appendChild(firstPick);
  modal.appendChild(firstWrap);
  // Candidate second cards as a rendered-card grid.
  if (others.length) {
    const cap = document.createElement('div');
    cap.className = 'mp-detail-label';
    cap.textContent = 'Add a second card?';
    modal.appendChild(cap);
    const grid = cardPickGrid(
      others.map((id) => ({ id, card: PATENTS_BY_ID[id] || { name: id } })),
      () => second,
      (id) => {
        second = (second === id) ? null : id;
        sellTwo.disabled = !second || _onlineBusy;
        sellTwo.textContent = second ? `Sell 2 for +${pairGain}` : 'Pick a 2nd card';
      },
    );
    modal.appendChild(grid);
  }
  const btns = document.createElement('div');
  btns.className = 'mp-trade-btns';
  const sellOne = document.createElement('button');
  sellOne.type = 'button'; sellOne.className = 'modal-btn';
  sellOne.textContent = 'Sell 1 for +3';
  sellOne.disabled = _onlineBusy;
  sellOne.addEventListener('click', () => {
    close();
    submitOnlineOp({ kind: 'FREE_MARKET', cardId: firstCard.id });
    if (afterFn) afterFn();
  });
  sellTwo.type = 'button'; sellTwo.className = 'modal-btn primary';
  sellTwo.textContent = 'Pick a 2nd card';
  sellTwo.disabled = true;
  sellTwo.addEventListener('click', () => {
    if (!second) return;
    close();
    submitOnlineOp({ kind: 'FREE_MARKET', cardIds: [firstCard.id, second] });
    if (afterFn) afterFn();
  });
  const cancel = document.createElement('button');
  cancel.type = 'button'; cancel.className = 'modal-btn'; cancel.textContent = 'Cancel';
  cancel.addEventListener('click', close);
  btns.appendChild(sellOne);
  if (others.length) btns.appendChild(sellTwo);
  btns.appendChild(cancel);
  modal.appendChild(btns);
  back.appendChild(modal);
  back.addEventListener('click', (ev) => { if (ev.target === back) close(); });
  document.body.appendChild(back);
}

