function doProspect(site, prosp) {
  if (!prosp) return;
  // Online: the server rolls the prospect die and resolves the disc.
  // Send PROSPECT for the target site and let the snapshot repaint;
  // skip the local roll modal + disc placement below.
  if (_online) {
    const siteId = toServerId(_onlineMaps, site.id);
    if (!siteId) { _onlineToast('That site is not on the map.', 'error'); return; }
    // Stamp the turn the scan was fired on so a relayed / re-fired raygun
    // request for the same site this turn resolves as the same valid scan
    // instead of bouncing. The raygun scan is a free action (no operation).
    const snap = _onlineSnapshot || {};
    // Which of the player's stacks is doing the prospecting (the rocket, or a
    // freighter / bernal / outpost carrying a valid prospector). The rocket
    // falls back to its persisted active prospector on the server; every other
    // stack names its prospector card explicitly.
    const unit = {};
    if (prosp.stackId && prosp.stackId !== 'rocket') unit.stackId = prosp.stackId;
    if (prosp.id) unit.prospectorId = prosp.id;
    // Claim disc supply: at the cap (9 placed), the player must MOVE an existing
    // disc to this new spot. Prompt for which one, then send it as relocateFrom.
    const myId = mySeatId();
    if (ownedClaimCount(snap.discs, myId) >= CLAIM_DISCS) {
      const mine = Object.keys(snap.discs || {})
        .filter((k) => snap.discs[k] && snap.discs[k].ownerId === myId
          && snap.discs[k].outcome === 'success')   // only active claims occupy a disc
        .map((k) => ({ siteId: k, disc: snap.discs[k] }))
        // A disc with a factory built on it is locked - it can't be moved.
        .filter((e) => e.siteId !== siteId && !(snap.factories && snap.factories[e.siteId]));
      if (!mine.length) {
        _onlineToast('All 9 claim discs are placed, and every movable one has a factory on it.', 'error');
        return;
      }
      openClaimRelocatePicker(mine, (fromSiteId) => {
        submitOnlineOp({ kind: 'PROSPECT', siteId, turn: snap.turn, round: snap.round, relocateFrom: fromSiteId, ...unit });
      });
      return;
    }
    submitOnlineOp({ kind: 'PROSPECT', siteId, turn: snap.turn, round: snap.round, ...unit });
    return;
  }
  // Already-prospected sites are off-limits in the sandbox; the UI
  // grays out the button when a disc is in place, but guard here
  // too so an autoclick can't double-spend.
  if (getDisc(site.id)) {
    setStatus(`This site already has a prospect disc - clear it first.`);
    return;
  }
  // ISRU rule re-validated against hydration (the "water" gate).
  // Defence-in-depth in case the popup button somehow ends up
  // enabled with a stale read. Includes the colocated ISRU modifier.
  const isAerostatSiteHere = siteIsAerostat(site);
  const prospIsru = Math.max(0, prosp.isru + colocatedIsruMod({ isAerostat: isAerostatSiteHere }));
  const rSite = getRocketSite();
  const colocScoopHere = isAerostatSiteHere && rSite && rSite.id === site.id && stackHasPower('aerostatHydration2');
  const baseWaterHere = Number.isFinite(site.hydration) ? site.hydration : 0;
  const siteWater = colocScoopHere ? Math.max(baseWaterHere, 2) : baseWaterHere;
  if (prospIsru > siteWater) {
    setStatus(
      `Prospect blocked: <em>${esc(prosp.name || '')}</em> needs site water ≥ `
      + `${prospIsru}, site has ${siteWater}.`
    );
    return;
  }
  // Prospect IS the turn's operation for EVERY prospector kind. The raygun
  // only extends the reach to a line-of-sight site; it still spends the op
  // (it is not a free scan). Missile / buggy land on the target. Rulebook I6.
  if (!requireOp('Prospect')) return;
  const threshold = siteProspectThreshold(site);
  const roll = 1 + Math.floor(Math.random() * 6);
  const success = roll <= threshold;
  const cardName = prosp.card?.name || prosp.id;
  const kindGlyph = { missile: '🚀', raygun: '🔫', buggy: '🛺' }[prosp.kind] || '🔬';
  // The buggy can re-roll the prospect die once (optional).
  const canReroll = prosp.kind === 'buggy';
  openProspectRollModal({ site, threshold, roll, success, kindGlyph, cardName, canReroll }, (finalRoll, finalSuccess) => {
    placeDisc(site.id, finalSuccess ? 'success' : 'fail', {
      roll: finalRoll, threshold, kind: prosp.kind, by: cardName,
    });
    setStatus(
      `${kindGlyph} Prospected <strong>${esc(site.name)}</strong> `
      + `(target ≤ ${threshold}) with <em>${esc(cardName)}</em>: `
      + `rolled <strong class="big">${finalRoll}</strong> - `
      + `<strong>${finalSuccess ? 'success - claim placed' : 'failed - site exhausted'}</strong>.`
    );
    logAction({
      type: 'prospect',
      icon: kindGlyph,
      summary: `${finalSuccess ? 'Claimed' : 'Exhausted'} ${site.name} (${prosp.kind}, rolled ${finalRoll} vs ≤${threshold})`,
      undoable: false,
      data: { siteId: site.id, kind: prosp.kind, roll: finalRoll, threshold, success: finalSuccess },
    });
  });
}

// Animated prospect-roll modal. Shows a 3D die on the left, the
// site's prospect target (≤ N) on the right, rolls the die for
// ~700 ms, then settles on the rolled value. The die's outer
// border tints green on success / red on fail so the player reads
// the outcome at a glance. Player then clicks "Place disc" to
// commit the result; onPlace fires once the disc lands.
function openProspectRollModal({ site, threshold, roll, success, kindGlyph, cardName, canReroll = false }, onPlace) {
  document.querySelector('.prospect-roll-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay prospect-roll-overlay';
  // Live result the Place button commits. The buggy reroll mutates
  // these in place, so onPlace always receives the FINAL roll.
  let curRoll = roll;
  let curSuccess = success;
  let rerollUsed = false;
  const close = (placed) => {
    overlay.remove();
    document.removeEventListener('keydown', onKey);
    if (placed && onPlace) onPlace(curRoll, curSuccess);
  };
  // Roll animation isn't dismissible by clicking outside / Esc -
  // the player has to acknowledge the result with the Place button.
  const onKey = (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      const btn = overlay.querySelector('.prospect-place-btn');
      if (btn && !btn.disabled) { e.preventDefault(); close(true); }
    }
  };
  document.addEventListener('keydown', onKey);

  const panel = document.createElement('div');
  panel.className = 'prospect-roll-panel';
  panel.innerHTML = `
    <h2 class="prospect-roll-title">${kindGlyph} Prospecting ${esc(site.name)}</h2>
    <p class="muted prospect-roll-sub">with <em>${esc(cardName)}</em></p>
    <div class="prospect-roll-stage">
      <div class="prospect-die-host"></div>
      <div class="prospect-roll-vs">≤</div>
      <div class="prospect-target">
        <strong>${threshold}</strong>
        <em>site size</em>
      </div>
    </div>
    <p class="prospect-roll-result muted">Rolling…</p>
    <div class="prospect-roll-actions">
      ${canReroll ? `<button type="button" class="popup-btn prospect-reroll-btn" disabled>🎲 Reroll (buggy)</button>` : ''}
      <button type="button" class="popup-btn primary prospect-place-btn" disabled>
        Place disc
      </button>
    </div>
  `;
  const dieHost = panel.querySelector('.prospect-die-host');
  const resultLine = panel.querySelector('.prospect-roll-result');
  const placeBtn = panel.querySelector('.prospect-place-btn');
  const rerollBtn = panel.querySelector('.prospect-reroll-btn');
  const die = buildDie(1);
  dieHost.appendChild(die);

  overlay.appendChild(panel);
  mountOverlay(overlay);

  // Settle the UI on a finished roll: tint the die, show the verdict,
  // and re-enable the action buttons.
  const showResult = (r, ok) => {
    die.classList.remove('die-success', 'die-fail');
    die.classList.add(ok ? 'die-success' : 'die-fail');
    resultLine.innerHTML = ok
      ? `Rolled <strong>${r}</strong> ≤ ${threshold} - <strong class="ok">success</strong>. Claim disc ready.`
      : `Rolled <strong>${r}</strong> > ${threshold} - <strong class="bad">failed</strong>. Site exhausted.`;
    resultLine.classList.remove('muted');
    placeBtn.disabled = false;
    placeBtn.textContent = ok ? 'Place yellow claim disc' : 'Place red disc';
    if (rerollBtn && !rerollUsed) rerollBtn.disabled = false;
  };
  // Animate a roll to `r`, locking the buttons until it settles.
  const animateRoll = (r, ok) => {
    placeBtn.disabled = true;
    if (rerollBtn) rerollBtn.disabled = true;
    die.classList.remove('die-success', 'die-fail');
    resultLine.textContent = 'Rolling…';
    resultLine.classList.add('muted');
    rollDie(die, r).then(() => showResult(r, ok));
  };

  animateRoll(curRoll, curSuccess);

  if (rerollBtn) {
    rerollBtn.addEventListener('click', () => {
      if (rerollUsed) return;
      rerollUsed = true;
      curRoll = 1 + Math.floor(Math.random() * 6);
      curSuccess = curRoll <= threshold;
      animateRoll(curRoll, curSuccess);
      // One reroll only - retire the button once spent.
      rerollBtn.style.display = 'none';
    });
  }
  placeBtn.addEventListener('click', () => close(true));
}

function getRocketSite() {
  if (!_activeData) return null;
  if (_rocketSiteId) {
    const s = _activeData.sites.find((x) => x.id === _rocketSiteId);
    if (s) return s;
    _rocketSiteId = null;
    persistRocketSite();
  }
  return _activeData.sites.find(
    (x) => x.type === 'lagrange' && x.name === 'LEO'
  ) || null;
}
function persistRocketSite() {
  if (isOnline()) return; // online state is server-owned; don't touch the solo save
  try {
    if (_rocketSiteId) localStorage.setItem(STORAGE_ROCKET_SITE, _rocketSiteId);
    else localStorage.removeItem(STORAGE_ROCKET_SITE);
  } catch { /* private mode */ }
}
function persistRocketTrail() {
  if (isOnline()) return; // online state is server-owned; don't touch the solo save
  try {
    if (_rocketTrail && _rocketTrail.length) {
      localStorage.setItem(STORAGE_ROCKET_TRAIL, JSON.stringify(_rocketTrail));
    } else {
      localStorage.removeItem(STORAGE_ROCKET_TRAIL);
    }
  } catch { /* private mode */ }
}
// Move-progress helpers. The full resumable queue context (ctx) is
// persisted as each roll / choice commits, so a tab close mid-
// resolution can pick up where it left off on the next load (per-roll
// resume). Committed rolls aren't re-rolled.
function persistMoveProgress(ctx) {
  try { localStorage.setItem(STORAGE_PENDING_MOVE, JSON.stringify(ctx)); }
  catch { /* private mode */ }
}
function clearMoveProgress() {
  try { localStorage.removeItem(STORAGE_PENDING_MOVE); }
  catch { /* private mode */ }
}
function loadMoveProgress() {
  try {
    const s = localStorage.getItem(STORAGE_PENDING_MOVE);
    return s ? JSON.parse(s) : null;
  } catch { return null; }
}
// True when a saved move ctx still resolves against the active data
// set (so we can safely re-enter the queue). If not, the move is
// rolled back instead.
function canResumeMove(ctx) {
  if (!ctx || !_activeData || !Array.isArray(ctx.turn1) || !ctx.turn1.length) return false;
  const has = (id) => !!(_activeData.byId ? _activeData.byId[id]
    : _activeData.sites.find((x) => x.id === id));
  return ctx.turn1.every((s) => has(s.from) && has(s.to)) && has(ctx.newSiteId);
}
// Roll a move that can't be resumed (data changed, etc.) back to its
// pre-move state so the turn isn't wasted: rocket returns to origin,
// route + trail restored, move budget + fuel refunded, hazard lock
// cleared. Mutates only module state + persistence.
function rollbackMove(ctx) {
  clearMoveProgress();
  if (!ctx) return;
  _rocketSiteId = ctx.fromSiteId || null;
  persistRocketSite();
  _rocketTrail = Array.isArray(ctx.trail) ? ctx.trail : [];
  persistRocketTrail();
  _plannedRoute = Array.isArray(ctx.route) && ctx.route.length ? ctx.route : null;
  _plannedRouteUnit = 'rocket';   // rollback restores the rocket's own route
  persistPlannedRoute();
  if (Number(ctx.fuelCost) > 0) addFuel(Number(ctx.fuelCost));
  refundMove();
  setHazardousMove(false);
  setStatus(
    '⚠ Your last move could not be resumed and was rolled back. The '
    + 'move budget and fuel were refunded - replay the move when ready.'
  );
}
// Planned route persistence. Called from every assignment to
// _plannedRoute so the multi-turn plan survives reloads - critical
// because the player might queue a 4-turn journey, end one turn,
// close the tab, come back tomorrow and expect to continue.
function persistPlannedRoute() {
  // Whenever the plotted route changes, refresh the toolbar's "Move this route"
  // commit button (central hook: every route mutation persists).
  syncRouteCommitBtn();
  // A Mobile Factory plot lives in the in-memory fleet map (turn-local), keyed by
  // the factory's server siteId, so plotting one never clobbers another.
  if (_plannedRouteUnit === 'factory') {
    if (_plannedFactoryId) {
      if (_plannedRoute && _plannedRoute.length) _factoryRoutes[_plannedFactoryId] = _plannedRoute.slice();
      else delete _factoryRoutes[_plannedFactoryId];
    }
    return;
  }
  try {
    const key = routeStorageKey(_plannedRouteUnit);
    if (_plannedRoute && _plannedRoute.length) {
      localStorage.setItem(key, JSON.stringify(_plannedRoute));
    } else {
      localStorage.removeItem(key);
    }
  } catch { /* private mode */ }
}

// Tween the sandbox rocket sprite along a polyline derived from a
// list of segments. Each frame writes a new (x, y) to the renderer
// via setSandboxRocket. Resolves when the tween finishes; rejects
// silently if another animation pre-empts this one. Distance-
// weighted so longer segments take proportionally more time.
// skippable=true (a real MOVE) paces at a constant 0.5s per node and shows the
// on-screen Skip button. Plot previews pass false to keep their own snappy
// totalMs and no Skip chrome.
function animateRocketAlong(segments, totalMs = 700, skippable = true) {
  // A manual route already walked hop-by-hop during plotting snaps on commit
  // (the player has already seen the ship travel) instead of re-flying it.
  if (_fastMoveAnim) totalMs = 0;
  // Burn-path consume (a real online MOVE): the lit route stays drawn and is
  // eaten segment-by-segment as the ship passes each node, then settles to the
  // future-turn tail. Picked up synchronously here (and the module var nulled)
  // so moveRocket's fallback knows the glide now owns the route settle.
  const consume = (skippable && _moveRouteConsume) ? _moveRouteConsume : null;
  if (consume) _moveRouteConsume = null;
  const tailSegs = consume ? (consume.tail || []) : null;
  const thisTurnSegs = consume ? (consume.thisTurn || []) : null;
  const settleRoute = (segs) => {
    if (_renderer && typeof _renderer.setRoute === 'function') {
      _renderer.setRoute(segs && segs.length ? segs : null);
    }
  };
  const settleTail = () => { if (consume) settleRoute(tailSegs); };
  // NOTE: rocket movement stays animated EVEN in battery-saver mode - a
  // smoothly sliding ship is load-bearing for reading the board (user
  // decision). Battery saver still stops the ambient drift loop + CSS motion;
  // this one tween is exempt. It self-schedules its own frames
  // (setSandboxRocket -> _scheduleDraw), so it animates fine with the ambient
  // loop off.
  return new Promise((resolve) => {
    if (!_renderer || !_activeData || !segments || !segments.length) {
      settleTail(); resolve(); return;
    }
    // Build the polyline: start at segments[0].from, then walk
    // through each .to in order. Skip any segments whose endpoints
    // we can't resolve (data drift safety).
    const pts = [];
    const first = _activeData.sites.find((s) => s.id === segments[0].from);
    if (first && typeof first.x === 'number') {
      pts.push({ x: first.x, y: first.y });
    }
    for (const seg of segments) {
      const s = _activeData.sites.find((x) => x.id === seg.to);
      if (s && typeof s.x === 'number') pts.push({ x: s.x, y: s.y });
    }
    if (pts.length < 2) { settleTail(); resolve(); return; }
    const numHopsForConsume = pts.length - 1;
    // The route-consume only lines up when the glide's hop count matches the
    // plan's this-turn segments 1:1 (so dropping the first H of them tracks the
    // ship). Otherwise skip the per-hop shrink: the full route stays lit, then
    // settles to the tail at the end. We eat the ORIGINAL planned segments (they
    // carry turn / burns / dv) so the highlight + labels look unchanged - the
    // echoed glide path has none of those (it would draw all-bright + "undefined").
    const canConsume = !!consume && Array.isArray(thisTurnSegs)
      && thisTurnSegs.length === numHopsForConsume;
    // The lit route with `hop` hops already behind = the un-flown THIS-turn
    // segments from `hop` onward, plus the future-turn tail.
    const litFromHop = (hop) => thisTurnSegs.slice(hop).concat(tailSegs || []);
    const lens = [];
    let totalLen = 0;
    for (let i = 1; i < pts.length; i++) {
      const L = Math.hypot(pts[i].x - pts[i-1].x, pts[i].y - pts[i-1].y);
      lens.push(L);
      totalLen += L;
    }
    if (totalLen === 0) { settleTail(); resolve(); return; }
    const r = isRocketActive();
    const gw = isGwThrusterId(getActiveThrusterId());   // gold stripes hold across the move
    // Instant snap (a manual route already walked during plotting): drop the
    // sprite on the final point and resolve, no per-frame tween.
    if (totalMs <= 0) {
      const last = pts[pts.length - 1];
      _renderer.setSandboxRocket({ x: last.x, y: last.y, colour: myRocketColour(), canFly: r.active, gw });
      settleTail(); resolve(); return;
    }
    // A real MOVE paces at a constant 0.5s per node hop (not distance-weighted),
    // so a long route reads as a steady node-by-node glide; each hop is linear so
    // the ship tracks the plotted polyline exactly. A plot preview keeps its own
    // snappy totalMs.
    const numHops = pts.length - 1;
    if (skippable) totalMs = moveAnimMs(pts.length);
    const t0 = performance.now();
    _rocketAnimating = true;
    if (skippable) beginMoveAnim();
    let litHop = -1;   // last hop the lit route was set for (repaint only on change)
    const paint = (p) => _renderer.setSandboxRocket({ x: p.x, y: p.y, colour: myRocketColour(), canFly: r.active, gw });
    const finish = () => { _rocketAnimating = false; if (skippable) endMoveAnim(); settleTail(); resolve(); };
    const step = (now) => {
      if (skippable && _skipMoveAnim) { paint(pts[pts.length - 1]); finish(); return; }
      // Clamp to [0,1]: the very first rAF timestamp can be a hair before t0,
      // which would make hop -1 and index pts[-1] (undefined) -> crash.
      const t = Math.max(0, Math.min(1, (now - t0) / totalMs));
      const hopF = t * numHops;
      const hop = Math.max(0, Math.min(numHops - 1, Math.floor(hopF)));
      const frac = hopF - hop;
      // Eat the burn path behind the ship: drop the segments already flown.
      if (canConsume && hop !== litHop) { litHop = hop; settleRoute(litFromHop(hop)); }
      paint({
        x: pts[hop].x + (pts[hop + 1].x - pts[hop].x) * frac,
        y: pts[hop].y + (pts[hop + 1].y - pts[hop].y) * frac,
      });
      if (t < 1) requestAnimationFrame(step);
      else finish();
    };
    requestAnimationFrame(step);
  });
}

// BOOST commit button next to the hand title. Lit when at
// least one card is marked. Per the variant cargo flow (user,
// 2026-05-24): Boost moves cards Hand -> LEO Stack (not
// directly onto the rocket), so the button is rocket-location-
// independent - it just needs marked cards. The separate
// Transfer free action (LEO popup) moves cards LEO -> Rocket
// when the rocket is parked at LEO.
function repaintBoostCommit() {
  const btn = document.getElementById('hand-boost-commit');
  if (!btn) return;
  const marked = getBoostMarked();
  const n = marked.length;
  // Boost costs Aqua = the total mass of the marked cards (see
  // commitBoost). Show the cost on the button, not the card count, so the
  // player sees the spend before committing.
  let cost = 0;
  for (const id of marked) {
    const c = PATENTS_BY_ID[id];
    if (!c) continue;
    const f = (c.faces && c.faces.primary) || c;
    cost += ((f.mass != null ? f.mass : c.mass) | 0);
  }
  btn.dataset.armed = n > 0 ? '1' : '0';
  btn.disabled = n === 0;
  const home = homeLabel();
  btn.textContent = n > 0 ? `🛰 BOOST → ${home} 💧${cost}` : `🛰 BOOST → ${home}`;
  btn.title = n > 0
    ? `Boost ${n} marked card${n === 1 ? '' : 's'} from your hand into the ${home} Stack for ${cost} aqua (total mass). The first boost each turn costs one operation; keep boosting free afterward. Use the Transfer action at ${home} to move them onto the rocket.`
    : `Mark cards in your hand, then press BOOST to ship them up to your ${home} Stack.`;
}

// Dry mass of cards currently on the active rocket stack.
// Used to compute the rocket's water-tank cap (TANK_MAX - dry)
// when cards transfer onto the rocket (more cards = less room
// for water). LEO has no tank, so there's no LEO equivalent.
function rocketStackDryMass() {
  let mass = 0;
  for (const slot of getRocketStack()) {
    const c = PATENTS_BY_ID[slot.id];
    if (!c) continue;
    const f = (c.faces && c.faces.primary) || c;
    mass += ((f.mass != null ? f.mass : c.mass) | 0);
  }
  return mass;
}

// Colour for the local player's rocket sprite. Online: the player's
// server-assigned seat colour (the crew-card hex), so the rocket on
// the map matches their roster dot + turn banner + name tint. Solo:
// the legacy 'yellow' named palette. getRocketSprite accepts either a
// named key or a raw #rrggbb.
function myRocketColour() {
  if (_online && _onlineSnapshot && _onlineMe) {
    const me = (_onlineSnapshot.players || []).find((p) => p.profileId === mySeatId());
    if (me && me.color) return me.color;
  }
  return 'yellow';
}
// Is the card id an active TW/GW (Terawatt/Gigawatt) thruster? Drives the gold
// stripes on the rocket sprite. The class is the card type (TW is a future
// member of the same family); both faces of a GW card share the type.
function isGwThrusterId(id) {
  const card = id ? PATENTS_BY_ID[id] : null;
  return !!(card && card.type === 'gw-thruster');
}

// Publish the local player's seat colour as --me-color on the browse
// shell so the player's own chrome (top bar, hand strip, hand title)
// can tint to it - a persistent "you are this colour" cue. Cleared
// (removed) in solo so the sandbox keeps its default palette.
function syncMeColor(snapshot) {
  const shell = document.querySelector('.browse-shell');
  if (!shell) return;
  let color = null;
  if (_online && snapshot && Array.isArray(snapshot.players) && _onlineMe) {
    const me = snapshot.players.find((p) => p.profileId === mySeatId());
    const active = snapshot.players[snapshot.activeIndex];
    const myTurn = !!(active && active.profileId === mySeatId());
    // Only light the player's own seat-colour chrome ON THEIR TURN, so a
    // glance at the top bar / hand tells you whether it's your move. Off-
    // turn the chrome goes neutral (the bottom banner still names whose
    // turn it is, tinted in their colour).
    color = (myTurn && me && me.color) || null;
  }
  if (color) shell.style.setProperty('--me-color', color);
  else shell.style.removeProperty('--me-color');
  shell.classList.toggle('has-me-color', !!color);
}

// World-space coords for a server rocket siteId (null = LEO anchor).
// Translates the server slug -> planner node -> {x, y}.
function mpRocketCoords(serverSiteId) {
  if (!_activeData) return null;
  if (!serverSiteId) return { x: LEO_ANCHOR.x, y: LEO_ANCHOR.y };  // at LEO
  const pid = _onlineMaps && _onlineMaps.serverToPlanner.get(serverSiteId);
  const site = pid && (_activeData.byId?.[pid]
    || _activeData.sites.find((s) => s.id === pid));
  if (site && typeof site.x === 'number') return { x: site.x, y: site.y };
  return { x: LEO_ANCHOR.x, y: LEO_ANCHOR.y };  // unknown -> LEO
}

// Lay out every player's rocket on the map. Ships sharing a site are
// arranged in a CENTRED HORIZONTAL ROW (not a ring) so colocated
// rockets - everyone at LEO especially - line up side by side at the
// same size. The local player's own rocket keeps its full-featured
// draw (badges, hover, click) but gets a horizontal offset so it
// takes its slot in the row; opponents are colour-coded sprites with
// a 🚫 when inactive (no active thruster), mirroring the local cue.
const MP_ROCKET_SPACING = 30;   // screen px between colocated ships
// Lay out every player's rocket: the colocation row + local offset.
// Returns { opponents: [{profileId, x, y, offsetX, colour, name, inactive}],
// localOffsetX }. Factored out of syncMpRockets so the move animator can
// reuse the SAME final layout while it tweens one ship across the map.
// Shared colocation fan-out across ALL vehicle types - every player's rocket,
// freighter, and each Bernal. Previously each TYPE fanned out only among itself,
// so a rocket and a Bernal at the SAME node both centred and OVERLAPPED (user
// 2026-06-27). Grouping every vehicle at a node into one centred row fixes it.
// Keyed by server siteId (null = LEO) so colocation is exact (no coord rounding).
// Returns Map: 'r:<pid>' | 'f:<pid>' | 'b:<pid>:<i>'  ->  offsetX (screen px).
function computeColocationOffsets(snapshot) {
  const out = new Map();
  if (!snapshot || !Array.isArray(snapshot.players)) return out;
  const groups = new Map();
  const at = (sid) => sid || 'leo';
  const push = (siteKey, vkey, seat, order) => {
    if (!groups.has(siteKey)) groups.set(siteKey, []);
    groups.get(siteKey).push({ vkey, seat, order });
  };
  for (const p of snapshot.players) {
    const seat = p.seat || 0;
    // order keeps a node reading rocket, then freighter, then Bernals L-to-R.
    push(at(p.rocket && p.rocket.siteId), `r:${p.profileId}`, seat, 0);
    if (p.freighter) push(at(p.freighter.siteId), `f:${p.profileId}`, seat, 1);
    (Array.isArray(p.bernals) ? p.bernals : []).forEach((bn, i) => {
      if (bn) push(at(bn.siteId), `b:${p.profileId}:${i}`, seat, 2 + i);
    });
  }
  for (const group of groups.values()) {
    group.sort((a, b) => (a.seat - b.seat) || (a.order - b.order) || (a.vkey < b.vkey ? -1 : 1));
    const n = group.length;
    group.forEach((v, i) => out.set(v.vkey, (i - (n - 1) / 2) * MP_ROCKET_SPACING));
  }
  return out;
}
function computeMpRockets(snapshot) {
  const myId = mySeatId();
  const offsets = computeColocationOffsets(snapshot);
  const opponents = [];
  let localOffsetX = 0;
  for (const p of (snapshot && snapshot.players) || []) {
    const pos = mpRocketCoords(p.rocket && p.rocket.siteId);
    if (!pos) continue;
    const offsetX = offsets.get(`r:${p.profileId}`) || 0;   // shared row slot
    if (p.profileId === myId) { localOffsetX = offsetX; continue; }
    opponents.push({
      profileId: p.profileId, x: pos.x, y: pos.y, offsetX,
      colour: p.color || 'white', name: p.name,
      inactive: !(p.rocket && p.rocket.activeThrusterId),
      gw: isGwThrusterId(p.rocket && p.rocket.activeThrusterId),   // gold TW/GW stripes
      // Loaded glory chits this ship is carrying home (shown as a 🏆 badge).
      chits: (p.glory && Array.isArray(p.glory.chits)) ? p.glory.chits.length : 0,
    });
  }
  return { opponents, localOffsetX };
}

function syncMpRockets(snapshot) {
  if (!_renderer) return;
  if (!_online || !snapshot || !Array.isArray(snapshot.players) || !_onlineMe) {
    _renderer.setMpRockets(null);
    _renderer.setSandboxRocketOffset(0);
    syncFreighterUnit(snapshot);
    syncBernalUnits(snapshot);
    syncElevators(snapshot);
    syncMobileCubes(snapshot);
    return;
  }
  const { opponents, localOffsetX } = computeMpRockets(snapshot);
  _renderer.setSandboxRocketOffset(localOffsetX);
  _renderer.setMpRockets(opponents);
  syncFreighterUnit(snapshot);
  syncBernalUnits(snapshot);
  syncElevators(snapshot);
  syncMobileCubes(snapshot);
}

// Draw every in-transit Mobile Factory cube on the map (M1, rule 1B6): a cube
// that lifted off a Claim and is moving. Resolves each cube's current node to
// world coords; tinted by its owner. Cleared when m1 is off (zero-bleed).
function syncMobileCubes(snapshot) {
  if (!_renderer || typeof _renderer.setMobileCubes !== 'function') return;
  if (!_online || !snapshot || !isM1() || !Array.isArray(snapshot.mobileCubes)) { _renderer.setMobileCubes(null); return; }
  const out = [];
  for (const c of snapshot.mobileCubes) {
    const pos = mpRocketCoords(c.siteId);   // null siteId -> LEO anchor
    if (!pos) continue;
    out.push({ siteId: c.siteId, x: pos.x, y: pos.y, color: factoryOwnerColor(c.ownerId), tag: c.tag, glitched: !!c.glitched });
  }
  _renderer.setMobileCubes(out);
}

// Draw EVERY Space Elevator location on the map (M1): the cable + B marker always
// render (white) so players see where elevators sit; a BUILT one pops in the
// controlling player's seat colour with a drop shadow. Resolves each pair's two
// endpoint slugs to world coords. Cleared when m1 is off (zero-bleed).
// The player who has BUILT the GEO Space Elevator by anchoring the GEO Elevator
// Bernal at GEO (burn-geo). Mirrors the server's geoElevatorOwnerId: M2-gated,
// derived live from the anchor (no snapshot.elevators entry), so unanchoring
// drops it. Returns the player record (for its seat colour) or null.
function geoElevatorOwner(snapshot) {
  if (!snapshot || !isM2()) return null;
  for (const p of (snapshot.players || [])) {
    for (const bn of (p.bernals || [])) {
      if (bn && bn.cardId === 'ber_geo_elevator_bernal' && bn.anchored && bn.siteId === 'burn-geo') {
        return p;
      }
    }
  }
  return null;
}

function syncElevators(snapshot) {
  if (!_renderer || typeof _renderer.setElevators !== 'function') return;
  const geoOwner = geoElevatorOwner(snapshot);
  // The faint elevator GUIDES are an M1 feature; the GEO elevator is built by an
  // M2 Bernal anchor. Draw nothing unless at least one of those applies.
  if (!_online || !snapshot || (!isM1() && !geoOwner)) { _renderer.setElevators(null); return; }
  const built = snapshot.elevators || {};
  const out = [];
  for (const pair of elevatorPairs()) {
    // With M1 off, show ONLY the GEO elevator (the other pairs are M1 guides).
    if (!isM1() && !pair.geo) continue;
    const aPos = mpRocketCoords(pair.a);
    const bPos = mpRocketCoords(pair.b);
    if (!aPos || !bPos) continue;
    // The GEO pair is built implicitly by the anchored GEO Bernal (no entry in
    // snapshot.elevators); every other pair is built only via BUILD_ELEVATOR.
    const geoBuilt = !!(pair.geo && geoOwner);
    const e = built[pair.key];
    const owner = geoBuilt ? geoOwner
      : (e && (snapshot.players || []).find((p) => p.profileId === e.ownerId));
    out.push({
      ax: aPos.x, ay: aPos.y, bx: bPos.x, by: bPos.y,
      built: !!(e || geoBuilt),
      color: (owner && owner.color) || null,
      // Whether each end draws a site hexagon, so the renderer can stop the
      // cable at the hex edge (arrow not hidden behind the hex).
      aHex: elevatorEndIsHexSite(pair.a),
      bHex: elevatorEndIsHexSite(pair.b),
    });
  }
  _renderer.setElevators(out);
}

